    bundled_config = BUNDLE_ROOT / "app" / "config.json"
    if bundled_config.exists():
        try:
            CONFIG.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(bundled_config, CONFIG)
        except Exception:
            # load_config() will safely fall back to DEFAULT if the portable
            # folder is unexpectedly read-only.
            pass
