def find_executable(filename):
    # Prefer explicit files in either the live library root or this code release.
    for direct in [BASE/filename,CODE_ROOT/filename,BASE/"tools"/filename,CODE_ROOT/"tools"/filename]:
        if direct.exists():
            return direct
    matches=[]
    for search_root in [CODE_ROOT,BASE]:
        try:
            matches.extend(p for p in search_root.rglob(filename) if p.is_file())
        except Exception:
            pass
    if matches:
        matches=sorted(set(matches),key=lambda p:(len(p.parts),len(str(p))))
        return matches[0]
    return CODE_ROOT / filename

