def refresh_tool_paths():
    global YTDLP, FFMPEG, FFPROBE, DENO, OLLAMA
    YTDLP=find_executable("yt-dlp.exe")
    FFMPEG=find_executable("ffmpeg.exe")
    FFPROBE=find_executable("ffprobe.exe")
    DENO=find_executable("deno.exe")
    OLLAMA=find_executable("ollama.exe")

def tool_version(exe, args=None):
    if not exe.exists():
        return ""
    args=args or ["--version"]
    try:
        p=subprocess.run([str(exe)]+args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                         text=True,encoding="utf-8",errors="replace",timeout=20,
                         creationflags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0))
        out=(p.stdout or p.stderr).strip().splitlines()
        return out[0] if out else "Detected"
    except Exception:
        return "Detected"

def ollama_server_ok():
    try:
        with urllib.request.urlopen("http://127.0.0.1:11434/api/tags",timeout=2) as r:
            return r.status==200
    except Exception:
        return False

def ollama_model_ok(model):
    try:
        with urllib.request.urlopen("http://127.0.0.1:11434/api/tags",timeout=3) as r:
            data=json.loads(r.read().decode("utf-8"))
        names=[]
        for m in data.get("models",[]):
            names.append(m.get("name",""))
            names.append(m.get("model",""))
        return model in names or any(x.startswith(model.split(":")[0]+":") for x in names)
    except Exception:
        return False

def download_file(url,dest,label):
    TOOLS.mkdir(exist_ok=True)
    tmp=Path(str(dest)+".part")
    try:
        set_state(phase="Dependency download",current=label,current_file=dest.name,
                  current_status="DOWNLOADING TOOL",current_percent="",message=f"Downloading {label}")
        print(f"Downloading {label}...")
        req=urllib.request.Request(url,headers={"User-Agent":"Mozilla/5.0"})
        with urllib.request.urlopen(req,timeout=120) as r, open(tmp,"wb") as f:
            total=int(r.headers.get("Content-Length") or 0)
            done=0
            while True:
                chunk=r.read(1024*1024)
                if not chunk: break
                f.write(chunk); done+=len(chunk)
                if total:
                    pct=f"{done*100/total:.1f}%"
                    set_state(current_percent=pct)
        tmp.replace(dest)
        set_state(current_status="DOWNLOADED",current_percent="100%")
        return True,""
    except Exception as e:
        try: tmp.unlink(missing_ok=True)
        except Exception: pass
        log(f"Dependency download failed {label}: {e}")
        return False,str(e)

def extract_zip(zip_path,dest_dir,label):
    try:
        dest_dir.mkdir(parents=True,exist_ok=True)
        with pyzipfile.ZipFile(zip_path,"r") as z:
            z.extractall(dest_dir)
        return True,""
    except Exception as e:
        log(f"Dependency extraction failed {label}: {e}")
        return False,str(e)

def install_portable_tool(name,url):
    TOOLS.mkdir(exist_ok=True)
    if name=="yt-dlp":
        ok,err=download_file(url,TOOLS/"yt-dlp.exe","yt-dlp")
        refresh_tool_paths()
        return ok,err

    zip_dest=TOOLS/f"{name}.zip"
    ok,err=download_file(url,zip_dest,name)
    if not ok:
        return False,err
    extract_dir=TOOLS/name
    ok,err=extract_zip(zip_dest,extract_dir,name)
    if ok:
        try: zip_dest.unlink()
        except Exception: pass
    refresh_tool_paths()
    return ok,err

def start_ollama_server():
    refresh_tool_paths()
    if ollama_server_ok():
        return True
    if not OLLAMA.exists():
        return False
    try:
        flags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0)
        subprocess.Popen([str(OLLAMA),"serve"],cwd=str(OLLAMA.parent),
                         stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
                         creationflags=flags)
        for _ in range(20):
            time.sleep(0.5)
            if ollama_server_ok():
                return True
    except Exception as e:
        log(f"Could not start Ollama: {e}")
    return False

def pull_ollama_model(model):
    if not start_ollama_server():
        return False,"Ollama server could not be started"
    try:
        print(f"Downloading Ollama model {model}. This can be several GB.")
        flags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0)
        p=subprocess.Popen(
            [str(OLLAMA),"pull",model],cwd=str(OLLAMA.parent),
            creationflags=flags
        )
        rc=p.wait()
        return rc==0,("" if rc==0 else f"ollama pull returned {rc}")
    except Exception as e:
        return False,str(e)

def transcript_api_import():
    if str(PY_PACKAGES) not in sys.path:
        sys.path.insert(0,str(PY_PACKAGES))
    try:
        return importlib.import_module("youtube_transcript_api")
    except Exception:
        return None

def install_youtube_transcript_api():
    PY_PACKAGES.mkdir(parents=True,exist_ok=True)
    print("Installing youtube-transcript-api locally (no admin rights required)...")
    try:
        p=subprocess.run([sys.executable,"-m","pip","install","--upgrade","--target",str(PY_PACKAGES),"youtube-transcript-api"],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,encoding="utf-8",errors="replace",timeout=300,creationflags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0))
        output=(p.stdout or "")+"\n"+(p.stderr or "")
        log("youtube-transcript-api install: "+output[-3000:])
        if str(PY_PACKAGES) not in sys.path: sys.path.insert(0,str(PY_PACKAGES))
        importlib.invalidate_caches()
        return transcript_api_import() is not None,output[-1500:]
    except Exception as e:
        log(f"youtube-transcript-api install failed: {e}")
        return False,str(e)

def dependency_status():
    refresh_tool_paths()
    python_ok=True
    statuses=[
        {"tool":"Python","required":"Yes","status":"OK" if python_ok else "Missing","path":sys.executable,"version":sys.version.split()[0]},
        {"tool":"yt-dlp","required":"Yes","status":"OK" if YTDLP.exists() else "Missing","path":str(YTDLP) if YTDLP.exists() else "","version":tool_version(YTDLP)},
        {"tool":"FFmpeg","required":"For video merging","status":"OK" if FFMPEG.exists() else "Missing","path":str(FFMPEG) if FFMPEG.exists() else "","version":tool_version(FFMPEG,["-version"])},
        {"tool":"ffprobe","required":"Recommended","status":"OK" if FFPROBE.exists() else "Missing","path":str(FFPROBE) if FFPROBE.exists() else "","version":tool_version(FFPROBE,["-version"])},
        {"tool":"Deno","required":"Recommended for YouTube","status":"OK" if DENO.exists() else "Missing","path":str(DENO) if DENO.exists() else "","version":tool_version(DENO)},
        {"tool":"Ollama CLI","required":"For AI","status":"OK" if OLLAMA.exists() else "Missing","path":str(OLLAMA) if OLLAMA.exists() else "","version":tool_version(OLLAMA)},
    ]
    yta_ok=transcript_api_import() is not None
    statuses.append({"tool":"youtube-transcript-api","required":"Preferred transcript source","status":"OK" if yta_ok else "Missing","path":str(PY_PACKAGES),"version":""})
    server=ollama_server_ok()
    model=CFG.get("ollama_model","qwen2.5:7b")
    statuses.append({"tool":"Ollama server","required":"For AI","status":"OK" if server else "Not Running","path":"127.0.0.1:11434","version":""})
    statuses.append({"tool":f"Model {model}","required":"For AI","status":"OK" if server and ollama_model_ok(model) else "Missing/Unknown","path":"","version":""})
    return statuses

def print_dependency_status():
    rows=dependency_status()
    print("\nDEPENDENCY CHECK")
    print("="*100)
    print(f"{'Tool':<24}{'Required':<24}{'Status':<16}{'Version':<18}Path")
    print("-"*100)
    for r in rows:
        print(f"{r['tool']:<24}{r['required']:<24}{r['status']:<16}{r['version'][:16]:<18}{r['path']}")
    print("="*100)
    return rows

def dependency_setup_menu(interactive=True):
    rows=print_dependency_status()
    missing={r["tool"] for r in rows if r["status"]=="Missing"}
    urls=CFG.get("tool_download_urls",{})

    if interactive:
        print("""
Dependency actions:
1 = Download all missing portable tools
2 = Download/select tools individually
3 = Start Ollama server
4 = Pull configured Ollama model
5 = Install youtube-transcript-api locally
6 = Recheck
0 = Continue to main menu
""")
        while True:
            c=input("Choose [0]: ").strip() or "0"
            if c=="0": break
            if c=="1":
                refresh_tool_paths()
                jobs=[]
                if not YTDLP.exists(): jobs.append(("yt-dlp",urls.get("yt-dlp","")))
                if not DENO.exists(): jobs.append(("deno",urls.get("deno","")))
                if not FFMPEG.exists() or not FFPROBE.exists(): jobs.append(("ffmpeg",urls.get("ffmpeg","")))
                if not OLLAMA.exists(): jobs.append(("ollama",urls.get("ollama","")))
                for name,url in jobs:
                    if not url:
                        print(f"No download URL configured for {name}")
                        continue
                    ok,err=install_portable_tool(name,url)
                    print(f"{name}: {'OK' if ok else 'FAILED - '+err}")
                print_dependency_status()
            elif c=="2":
                print("1=yt-dlp  2=Deno  3=FFmpeg+ffprobe  4=Ollama")
                t=input("Choose tool: ").strip()
                mp={"1":"yt-dlp","2":"deno","3":"ffmpeg","4":"ollama"}
                name=mp.get(t)
                if name:
                    ok,err=install_portable_tool(name,urls.get(name,""))
                    print(f"{name}: {'OK' if ok else 'FAILED - '+err}")
                    print_dependency_status()
            elif c=="3":
                print("Ollama server:", "RUNNING" if start_ollama_server() else "FAILED")
                print_dependency_status()
            elif c=="4":
                model=CFG.get("ollama_model","qwen2.5:7b")
                ans=input(f"Pull model {model}? It may require several GB [y/N]: ").strip().lower()
                if ans=="y":
                    ok,err=pull_ollama_model(model)
                    print("Model:", "OK" if ok else f"FAILED - {err}")
                print_dependency_status()
            elif c=="5":
                ok,msg=install_youtube_transcript_api()
                print("youtube-transcript-api:", "OK" if ok else f"FAILED - {msg}")
                print_dependency_status()
            elif c=="6":
                print_dependency_status()
    return rows


def install_missing_core_portable_dependencies():
    """
    Install no-admin core media dependencies into the app's portable tools area.
    Ollama/model downloads remain optional and separate because they can be large.
    """
    refresh_tool_paths()
    urls=CFG.get("tool_download_urls",{}) if isinstance(CFG,dict) else {}
    results=[]
    jobs=[]
    if not YTDLP.exists(): jobs.append(("yt-dlp",urls.get("yt-dlp","")))
    if not DENO.exists(): jobs.append(("deno",urls.get("deno","")))
    if not FFMPEG.exists() or not FFPROBE.exists(): jobs.append(("ffmpeg",urls.get("ffmpeg","")))

    for name,url in jobs:
        if web_stop_requested():
            results.append({"tool":name,"ok":False,"message":"Stopped by user"})
            break
        if not url:
            results.append({"tool":name,"ok":False,"message":"No configured download URL"})
            continue
        ok,err=install_portable_tool(name,url)
        results.append({"tool":name,"ok":bool(ok),"message":"Installed" if ok else str(err)})

    if transcript_api_import() is None and not web_stop_requested():
        ok,msg=install_youtube_transcript_api()
        results.append({"tool":"youtube-transcript-api","ok":bool(ok),"message":"Installed" if ok else str(msg)})

    refresh_tool_paths()
    core_ok=bool(YTDLP.exists() and FFMPEG.exists() and FFPROBE.exists() and DENO.exists())
    failed=[x for x in results if not x.get("ok")]
    status="SUCCESS" if core_ok and not failed else ("WARN / ACTION REQUIRED" if core_ok or results else "FAILED")
    return {
        "ok":core_ok,
        "status":status,
        "message":"Core portable tools are ready." if core_ok else "One or more core portable tools are still missing.",
        "installed":results,
        "dependencies":dependency_status()
    }

