def maybe_update_ytdlp():
    if not YTDLP.exists():
        return False
    try:
        print("\nChecking yt-dlp update after YouTube 403...")
        p=subprocess.run([str(YTDLP),"-U"],stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                         text=True,encoding="utf-8",errors="replace",timeout=120,
                         creationflags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0))
        out=(p.stdout or p.stderr or "").strip()
        if out:
            print(out)
            log("yt-dlp update: "+out[-1000:])
        return p.returncode==0
    except Exception as e:
        log(f"yt-dlp update failed: {e}")
        return False

