def migrate_legacy_root_files():
    """
    Move legacy root files into canonical folders.
    Non-destructive on name collision: keep destination and suffix migrated copy.
    """
    ensure_project_layout()

    mappings={
        BASE/"video_library.db": BASE/"data"/"database"/"video_library.db",
        BASE/"video_library.rebuilt.db": BASE/"maintenance"/"recovery"/"video_library.rebuilt.db",
        BASE/"video_list.csv": BASE/"data"/"exports"/"video_list.csv",
        BASE/"video_list_with_chatgpt_titles.csv": BASE/"data"/"exports"/"video_list_with_chatgpt_titles.csv",
        BASE/"rename_review_results.csv": BASE/"maintenance"/"audits"/"rename_review_results.csv",

        BASE/"library_health.csv": BASE/"maintenance"/"audits"/"library_health.csv",
        BASE/"library_health_summary.json": BASE/"maintenance"/"audits"/"library_health_summary.json",
        BASE/"phase0_core_audit.csv": BASE/"maintenance"/"audits"/"phase0_core_audit.csv",
        BASE/"app.log": BASE/"logs"/"app.log",
        BASE/"package_history.csv": BASE/"data"/"chatgpt"/"package_history.csv",
        BASE/"phase2_integrity_audit.csv": BASE/"maintenance"/"audits"/"phase2_integrity_audit.csv",
        BASE/"phase3_summary_quality.csv": BASE/"maintenance"/"audits"/"phase3_summary_quality.csv",
        BASE/"phase4_content_intelligence.csv": BASE/"maintenance"/"audits"/"phase4_content_intelligence.csv",
    }

    moved=0
    skipped=0
    failed=0

    for old,new in mappings.items():
        try:
            if not old.exists():
                continue
            # A migration source must never be its own destination.  Treating
            # it as a duplicate would unlink the canonical file on startup.
            if old.resolve()==new.resolve():
                continue
            new.parent.mkdir(parents=True,exist_ok=True)

            if new.exists():
                # Preserve canonical destination; if same size, old can be removed safely.
                try:
                    if old.stat().st_size==new.stat().st_size:
                        old.unlink()
                        skipped+=1
                        continue
                except Exception:
                    pass

                suffix=1
                alt=new.with_name(f"{new.stem}_legacy{suffix}{new.suffix}")
                while alt.exists():
                    suffix+=1
                    alt=new.with_name(f"{new.stem}_legacy{suffix}{new.suffix}")
                shutil.move(str(old),str(alt))
            else:
                shutil.move(str(old),str(new))
            moved+=1
        except Exception as ex:
            failed+=1
            print(f"Legacy file migration failed: {old.name}: {ex}")

    print(f"Root file migration: moved={moved}, skipped duplicates={skipped}, failed={failed}")
    return moved,skipped,failed

