def video_table_columns():
    con=db_connect()
    rows=con.execute("PRAGMA table_info(videos)").fetchall()
    con.close()
    return {str(r[1]) for r in rows}

def select_existing_video_columns(preferred):
    """
    Return SQL expressions for requested fields, using NULL AS <name>
    when an older DB does not have that column.
    """
    existing=video_table_columns()
    parts=[]
    for name in preferred:
        if name in existing:
            parts.append(name)
        else:
            parts.append(f"NULL AS {name}")
    return ", ".join(parts)


