def rule_tags(title):
    t=(title or "").lower()
    found=[]
    for ent in CFG.get("known_entities",[]):
        if re.search(r'(?<!\w)'+re.escape(ent.lower())+r'(?!\w)',t):
            found.append(ent)
    return sorted(set(found))

def llm_generate(prompt,timeout=None):
    if not CFG.get("ai_enabled",True):
        return None

    if not ollama_server_ok():
        if not start_ollama_server():
            log("LLM skipped: Ollama server is not running")
            return None

    timeout = int(timeout or CFG.get("ollama_timeout_seconds",600))
    retries = max(1, int(CFG.get("ollama_retries",2)))

    payload=json.dumps({
        "model":CFG.get("ollama_model","qwen2.5:7b"),
        "prompt":prompt,
        "stream":False,
        "format":"json",
        "keep_alive":CFG.get("ollama_keep_alive","30m"),
        "options":{
            "temperature":0.1,
            "num_predict":int(CFG.get("ollama_num_predict",1400))
        }
    }).encode("utf-8")

    last_error=None
    for attempt in range(1,retries+1):
        req=urllib.request.Request(
            CFG.get("ollama_url"),
            data=payload,
            headers={"Content-Type":"application/json"}
        )
        try:
            set_state(
                current_status=f"OLLAMA PROCESSING ({attempt}/{retries})",
                message=f"Waiting for local LLM response; timeout {timeout}s"
            )
            started=time.time()
            with urllib.request.urlopen(req,timeout=timeout) as r:
                body=json.loads(r.read().decode("utf-8"))
            elapsed=time.time()-started
            log(f"LLM call completed in {elapsed:.1f}s")
            txt=body.get("response","").strip()
            return json.loads(txt)
        except Exception as e:
            last_error=e
            log(f"LLM attempt {attempt}/{retries} failed: {e}")
            set_state(
                current_status=f"OLLAMA RETRY {attempt}/{retries}",
                message=f"LLM attempt failed: {e}"
            )
            if attempt < retries:
                time.sleep(2*attempt)

    log(f"LLM exhausted retries: {last_error}")
    return None


def ai_enrich_title(title):
    rules=rule_tags(title)
    cats=", ".join(CFG.get("categories",[]))
    prompt=f"""Return only valid JSON.
Video title:
{title}

Allowed category must be exactly one of:
{cats}

Return:
{{
 "clean_title":"Natural concise ENGLISH title. If the source is Hindi, Hinglish, Punjabi or mixed language, translate it to clear English. Remove hashtags, emojis, decorative punctuation, channel/person promo suffixes, ALL-CAPS clickbait, repeated words, and claims like MUST WATCH when they add no topic meaning. Preserve the actual subject and important numbers.",
 "category":"one allowed category",
 "subcategory":"short useful subcategory",
 "main_topic":"main entity/topic",
 "tags":["specific useful tags"],
 "confidence":0.0,
 "needs_review":false
}}

The clean_title is used as the Windows folder and video filename, so it must be concise, descriptive, English and filename-safe.
Known rule-detected entities to retain as tags when relevant:
{rules}
"""
    d=llm_generate(prompt)
    if not d:
        return {
            "clean_title":safe_name(title),"category":"Other","subcategory":"",
            "main_topic":rules[0] if rules else "","tags":rules,
            "confidence":0.0,"needs_review":True
        }
    tags=d.get("tags") or []
    if isinstance(tags,str):
        tags=[x.strip() for x in tags.split(",") if x.strip()]
    tags=sorted(set([str(x).strip() for x in tags if str(x).strip()]+rules),key=str.lower)
    return {
        "clean_title":safe_name(d.get("clean_title") or title),
        "category":d.get("category") if d.get("category") in CFG.get("categories",[]) else "Other",
        "subcategory":str(d.get("subcategory") or ""),
        "main_topic":str(d.get("main_topic") or ""),
        "tags":tags,
        "confidence":float(d.get("confidence") or 0),
        "needs_review":bool(d.get("needs_review",False))
    }

