def parse_srt_sections(srt_text):
    """Parse standard SRT and malformed/inline SRT cues reliably."""
    txt=srt_text.replace("\r\n","\n").replace("\r","\n")

    # Standard SRT blocks first.
    standard=re.compile(
        r'(?ms)^\s*(?:\d+\s*\n)?'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*\n'
        r'(.*?)(?=\n{2,}|\Z)'
    )
    blocks=[]
    for m in standard.finditer(txt):
        body=re.sub(r'<[^>]+>',' ',m.group(3))
        body=re.sub(r'\s+',' ',html.unescape(body)).strip()
        if body:
            blocks.append((m.group(1).replace(".",","),m.group(2).replace(".",","),body))
    if blocks:
        return blocks

    # Fallback for timestamps that appear inline with transcript text.
    inline=re.compile(
        r'(?s)(?:^|\s)(?:\d+\s+)?'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*'
        r'(.*?)(?=(?:\s+\d+\s+)?\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->|$)'
    )
    for m in inline.finditer(txt):
        body=re.sub(r'<[^>]+>',' ',m.group(3))
        body=re.sub(r'\s+',' ',html.unescape(body)).strip()
        if body:
            blocks.append((m.group(1).replace(".",","),m.group(2).replace(".",","),body))
    if blocks:
        return blocks

    # Last-resort plain transcript.
    body=re.sub(r'(?m)^\s*\d+\s*$',' ',txt)
    body=re.sub(r'(?:^|\s)\d+\s+\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}[,.]\d{3}',' ',body)
    body=re.sub(r'\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}[,.]\d{3}',' ',body)
    body=re.sub(r'<[^>]+>',' ',body)
    body=re.sub(r'\s+',' ',html.unescape(body)).strip()
    return [("00:00:00,000","00:00:00,000",body)] if body else []

def subtitle_cleanup(text):
    t=text.replace("\r\n","\n").replace("\r","\n")
    t=re.sub(r'(?mi)^\s*WEBVTT.*$',' ',t)
    t=re.sub(r'(?m)^\s*\d+\s*$',' ',t)
    t=re.sub(r'(?<!\d)\d+\s+\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{1,2}:\d{2}:\d{2}[,.]\d{3}',' ',t)
    t=re.sub(r'\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{1,2}:\d{2}:\d{2}[,.]\d{3}',' ',t)
    t=re.sub(r'\d{1,2}:\d{2}[,.]\d{3}\s*-->\s*\d{1,2}:\d{2}[,.]\d{3}',' ',t)
    t=re.sub(r'<[^>]+>',' ',t)
    t=html.unescape(t)
    t=re.sub(r'\[(?:music|applause|laughter|foreign)\]',' ',t,flags=re.I)
    t=re.sub(r'\s+',' ',t).strip()
    return t

def sec(ts):
    try:
        h,m,sms=ts.replace(",",".").split(":")
        return int(h)*3600+int(m)*60+float(sms)
    except Exception: return 0

def hms(seconds):
    seconds=int(seconds)
    return f"{seconds//3600:02d}:{(seconds%3600)//60:02d}:{seconds%60:02d}"

def transcript_chunks(blocks,target_seconds=240):
    if not blocks: return []
    chunks=[]; cur=[]; start=sec(blocks[0][0]); end=start
    for b in blocks:
        bs,be=sec(b[0]),sec(b[1])
        if cur and be-start>target_seconds:
            chunks.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
            cur=[]; start=bs
        cur.append(b); end=be
    if cur:
        chunks.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
    return chunks



def deterministic_content_title(original_title, transcript_text):
    """Fallback transcript-based title using concrete foods/herbs/entities."""
    t=(transcript_text or "").lower()
    entity_map=[
        ("cumin","Cumin"),("jeera","Cumin"),("carom seeds","Carom Seeds"),
        ("carom","Carom Seeds"),("ajwain","Carom Seeds"),("fennel","Fennel"),
        ("saunf","Fennel"),("fenugreek","Fenugreek"),("methi","Fenugreek"),
        ("ceylon cinnamon","Ceylon Cinnamon"),("cinnamon","Cinnamon"),
        ("coriander","Coriander"),("dhania","Coriander"),("turmeric","Turmeric"),
        ("haldi","Turmeric"),("neem","Neem"),("tulsi","Tulsi"),
        ("holy basil","Tulsi"),("ashwagandha","Ashwagandha"),("amla","Amla"),
        ("giloy","Giloy"),("moringa","Moringa"),("kalonji","Kalonji"),
        ("nigella","Kalonji"),("kokum","Kokum"),("ginger","Ginger"),
        ("garlic","Garlic"),("lemon","Lemon"),("bitter gourd","Bitter Gourd"),
        ("karela","Bitter Gourd"),("curd","Curd"),("yogurt","Yogurt"),
        ("ghee","Ghee"),("milk","Milk"),("paneer","Paneer"),("sprouts","Sprouts"),
        ("peanut","Peanut"),("almond","Almond"),("walnut","Walnut"),
        ("chia","Chia Seeds"),("flax","Flax Seeds"),("sesame","Sesame Seeds"),
        ("apple cider vinegar","Apple Cider Vinegar")
    ]
    hits=[]
    for key,label in entity_map:
        m=re.search(r'(?<!\w)'+re.escape(key)+r'(?!\w)',t)
        if m: hits.append((m.start(),label))
    found=[]
    for _,label in sorted(hits):
        if label not in found: found.append(label)

    source=(original_title or "").lower()
    list_video=bool(re.search(r'\b\d+\s+.*\b(?:foods?|drinks?|herbs?|seeds?|products?|remedies)\b',source))
    weight=any(x in t for x in ["belly fat","weight loss","lose weight","burn fat","fat loss","obesity"])

    if found:
        names=", ".join(found[:5] if list_video else found[:4])
        if weight: return safe_name(f"{names} for Weight Management")
        return safe_name(names if list_video else f"{names} Health Guide")
    if weight: return "Foods and Remedies for Weight Management"
    return safe_name(original_title)


def ai_content_identity(original_title, transcript_text):
    """Create final English filename from actual transcript subjects."""
    sample=subtitle_cleanup((transcript_text or "")[:22000])
    prompt=f"""Return only valid JSON.

SOURCE TITLE:
{original_title}

CLEAN TRANSCRIPT EXCERPT:
{sample}

Create the FINAL ENGLISH FILE/FOLDER NAME from what the video actually discusses.

Rules:
- Do not merely rewrite/translate the source title.
- Extract concrete subjects from the transcript.
- For titles such as "5 Foods", "7 Drinks", "4 Seeds", "Best Herbs",
  "Products" or "Remedies", identify the ACTUAL named items in the transcript.
- Put the most important actual item names in meaningful_title when practical.
- Example: "5 Amazing Foods that Melt Belly Fat" should become something like
  "Cumin, Fennel, Fenugreek, Cinnamon and Amla for Weight Management" ONLY if
  those are actually the principal items discussed.
- Do not put an advertised/sponsored product in the filename unless the video
  is mainly about that product.
- Translate Hindi/Hinglish/Punjabi/other languages to natural English.
- Remove channel names, hashtags, emojis, hype, guarantees and clickbait.
- Prefer <= 120 characters.
- Never invent an item absent from the transcript.

Return:
{{
 "meaningful_title":"specific English filename using actual transcript subjects",
 "title_entities":["principal concrete names that belong in the filename"],
 "main_topic":"specific main subject",
 "summary":"2 to 4 sentence factual overview",
 "category":"broad category",
 "subcategory":"specific subcategory",
 "tags":["specific useful transcript-supported tags"]
}}
"""
    d=llm_generate(prompt)
    fallback=deterministic_content_title(original_title,transcript_text)
    if not d:
        return {"meaningful_title":fallback,"title_entities":[],"main_topic":"",
                "summary":"","category":"","subcategory":"","tags":[]}

    candidate=safe_name(d.get("meaningful_title") or "")
    source_clean=safe_name(original_title)
    entities=d.get("title_entities") or []
    if isinstance(entities,str):
        entities=[x.strip() for x in entities.split(",") if x.strip()]
    list_video=bool(re.search(r'(?i)\b\d+\s+.*\b(?:foods?|drinks?|herbs?|seeds?|products?|remedies)\b',
                              original_title or ""))
    vague=bool(re.search(r'(?i)\b(amazing|must try|shocking|surprise|melt belly fat|must watch|result will amaze)\b',
                         candidate))
    if not candidate or candidate.lower()==source_clean.lower() or vague or (list_video and not entities):
        candidate=fallback
    if len(candidate)>120:
        candidate=candidate[:120].rsplit(" ",1)[0].rstrip(" ,-_")
    d["meaningful_title"]=safe_name(candidate)
    d["title_entities"]=entities
    return d


def semantic_chapter_groups(blocks,max_seconds=None,max_chars=None):
    if not blocks:
        return []
    max_seconds=int(max_seconds or CFG.get("chapter_max_seconds",120))
    max_chars=int(max_chars or CFG.get("chapter_max_chars",3200))
    groups=[]; cur=[]; chars=0; start=sec(blocks[0][0]); end=start
    for b in blocks:
        bs,be=sec(b[0]),sec(b[1])
        cleaned=subtitle_cleanup(b[2])
        if not cleaned:
            continue
        if cur and ((be-start)>max_seconds or (chars+len(cleaned))>max_chars):
            groups.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
            cur=[]; chars=0; start=bs
        cur.append((b[0],b[1],cleaned)); chars+=len(cleaned)+1; end=be
    if cur:
        groups.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
    return groups

def ai_detailed_transcript(srt_text,title):
    blocks=parse_srt_sections(srt_text)
    groups=semantic_chapter_groups(blocks)
    chapters=[]
    for idx,c in enumerate(groups,1):
        cleaned=subtitle_cleanup(c["text"])
        prompt=f"""Return only valid JSON.

Video title:
{title}

Timestamp range:
{c['start']} to {c['end']}

Clean transcript:
{cleaned}

Create ONE coherent structured chapter.

Rules:
- Do not output raw transcript text.
- Do not use generic headings like Transcript Section, Chapter, or Section.
- Use a specific heading based on the actual topic in this range.
- Keep exact supplied timestamps.
- Treat health/scientific statements as speaker claims, not verified facts.

Return:
{{
 "chapter_title":"specific meaningful heading",
 "start":"{c['start']}",
 "end":"{c['end']}",
 "overview":"2 to 5 concise sentences",
 "topics":["specific subtopics"],
 "ingredients_or_entities":["explicit ingredients, people, products, medicines, devices or places"],
 "instructions":["explicit steps, quantities, timing or preparation instructions"],
 "claims":["important claims made by the speaker"],
 "key_points":["3 to 7 concise takeaways"],
 "tags":["specific tags"]
}}
"""
        d=llm_generate(prompt)
        if not d:
            set_state(
                current_status="LLM FALLBACK",
                message=f"LLM timed out or failed for {c['start']} - {c['end']}; using structured fallback."
            )
            words=cleaned.split()
            chapters.append({
                "chapter_title":f"Section {idx}",
                "start":c["start"],"end":c["end"],
                "overview":" ".join(words[:90]),
                "topics":[],"ingredients_or_entities":[],
                "instructions":[],"claims":[],"key_points":[],"tags":[]
            })
        else:
            d["start"]=c["start"]; d["end"]=c["end"]
            h=str(d.get("chapter_title") or "").strip()
            if not h or h.lower() in ("transcript section","chapter","section"):
                h=f"Section {idx}"
            d["chapter_title"]=h
            chapters.append(d)
    return chapters


