def staging_media_path(video_id):
    s=staging_dir(video_id,create=False)
    for pat in ("*.mp4","*.mkv","*.webm","*.mov","*.m4v"):
        found=next((p for p in s.glob(pat) if _nonzero_file(p)),None)
        if found:
            return found
    return None


def commit_staging_to_library(video_id,upload_date,title,channel):
    """
    Transaction-style move/merge after media validation.
    """
    vid=str(video_id)
    sdir=staging_dir(vid)
    media=staging_media_path(vid)

    if not media or not _nonzero_file(media):
        raise FileNotFoundError(f"Cannot commit staging: media missing for {vid}")

    final=video_folder_path(title,upload_date,channel,vid)
    final.mkdir(parents=True,exist_ok=True)
    fdata=final/"_data"
    fdata.mkdir(parents=True,exist_ok=True)

    # Move/merge media
    for p in list(sdir.iterdir()):
        if p.name=="_data":
            continue
        if not p.is_file():
            continue
        target=final/p.name
        if target.exists():
            try:
                if p.stat().st_size==target.stat().st_size:
                    p.unlink()
                    continue
            except Exception:
                pass
            target=final/f"{vid}{p.suffix}"
        shutil.move(str(p),str(target))

    # Move/merge support files
    sdata=sdir/"_data"
    if sdata.exists():
        for p in list(sdata.iterdir()):
            if not p.is_file():
                continue
            target=fdata/p.name
            if target.exists():
                try:
                    if p.stat().st_size==target.stat().st_size:
                        p.unlink()
                        continue
                except Exception:
                    pass
                target=fdata/f"{vid}_{int(time.time())}{p.suffix}"
            shutil.move(str(p),str(target))

    # keep staging dir only if something unresolved remains
    try:
        if sdata.exists() and not any(sdata.iterdir()):
            sdata.rmdir()
        if not any(sdir.iterdir()):
            sdir.rmdir()
    except Exception:
        pass

    media_final=find_any_media(final)
    refresh_db_artifact_paths(vid,final)
    return final




