def youtube_download_attempts(base_args,url,quality):
    """
    Return ordered command attempts.
    1) normal selected format
    2) web_safari client using HLS-friendly formats
    3) web_embedded fallback for embeddable videos
    """
    attempts=[]
    fmt=quality_selector(quality)
    attempts.append(("default", base_args + ["-f",fmt,url]))

    if CFG.get("youtube_403_fallback",True) and is_youtube_url(url):
        h=str(quality).lower()
        if h in ("best","audio"):
            hls_fmt="bestaudio/best" if h=="audio" else "best[protocol*=m3u8]/best"
        else:
            try:
                n=int(h)
                hls_fmt=f"best[protocol*=m3u8][height<={n}]/best[height<={n}]/best"
            except Exception:
                hls_fmt="best[protocol*=m3u8][height<=1080]/best[height<=1080]/best"

        for client in CFG.get("youtube_fallback_clients",["web_safari","web_embedded"]):
            args=list(base_args)
            args += ["--extractor-args",f"youtube:player_client={client}","-f",hls_fmt,url]
            attempts.append((client,args))
    return attempts

def run_video_with_fallback(base_args,url,quality,base_name):
    last_err=""
    updated=False
    attempts=youtube_download_attempts(base_args,url,quality)

    for idx,(label,args) in enumerate(attempts,1):
        set_state(
            current_status=f"VIDEO ATTEMPT {idx}/{len(attempts)} - {label}",
            message=f"Trying YouTube download strategy: {label}"
        )
        console_newline()
        print(f"Video download attempt {idx}/{len(attempts)}: {label}")
        rc,_,err=run_download_with_progress(args,base_name,"Video / Audio")
        last_err=err or ""
        if rc==0:
            return 0,"",label

        is403=("403" in last_err or "Forbidden" in last_err)
        if is403:
            log(f"403 on strategy {label}: {last_err[-1500:]}")
            if CFG.get("auto_update_ytdlp_on_403",True) and not updated:
                maybe_update_ytdlp()
                updated=True
            continue
        # For non-403 errors still try alternate YouTube strategy if available.
        log(f"Download strategy {label} failed: {last_err[-1500:]}")

    return 1,last_err,"all strategies failed"






def chatgpt_report_fingerprint(result_hash):
    """
    Report regeneration fingerprint includes BOTH the imported ChatGPT result
    and the current renderer/app version. This makes a new app version rebuild
    existing reports once even when the ChatGPT summary itself did not change.
    """
    return short_hash(f"{result_hash or ''}|renderer={APP_VERSION}")

def short_hash(text_value):
    return hashlib.sha256((text_value or "").encode("utf-8",errors="ignore")).hexdigest()

def normalize_hhmmss(value):
    """
    Accept HH:MM:SS or MM:SS and return HH:MM:SS.
    Reject invalid minute/second values.
    """
    raw=str(value or "").strip()
    if not raw:
        return None
    parts=raw.split(":")
    try:
        if len(parts)==2:
            h=0
            m=int(parts[0]); s=int(float(parts[1]))
        elif len(parts)==3:
            h=int(parts[0]); m=int(parts[1]); s=int(float(parts[2]))
        else:
            return None
    except Exception:
        return None
    if h<0 or m<0 or s<0 or m>=60 or s>=60:
        return None
    return f"{h:02d}:{m:02d}:{s:02d}"

def validate_and_normalize_sections(sections):
    """
    Normalize timestamps and reject only structurally invalid ranges.
    Overlap is valid because a recommendation/subtopic may legitimately sit
    inside a broader chapter. Overlaps are returned as warnings only.
    """
    normalized=[]
    errors=[]
    warnings=[]

    for idx,item in enumerate(sections or [],1):
        start=normalize_hhmmss(item.get("start"))
        end=normalize_hhmmss(item.get("end"))

        if not start or not end:
            errors.append(f"Section {idx}: invalid timestamp.")
            continue

        if sec(end) < sec(start):
            errors.append(f"Section {idx}: end before start ({start}-{end}).")
            continue

        clean=dict(item)
        clean["start"]=start
        clean["end"]=end
        normalized.append(clean)

    normalized.sort(key=lambda x:(sec(x["start"]),sec(x["end"])))

    for i in range(1,len(normalized)):
        prev=normalized[i-1]
        cur=normalized[i]
        if sec(cur["start"]) < sec(prev["end"]):
            warnings.append(
                f"Overlap allowed: {prev.get('chapter_title','Section')} "
                f"{prev['start']}-{prev['end']} overlaps "
                f"{cur.get('chapter_title','Section')} {cur['start']}-{cur['end']}."
            )

    return normalized,errors,warnings


def contains_substantial_devanagari(text_value, threshold=0.08):
    txt=str(text_value or "")
    letters=[c for c in txt if c.isalpha()]
    if not letters:
        return False
    dev=sum(1 for c in letters if '\u0900' <= c <= '\u097F')
    return dev/len(letters) >= threshold

def chatgpt_result_text(item):
    chunks=[
        str(item.get("meaningful_title") or ""),
        str(item.get("overall_summary") or item.get("summary") or "")
    ]
    for group in item.get("groups") or []:
        chunks.append(str(group.get("group_title") or ""))
        for entry in group.get("items") or []:
            chunks.extend([
                str(entry.get("title") or ""),
                str(entry.get("summary") or "")
            ])
            chunks.extend(str(x) for x in (entry.get("steps") or []))
    for secn in item.get("sections") or []:
        chunks.extend([
            str(secn.get("title") or ""),
            str(secn.get("detailed_summary") or secn.get("summary") or "")
        ])
        chunks.extend(str(x) for x in (secn.get("instructions") or []))
    return "\n".join(chunks)

def expected_package_video_ids(package_id):
    if not package_id:
        return None
    path=CHATGPT_PACKAGES/f"{package_id}.json"
    if not path.exists():
        return None
    try:
        data=json.loads(path.read_text(encoding="utf-8"))
        return {str(v.get("video_id") or "").strip() for v in (data.get("videos") or []) if str(v.get("video_id") or "").strip()}
    except Exception:
        return None

def archive_current_error(folder,base):
    err=support_dir(folder)/f"{base}.ERROR.txt"
    if not err.exists() or not CFG.get("archive_error_history",True):
        return
    hist=support_dir(folder)/"error_history"
    hist.mkdir(parents=True,exist_ok=True)
    stamp=datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    target=hist/f"{base}.{stamp}.ERROR.txt"
    try:
        shutil.move(str(err),str(target))
    except Exception:
        pass

def central_transcript_path(video_id, original_title, lang_code):
    max_chars=max(20,int(CFG.get("central_transcript_title_max_chars",80)))
    title=safe_name(original_title or video_id)[:max_chars].rstrip(" ._-")
    lang=(lang_code or "unknown").replace("/","-")
    return ALL_TRANSCRIPTS/f"{video_id}__{title}__{lang}.txt"


def copy_transcript_to_central_folder(video_id, original_title):
    p=temp_paths(video_id)
    en_path=p["dir"]/f"{video_id}.timestamped.en.txt"
    src_path=p["timestamped"]

    con=db_connect()
    row=con.execute(
        "SELECT subtitle_base_lang FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()

    lang=((row[0] if row else "") or "unknown").split("-")[0].lower()
    chosen=None
    chosen_lang=lang
    if en_path.exists() and en_path.stat().st_size>0:
        chosen=en_path
        chosen_lang="en"
    elif src_path.exists() and src_path.stat().st_size>0:
        chosen=src_path

    if not chosen:
        return None

    out=central_transcript_path(video_id,original_title,chosen_lang)
    for old in ALL_TRANSCRIPTS.glob(f"{video_id}__*.txt"):
        if old != out:
            try: old.unlink()
            except Exception: pass
    shutil.copy2(chosen,out)
    return out

def set_video_final_status(video_id,status,reason=""):
    con=db_connect()
    con.execute(
        "UPDATE videos SET final_status=?,failure_reason=? WHERE video_id=?",
        (status,reason or "",video_id)
    )
    con.commit()
    con.close()


def latest_video_error_details(folder,base=""):
    """
    Return the most useful real failure text available for a video.
    """
    folder=Path(folder)
    candidates=[]
    try:
        data=support_dir(folder)
        if data.exists():
            candidates.extend(sorted(
                data.glob("*.ERROR.txt"),
                key=lambda p:p.stat().st_mtime if p.exists() else 0,
                reverse=True
            ))
    except Exception:
        pass

    # legacy location fallback
    try:
        candidates.extend(sorted(
            folder.glob("*.ERROR.txt"),
            key=lambda p:p.stat().st_mtime if p.exists() else 0,
            reverse=True
        ))
    except Exception:
        pass

    for p in candidates:
        try:
            txt=p.read_text(encoding="utf-8",errors="replace").strip()
            if txt:
                return txt[-8000:]
        except Exception:
            pass
    return ""

def read_video_error_reason(folder,base):
    err=support_dir(folder)/f"{base}.ERROR.txt"
    if not err.exists():
        return ""
    try:
        lines=[x.strip() for x in err.read_text(encoding="utf-8",errors="replace").splitlines() if x.strip()]
        return " | ".join(lines[-8:])[:1200]
    except Exception:
        return ""





def temp_short_video_root():
    """
    Separate temporary area for YouTube Shorts / short-form videos.
    """
    p=BASE/"tmp"/"short_videos"
    p.mkdir(parents=True,exist_ok=True)
    return p


def is_short_video_record(video_id="",url="",duration_seconds=None):
    """
    Detect Shorts primarily from URL, then duration as fallback.
    YouTube Shorts URL is authoritative. Duration <= 180 seconds is treated
    as short-form when URL classification is unavailable.
    """
    u=str(url or "").lower()
    if "/shorts/" in u:
        return True
    try:
        if duration_seconds is not None and float(duration_seconds)>0:
            return float(duration_seconds)<=180
    except Exception:
        pass
    return False


def short_video_temp_dir(video_id):
    p=temp_short_video_root()/str(video_id)
    p.mkdir(parents=True,exist_ok=True)
    return p

