def phase1_dirs():
    maintenance=BASE/CFG.get("maintenance_root","maintenance")
    q=BASE/CFG.get("repair_quarantine_folder","maintenance/quarantine")
    b=BASE/CFG.get("repair_backup_folder","maintenance/backups")
    h=BASE/CFG.get("repair_history_folder","maintenance/repair_history")
    a=BASE/CFG.get("repair_audit_folder","maintenance/audits")
    r=BASE/CFG.get("repair_recovery_folder","maintenance/recovery")
    for p in (maintenance,q,b,h,a,r):
        p.mkdir(parents=True,exist_ok=True)
    return q,b,h,a,r


def phase1_migrate_legacy_maintenance_folders():
    q,b,h,a,r=phase1_dirs()
    mappings=[
        (BASE/"_quarantine",q),
        (BASE/"_backups",b),
        (BASE/"_repair_history",h),
    ]
    moved=0
    failed=0
    for old,dest in mappings:
        if not old.exists():
            continue
        try:
            for item in list(old.iterdir()):
                target=dest/item.name
                if target.exists():
                    stamp=time.strftime("%Y%m%d-%H%M%S")
                    target=dest/f"{item.stem}_{stamp}{item.suffix}"
                shutil.move(str(item),str(target))
                moved+=1
            try:
                old.rmdir()
            except Exception:
                pass
        except Exception as ex:
            failed+=1
            print(f"FAILED migrating {old}: {ex}")
    print(f"Maintenance migration complete. Moved: {moved}, Failed: {failed}")
    print(f"New root: {BASE/'maintenance'}")
    return moved,failed


def repair_original_title_markers():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,original_title,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    filled=0
    created=0
    skipped=0
    failed=0

    for vid,original_title,db_folder in rows:
        title=str(original_title or "").strip()
        if not title:
            skipped+=1
            continue

        folder=locate_existing_folder(vid)
        if folder is None and db_folder:
            p=Path(db_folder)
            if p.exists():
                folder=p
        if folder is None:
            failed+=1
            continue

        folder=Path(folder)
        markers=[find_original_title_marker(folder)] if find_original_title_marker(folder) else []
        try:
            if markers:
                marker=markers[0]
                current=marker.read_text(encoding="utf-8",errors="ignore").strip()
                if not current:
                    marker.write_text(title,encoding="utf-8")
                    filled+=1
                else:
                    skipped+=1
            else:
                marker=find_original_title_marker(folder)
                marker.write_text(title,encoding="utf-8")
                created+=1
        except Exception:
            failed+=1

    print("Original-title repair complete")
    print(f"Filled empty : {filled}")
    print(f"Created      : {created}")
    print(f"Skipped      : {skipped}")
    print(f"Failed       : {failed}")
    return filled,created,failed


def phase1_file_hash(path,limit_mb=64):
    p=Path(path)
    if not p.exists() or not p.is_file():
        return ""
    h=hashlib.sha256()
    try:
        with open(p,"rb") as f:
            remaining=limit_mb*1024*1024
            while remaining>0:
                chunk=f.read(min(1024*1024,remaining))
                if not chunk: break
                h.update(chunk)
                remaining-=len(chunk)
        return h.hexdigest()
    except Exception:
        return ""

def phase1_scan_library():
    """
    Full Phase 1 integrity scan.
    Writes:
      library_health.csv
      library_health_summary.json
    """
    _,_,hist,audit_dir,recovery_dir=phase1_dirs()
    rows_out=[]
    summary={
        "videos":0,"pass":0,"warn":0,"fail":0,
        "missing_video":0,"missing_report":0,"missing_transcript":0,
        "zero_byte":0,"db_path_mismatch":0,"duplicate_video_id":0,
        "orphan_folders":0,"orphan_files":0
    }

    con=db_connect()
    cols=video_table_columns()
    wanted=[
        "video_id","original_title","clean_title","channel","upload_date",
        "local_folder","local_video","report_html","transcript_original",
        "transcript_clean","transcript_detailed","subtitle_file",
        "chatgpt_summary_file","chatgpt_imported","final_status","failure_reason"
    ]
    sql=select_existing_video_columns(wanted)
    dbrows=con.execute(f"SELECT {sql} FROM videos ORDER BY rowid").fetchall()
    con.close()

    known_ids=set()
    known_folders=set()

    def add(vid,check,status,reason="",path=""):
        rows_out.append({
            "Video ID":vid,"Check":check,"Status":status,
            "Reason":reason,"Path":str(path or "")
        })
        if status=="FAIL": summary["fail"]+=1
        elif status=="WARN": summary["warn"]+=1
        else: summary["pass"]+=1

    for row in dbrows:
        summary["videos"]+=1
        (
            vid,orig,clean,channel,upload_date,local_folder,local_video,report_html,
            transcript_original,transcript_clean,transcript_detailed,subtitle_file,
            chatgpt_summary_file,chatgpt_imported,final_status,failure_reason
        )=row
        known_ids.add(str(vid))

        folder=locate_existing_folder(vid)
        if folder:
            folder=Path(folder)
            known_folders.add(str(folder.resolve()))
            add(vid,"Folder","PASS",path=folder)
        else:
            add(vid,"Folder","FAIL","Folder not found")
            continue

        # DB folder path
        if local_folder and Path(local_folder).exists():
            if Path(local_folder).resolve()!=folder.resolve():
                summary["db_path_mismatch"]+=1
                add(vid,"DB local_folder","WARN","DB path differs from Video-ID resolved folder",local_folder)
            else:
                add(vid,"DB local_folder","PASS",path=local_folder)
        else:
            summary["db_path_mismatch"]+=1
            add(vid,"DB local_folder","WARN","Missing/stale DB folder path",local_folder or "")

        # Video
        media=find_any_media(folder)
        if not media:
            summary["missing_video"]+=1
            add(vid,"Video","FAIL","No media file found")
        elif media.stat().st_size==0:
            summary["zero_byte"]+=1
            add(vid,"Video","FAIL","Zero-byte media file",media)
        else:
            add(vid,"Video","PASS",path=media)
            if local_video and Path(local_video).exists():
                if Path(local_video).resolve()!=media.resolve():
                    summary["db_path_mismatch"]+=1
                    add(vid,"DB local_video","WARN","DB video path differs from actual media",local_video)
            else:
                summary["db_path_mismatch"]+=1
                add(vid,"DB local_video","WARN","Missing/stale DB video path",local_video or "")

        # .video_id marker
        marker=support_dir(folder)/".video_id"
        if not marker.exists():
            add(vid,".video_id","FAIL","Missing marker",marker)
        else:
            marker_vid=marker.read_text(encoding="utf-8",errors="ignore").strip()
            add(vid,".video_id","PASS" if marker_vid==str(vid) else "FAIL",
                "" if marker_vid==str(vid) else f"Marker contains {marker_vid}",marker)

        # transcripts
        ts=list(support_dir(folder).glob("*.transcript_timestamped.txt"))
        clean=list(support_dir(folder).glob("*.transcript_clean.txt"))
        if not ts or ts[0].stat().st_size==0:
            summary["missing_transcript"]+=1
            add(vid,"Timestamped Transcript","FAIL","Missing/zero-byte")
        else:
            add(vid,"Timestamped Transcript","PASS",path=ts[0])
        if not clean or clean[0].stat().st_size==0:
            summary["missing_transcript"]+=1
            add(vid,"Clean Transcript","FAIL","Missing/zero-byte")
        else:
            add(vid,"Clean Transcript","PASS",path=clean[0])

        # report
        reports=list(folder.glob("*.report.html"))
        report=Path(report_html) if report_html and Path(report_html).exists() else (reports[0] if reports else None)
        if not report or report.stat().st_size==0:
            summary["missing_report"]+=1
            add(vid,"HTML Report","FAIL","Missing/zero-byte")
        else:
            add(vid,"HTML Report","PASS",path=report)
            if media:
                try:
                    body=report.read_text(encoding="utf-8",errors="replace")
                    if media.name in body:
                        add(vid,"HTML Video Link","PASS",path=media.name)
                    else:
                        add(vid,"HTML Video Link","FAIL",f"Report does not reference current media {media.name}",report)
                except Exception as ex:
                    add(vid,"HTML Video Link","FAIL",str(ex),report)

        # ChatGPT canonical summary when imported
        if int(chatgpt_imported or 0)==1:
            canonical=canonical_chatgpt_summary_path(folder,vid)
            if not canonical.exists() or canonical.stat().st_size==0:
                add(vid,"ChatGPT Summary","FAIL","Imported flag set but canonical summary missing",canonical)
            else:
                try:
                    obj=json.loads(canonical.read_text(encoding="utf-8"))
                    file_vid=str(obj.get("video_id") or "").strip()
                    if file_vid and file_vid!=str(vid):
                        add(vid,"ChatGPT Summary","FAIL",f"Video ID mismatch: {file_vid}",canonical)
                    else:
                        add(vid,"ChatGPT Summary","PASS",path=canonical)
                except Exception as ex:
                    add(vid,"ChatGPT Summary","FAIL",f"Invalid JSON: {ex}",canonical)

        # zero-byte support files
        for fp in support_dir(folder).iterdir():
            if fp.is_file() and fp.stat().st_size==0:
                summary["zero_byte"]+=1
                add(vid,"Zero-byte File","WARN","Zero-byte support file",fp)

    # duplicate markers / orphan folders
    marker_map={}
    if DOWNLOADS.exists():
        for marker in DOWNLOADS.rglob(".video_id"):
            try:
                vid=marker.read_text(encoding="utf-8",errors="ignore").strip()
                folder=marker.parent.parent if marker.parent.name=="_data" else marker.parent
                marker_map.setdefault(vid,[]).append(folder)
            except Exception:
                pass

    for vid,folders in marker_map.items():
        if len(folders)>1:
            summary["duplicate_video_id"]+=1
            for f in folders:
                add(vid,"Duplicate Video ID","WARN",f"{len(folders)} folders contain this Video ID",f)

    for vid,folders in marker_map.items():
        for folder in folders:
            resolved=str(Path(folder).resolve())
            if vid not in known_ids:
                summary["orphan_folders"]+=1
                rows_out.append({
                    "Video ID":vid,"Check":"Orphan Folder","Status":"WARN",
                    "Reason":"Folder marker not represented in SQLite","Path":str(folder)
                })

    # folders with no .video_id at all
    if DOWNLOADS.exists():
        for p in DOWNLOADS.iterdir():
            if not p.is_dir(): continue
            # channel parent; scan child folders
            for child in p.iterdir():
                if child.is_dir() and child.name!="_data":
                    marker=child/"_data"/".video_id"
                    if not marker.exists() and any(child.glob("*.mp4")):
                        summary["orphan_folders"]+=1
                        rows_out.append({
                            "Video ID":"","Check":"Orphan Folder","Status":"WARN",
                            "Reason":"Media folder has no .video_id marker","Path":str(child)
                        })

    output=audit_dir/"library_health.csv"
    with open(output,"w",newline="",encoding="utf-8-sig") as f:
        fields=["Video ID","Check","Status","Reason","Path"]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        w.writerows(rows_out)

    (audit_dir/"library_health_summary.json").write_text(
        json.dumps(summary,indent=2),encoding="utf-8"
    )

    print("")
    print("===== LIBRARY HEALTH =====")
    print(f"Videos              : {summary['videos']}")
    print(f"PASS checks         : {summary['pass']}")
    print(f"WARN checks         : {summary['warn']}")
    print(f"FAIL checks         : {summary['fail']}")
    print(f"Missing video       : {summary['missing_video']}")
    print(f"Missing report      : {summary['missing_report']}")
    print(f"Missing transcript  : {summary['missing_transcript']}")
    print(f"Zero-byte files     : {summary['zero_byte']}")
    print(f"DB path mismatches  : {summary['db_path_mismatch']}")
    print(f"Duplicate Video IDs : {summary['duplicate_video_id']}")
    print(f"Orphan folders      : {summary['orphan_folders']}")
    print(f"Details             : {output}")
    return output,summary

def phase1_fix_db_paths():
    """Safe repair: synchronize SQLite paths to the actual Video-ID-resolved folder/media/report."""
    con=db_connect()
    rows=con.execute("SELECT video_id FROM videos ORDER BY rowid").fetchall()
    con.close()

    fixed=0; skipped=0; failed=0
    for (vid,) in rows:
        folder=locate_existing_folder(vid)
        if not folder:
            failed+=1
            print(f"FAILED {vid}: folder not found")
            continue
        folder=Path(folder)
        media=find_any_media(folder)
        reports=list(folder.glob("*.report.html"))
        report=reports[0] if reports else None

        con=db_connect()
        con.execute(
            "UPDATE videos SET local_folder=?,local_video=?,report_html=? WHERE video_id=?",
            (str(folder),str(media) if media else "",str(report) if report else "",vid)
        )
        con.commit(); con.close()
        fixed+=1
    export_csv()
    print(f"DB path repair complete. Fixed: {fixed}, Failed: {failed}")
    return fixed,failed

def phase1_repair_video_id_markers():
    """Safe repair: recreate missing _data/.video_id using the SQLite Video ID."""
    con=db_connect()
    rows=con.execute("SELECT video_id,local_folder FROM videos ORDER BY rowid").fetchall()
    con.close()
    fixed=0; skipped=0; failed=0
    for vid,db_folder in rows:
        folder=locate_existing_folder(vid)
        if not folder and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)
        if not folder:
            failed+=1; continue
        marker=support_dir(folder)/".video_id"
        if marker.exists() and marker.read_text(encoding="utf-8",errors="ignore").strip()==str(vid):
            skipped+=1; continue
        try:
            marker.write_text(str(vid),encoding="utf-8")
            fixed+=1
        except Exception:
            failed+=1
    print(f".video_id repair complete. Fixed: {fixed}, Skipped: {skipped}, Failed: {failed}")
    return fixed,failed

def phase1_quarantine_zero_byte_files():
    """
    Safe cleanup: MOVE zero-byte files to quarantine; never delete them.
    """
    quarantine,_,_,_,_=phase1_dirs()
    repair_original_title_markers()
    stamp=time.strftime("%Y%m%d-%H%M%S")
    dest=quarantine/f"zero_byte_{stamp}"
    moved=0; failed=0
    for p in DOWNLOADS.rglob("*") if DOWNLOADS.exists() else []:
        try:
            if p.is_file() and p.stat().st_size==0:
                if p.name.lower().endswith(".original-title"):
                    continue
                rel=p.relative_to(DOWNLOADS)
                target=dest/rel
                target.parent.mkdir(parents=True,exist_ok=True)
                shutil.move(str(p),str(target))
                moved+=1
        except Exception:
            failed+=1
    print(f"Zero-byte quarantine complete. Moved: {moved}, Failed: {failed}")
    print(f"Quarantine: {dest}")
    return moved,failed

def phase1_repair_missing_reports():
    """
    Rebuild only missing/broken reports when enough local data exists.
    Uses canonical ChatGPT summary when available.
    """
    con=db_connect()
    rows=con.execute("SELECT video_id FROM videos ORDER BY rowid").fetchall()
    con.close()
    repaired=0; skipped=0; failed=0

    for (vid,) in rows:
        folder=locate_existing_folder(vid)
        if not folder:
            failed+=1; continue
        folder=Path(folder)
        reports=list(folder.glob("*.report.html"))
        media=find_any_media(folder)
        broken=(not reports or not reports[0].exists() or reports[0].stat().st_size==0)
        if not broken and media:
            try:
                body=reports[0].read_text(encoding="utf-8",errors="replace")
                broken=media.name not in body
            except Exception:
                broken=True
        if not broken:
            skipped+=1; continue

        summary_obj,summary_path=load_chatgpt_summary_for_video(vid)
        if not summary_obj:
            failed+=1
            print(f"FAILED {vid}: no canonical ChatGPT summary available")
            continue

        try:
            title=resolved_approved_title(vid)
            ok,msg=rebuild_report_after_rename(vid,folder,title)
            if ok:
                repaired+=1
                print(f"REPAIRED {vid}: {msg}")
            else:
                failed+=1
                print(f"FAILED {vid}: {msg}")
        except Exception as ex:
            failed+=1
            print(f"FAILED {vid}: {ex}")

    print(f"Report repair complete. Repaired: {repaired}, Skipped: {skipped}, Failed: {failed}")
    return repaired,failed

def phase1_backup_library_metadata():
    """
    Portable backup excluding large media:
      DB + config + CSVs + ChatGPT summaries + transcripts + report HTMLs + markers.
    """
    _,backup_root,_,_,_=phase1_dirs()
    stamp=time.strftime("%Y%m%d-%H%M%S")
    target=backup_root/f"metadata_backup_{stamp}"
    target.mkdir(parents=True,exist_ok=True)

    # Core files
    for p in [DB,cfgp if False else BASE/"app"/"config.json",main_video_csv_path(),reviewed_titles_csv_path()]:
        try:
            p=Path(p)
            if p.exists():
                shutil.copy2(p,target/p.name)
        except Exception:
            pass

    # Lightweight per-video data only
    data_root=target/"video_data"
    for marker in DOWNLOADS.rglob(".video_id") if DOWNLOADS.exists() else []:
        try:
            folder=marker.parent.parent if marker.parent.name=="_data" else marker.parent
            vid=marker.read_text(encoding="utf-8",errors="ignore").strip()
            vdest=data_root/vid
            vdest.mkdir(parents=True,exist_ok=True)

            # report
            for rp in folder.glob("*.report.html"):
                shutil.copy2(rp,vdest/rp.name)

            # selected _data artifacts
            for fp in support_dir(folder).iterdir():
                if not fp.is_file(): continue
                low=fp.name.lower()
                keep=(
                    low==".video_id"
                    or low.endswith(".json")
                    or "transcript" in low
                    or low.endswith(".description")
                    or low.endswith(".original-title")
                    or "chatgpt_summary" in low
                )
                if keep:
                    shutil.copy2(fp,vdest/fp.name)
        except Exception:
            pass

    # zip backup
    zip_path=backup_root/f"metadata_backup_{stamp}.zip"
    shutil.make_archive(str(zip_path.with_suffix("")),"zip",target)
    shutil.rmtree(target,ignore_errors=True)

    # retention
    backups=sorted(backup_root.glob("metadata_backup_*.zip"),key=lambda p:p.stat().st_mtime,reverse=True)
    keep=int(CFG.get("repair_keep_backup_count",5))
    for old in backups[keep:]:
        try: old.unlink()
        except Exception: pass

    print(f"Backup created: {zip_path}")
    return zip_path

def phase1_rebuild_db_from_folders():
    """
    Conservative DB rebuild helper.
    It DOES NOT replace the current DB automatically.
    Creates video_library.rebuilt.db from folders/markers/info.json.
    """
    _,backup_root,_,_,_=phase1_dirs()
    _,_,_,_,recovery_dir=phase1_dirs()
    rebuilt=recovery_dir/"video_library.rebuilt.db"
    if rebuilt.exists():
        rebuilt.unlink()

    con=sqlite3.connect(rebuilt)
    con.execute("""
      CREATE TABLE videos(
        video_id TEXT PRIMARY KEY,
        platform TEXT,url TEXT,original_title TEXT,clean_title TEXT,
        channel TEXT,upload_date TEXT,description TEXT,
        downloaded INTEGER DEFAULT 0,local_folder TEXT,local_video TEXT,
        report_html TEXT,final_status TEXT,failure_reason TEXT
      )
    """)

    count=0
    for marker in DOWNLOADS.rglob(".video_id") if DOWNLOADS.exists() else []:
        try:
            vid=marker.read_text(encoding="utf-8",errors="ignore").strip()
            folder=marker.parent.parent if marker.parent.name=="_data" else marker.parent
            info_files=list(support_dir(folder).glob("*.info.json"))
            info={}
            if info_files:
                try: info=json.loads(info_files[0].read_text(encoding="utf-8",errors="replace"))
                except Exception: info={}
            media=find_any_media(folder)
            reports=list(folder.glob("*.report.html"))
            title=(
                info.get("title")
                or (media.stem if media else folder.name)
            )
            channel=info.get("channel") or info.get("uploader") or folder.parent.name
            upload_date=str(info.get("upload_date") or "")
            if re.fullmatch(r"\d{8}",upload_date):
                upload_date=f"{upload_date[:4]}-{upload_date[4:6]}-{upload_date[6:8]}"
            url=info.get("webpage_url") or info.get("original_url") or ""
            desc=info.get("description") or ""

            con.execute("""
              INSERT OR REPLACE INTO videos(
                video_id,platform,url,original_title,clean_title,channel,upload_date,
                description,downloaded,local_folder,local_video,report_html,
                final_status,failure_reason
              ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,(
                vid,"youtube",url,title,title,channel,upload_date,desc,
                1 if media else 0,str(folder),str(media or ""),
                str(reports[0]) if reports else "",
                "PASS" if media else "WARN",""
            ))
            count+=1
        except Exception:
            pass

    con.commit(); con.close()
    print(f"Rebuilt DB candidate created: {rebuilt}")
    print(f"Recovered folder records: {count}")
    print("Current video_library.db was NOT replaced.")
    return rebuilt


def one_click_recovery_roots():
    """Find likely old/current library roots without recursively scanning whole drives."""
    roots=[]
    def add(p):
        try:
            p=Path(p).resolve()
        except Exception:
            return
        if p.exists() and p.is_dir() and p not in roots:
            roots.append(p)

    add(BASE);add(CODE_ROOT)
    try:
        for item in (BASE_RESOLUTION.get("candidates") or []):
            add(item.get("path"))
    except Exception:
        pass

    for parent in [BASE.parent,CODE_ROOT.parent,BASE.parent.parent,CODE_ROOT.parent.parent]:
        try:
            if not parent.exists():continue
            for child in parent.iterdir():
                if not child.is_dir():continue
                low=child.name.lower().replace("_","").replace("-","").replace(" ","")
                useful=(child/"downloads").exists() or (child/"data"/"database").exists()
                if useful and ("videolibrary" in low or "youtube" in low or "librarymanager" in low):
                    add(child)
        except Exception:
            pass
    return roots

def one_click_recovery_package_missing_ids():
    """Best-effort list of VIDEO_IDs referenced by ChatGPT packages but absent from SQLite."""
    ids=set()
    try:
        dirs=phase2_all_package_dirs()
    except Exception:
        dirs=[]
    def walk(obj):
        if isinstance(obj,dict):
            for k,v in obj.items():
                lk=str(k).lower()
                if lk=="video_id" and isinstance(v,(str,int)):
                    s=str(v).strip()
                    if s:ids.add(s)
                elif lk=="video_ids" and isinstance(v,list):
                    for x in v:
                        s=str(x).strip()
                        if s:ids.add(s)
                else:
                    walk(v)
        elif isinstance(obj,list):
            for x in obj:walk(x)
    for d in dirs:
        try:
            for p in Path(d).glob("*.json"):
                if p.stat().st_size>80*1024*1024:continue
                try:walk(json.loads(p.read_text(encoding="utf-8",errors="replace")))
                except Exception:pass
        except Exception:
            pass

    con=db_connect()
    current={str(r[0]) for r in con.execute("SELECT video_id FROM videos").fetchall()}
    con.close()
    return sorted(x for x in ids if x not in current and re.fullmatch(r"[A-Za-z0-9_-]{11}",str(x or "").strip()))


def one_click_extract_backup_databases(roots,stamp):
    """Extract old video_library.db copies from portable metadata backup ZIPs."""
    recovery=BASE/"maintenance"/"recovery"/"extracted_db_backups"/stamp
    recovery.mkdir(parents=True,exist_ok=True)
    out=[]
    zips=[]
    for root in roots:
        for pattern in [
            root/"maintenance"/"backups",
            root/"maintenance"/"repair"/"backups",
            root/"backups",
        ]:
            try:
                if pattern.is_dir():
                    zips.extend(pattern.glob("metadata_backup_*.zip"))
            except Exception:
                pass
    # Latest first, bounded so recovery does not expand hundreds of archives.
    uniq=[]
    seen=set()
    for p in sorted(zips,key=lambda x:x.stat().st_mtime if x.exists() else 0,reverse=True):
        try:key=str(p.resolve())
        except Exception:key=str(p)
        if key in seen:continue
        seen.add(key);uniq.append(p)
    for zi,zp in enumerate(uniq[:12],1):
        if web_stop_requested():break
        try:
            with pyzipfile.ZipFile(zp) as z:
                members=[n for n in z.namelist() if Path(n).name.lower() in {"video_library.db","video_library.rebuilt.db"}]
                for mi,name in enumerate(members,1):
                    data=z.read(name)
                    dest=recovery/f"backup_{zi:02d}_{mi:02d}_{Path(name).name}"
                    dest.write_bytes(data)
                    out.append(dest)
        except Exception as ex:
            print(f"[RECOVERY] Could not inspect backup {zp}: {type(ex).__name__}: {ex}")
    return out

def one_click_database_candidates(roots,stamp):
    candidates=[]
    def add(p,origin):
        try:
            p=Path(p)
            if not p.is_file():return
            if p.resolve()==DB.resolve():return
            key=str(p.resolve())
            if any(str(x["path"].resolve())==key for x in candidates):return
            con=sqlite3.connect(str(p),timeout=4)
            con.execute("PRAGMA query_only=ON")
            ok=con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='videos'").fetchone()
            count=int(con.execute("SELECT COUNT(*) FROM videos").fetchone()[0]) if ok else 0
            cols=len(con.execute("PRAGMA table_info(videos)").fetchall()) if ok else 0
            con.close()
            if ok:
                candidates.append({"path":p,"origin":origin,"rows":count,"columns":cols,"mtime":p.stat().st_mtime})
        except Exception:
            pass

    for r in roots:
        for p in [
            r/"data"/"database"/"video_library.db",
            r/"video_library.db",
            r/"data"/"video_library.db",
            r/"maintenance"/"recovery"/"video_library.rebuilt.db",
        ]:
            add(p,f"library root: {r}")

        # Explicit recovery DB files only; no arbitrary .db scan.
        try:
            rr=r/"maintenance"/"recovery"
            if rr.is_dir():
                for p in rr.glob("video_library*.db"):
                    add(p,f"recovery: {r}")
        except Exception:
            pass

    for p in one_click_extract_backup_databases(roots,stamp):
        add(p,"portable metadata backup")

    candidates.sort(key=lambda x:(x["rows"],x["columns"],x["mtime"]),reverse=True)
    return candidates

def one_click_merge_source_db(source_path):
    """
    Merge missing rows from an old DB.
    Existing rows are NEVER replaced. Empty text fields may be filled from the old DB.
    """
    source_path=Path(source_path)
    src=sqlite3.connect(str(source_path),timeout=8)
    src.execute("PRAGMA query_only=ON")
    src_cols=[str(r[1]) for r in src.execute("PRAGMA table_info(videos)").fetchall()]
    if "video_id" not in src_cols:
        src.close();return {"added":0,"filled":0,"source_rows":0}

    target=db_connect()
    target_cols={str(r[1]) for r in target.execute("PRAGMA table_info(videos)").fetchall()}
    common=[c for c in src_cols if c in target_cols]
    cur=src.execute("SELECT "+",".join('"'+c.replace('"','""')+'"' for c in common)+" FROM videos")
    added=filled=source_rows=0
    protected={"video_id","favorite","watched","user_rating","archived","needs_review"}
    fillable=[c for c in common if c not in protected]

    for row in cur:
        if web_stop_requested():break
        source_rows+=1
        d=dict(zip(common,row))
        vid=str(d.get("video_id") or "").strip()
        if not vid:continue

        exists=target.execute("SELECT 1 FROM videos WHERE video_id=?",(vid,)).fetchone()
        if not exists:
            cols=[c for c in common if c=="video_id" or d.get(c) is not None]
            vals=[d.get(c) for c in cols]
            try:
                target.execute(
                    "INSERT OR IGNORE INTO videos("+",".join('"'+c.replace('"','""')+'"' for c in cols)+") VALUES("+",".join("?" for _ in cols)+")",
                    vals
                )
                if target.total_changes:
                    added+=1
            except Exception as ex:
                print(f"[RECOVERY] DB row {vid} insert warning: {ex}")
        else:
            # Fill only genuinely blank values. Do not overwrite current metadata/state.
            for c in fillable:
                sv=d.get(c)
                if sv is None or sv=="":continue
                try:
                    tv=target.execute(f'SELECT "{c}" FROM videos WHERE video_id=?',(vid,)).fetchone()
                    tv=tv[0] if tv else None
                    if tv is None or (isinstance(tv,str) and not tv.strip()):
                        target.execute(f'UPDATE videos SET "{c}"=? WHERE video_id=?',(sv,vid))
                        filled+=1
                except Exception:
                    pass

    target.commit();target.close();src.close()
    return {"added":added,"filled":filled,"source_rows":source_rows}

def one_click_folder_record(marker):
    marker=Path(marker)
    vid=marker.read_text(encoding="utf-8",errors="ignore").strip()
    if not vid:return None
    folder=marker.parent.parent if marker.parent.name=="_data" else marker.parent
    if not folder.exists():return None
    data_dir=support_dir(folder)

    info={}
    try:
        info_files=list(data_dir.glob("*.info.json"))
        if info_files:
            info=json.loads(info_files[0].read_text(encoding="utf-8",errors="replace"))
    except Exception:
        info={}

    media=find_any_media(folder)
    reports=list(folder.glob("*.report.html"))
    report=reports[0] if reports else None
    original=""
    try:
        ots=list(data_dir.glob("*.original-title"))
        if ots:original=ots[0].read_text(encoding="utf-8",errors="replace").strip()
    except Exception:pass

    url=str(info.get("webpage_url") or info.get("original_url") or "")
    if not url:
        try:
            ufiles=list(data_dir.glob("*.url"))
            if ufiles:url=ufiles[0].read_text(encoding="utf-8",errors="replace").strip()
        except Exception:pass

    title=str(info.get("title") or original or (media.stem if media else folder.name))
    channel=str(info.get("channel") or info.get("uploader") or folder.parent.name)
    upload=str(info.get("upload_date") or "")
    if re.fullmatch(r"\d{8}",upload):
        upload=f"{upload[:4]}-{upload[4:6]}-{upload[6:8]}"

    # Category for downloads\Category\Channel\Video layout.
    category=""
    try:
        if folder.parent.parent.name.lower()!="downloads":
            category=folder.parent.parent.name
    except Exception:pass

    def first(pattern):
        try:
            vals=list(data_dir.glob(pattern))
            return str(vals[0]) if vals else ""
        except Exception:return ""

    return {
        "video_id":vid,"platform":"youtube","url":url,
        "original_title":original or title,"clean_title":title,
        "channel":channel,"upload_date":upload,
        "description":str(info.get("description") or ""),
        "category":category,
        "downloaded":1 if media else 0,
        "local_folder":str(folder),"local_video":str(media or ""),
        "report_html":str(report or ""),
        "subtitle_file":first("*.vtt") or first("*.srt"),
        "transcript_original":first("*.transcript_timestamped.txt"),
        "transcript_clean":first("*.transcript_clean.txt"),
        "transcript_detailed":first("*.transcript_detailed.txt"),
        "final_status":"PASS" if media else "WARN",
        "failure_reason":"",
    }

def one_click_merge_folder_roots(roots):
    """Recover VIDEO_ID rows from physical video folders across likely old/current libraries."""
    target=db_connect()
    target_cols={str(r[1]) for r in target.execute("PRAGMA table_info(videos)").fetchall()}
    added=filled=markers=0
    recovered_ids=[]
    seen_markers=set()

    download_roots=[]
    for r in roots:
        d=Path(r)/"downloads"
        if d.is_dir() and d not in download_roots:
            download_roots.append(d)

    for droot in download_roots:
        print(f"[RECOVERY] Scanning video folders: {droot}")
        try:
            iterator=droot.rglob(".video_id")
        except Exception:
            continue
        for marker in iterator:
            if web_stop_requested():break
            try:
                key=str(marker.resolve())
                if key in seen_markers:continue
                seen_markers.add(key);markers+=1
                rec=one_click_folder_record(marker)
                if not rec:continue
                vid=rec["video_id"]
                exists=target.execute("SELECT 1 FROM videos WHERE video_id=?",(vid,)).fetchone()
                cols=[c for c in rec if c in target_cols]
                if not exists:
                    target.execute(
                        "INSERT OR IGNORE INTO videos("+",".join(f'"{c}"' for c in cols)+") VALUES("+",".join("?" for _ in cols)+")",
                        [rec[c] for c in cols]
                    )
                    added+=1;recovered_ids.append(vid)
                else:
                    for c in cols:
                        if c in {"video_id","favorite","watched","user_rating","archived","needs_review"}:continue
                        sv=rec.get(c)
                        if sv is None or sv=="":continue
                        tv=target.execute(f'SELECT "{c}" FROM videos WHERE video_id=?',(vid,)).fetchone()
                        tv=tv[0] if tv else None
                        if tv is None or (isinstance(tv,str) and not tv.strip()):
                            target.execute(f'UPDATE videos SET "{c}"=? WHERE video_id=?',(sv,vid));filled+=1
            except Exception as ex:
                print(f"[RECOVERY] Folder marker warning {marker}: {type(ex).__name__}: {ex}")
        if web_stop_requested():break
    target.commit();target.close()
    return {"markers":markers,"added":added,"filled":filled,"recovered_ids":recovered_ids,"download_roots":[str(x) for x in download_roots]}

def old_library_import_repair(options):
    """Safely import an explicitly chosen legacy library. Never downloads media."""
    options=options or {}
    source=Path(str(options.get("media_root") or "").strip())
    metadata=Path(str(options.get("metadata_root") or "").strip()) if str(options.get("metadata_root") or "").strip() else None
    if not source.is_dir():
        raise ValueError("Choose an existing old Downloads/media folder first.")
    if metadata and not metadata.is_dir():
        raise ValueError("The optional old metadata folder does not exist.")
    do_move=bool(options.get("move_media"))
    do_db=bool(options.get("merge_metadata",True))
    do_paths=bool(options.get("repair_paths",True))
    do_reports=bool(options.get("refresh_reports",False))
    do_indexes=bool(options.get("rebuild_indexes",True))
    stamp=time.strftime("%Y%m%d-%H%M%S")
    audit=BASE/"maintenance"/"imports"/f"old_library_import_{stamp}.json"
    audit.parent.mkdir(parents=True,exist_ok=True)
    markers=list(source.rglob(".video_id"))
    folders=[];seen=set()
    for marker in markers:
        folder=marker.parent.parent if marker.parent.name=="_data" else marker.parent
        key=str(folder.resolve())
        if key not in seen: seen.add(key);folders.append(folder)
    # Older downloader libraries often have no .video_id marker. Treat the
    # direct parent of each media file as an importable video folder as well.
    media_exts={".mp4",".mkv",".webm",".m4v",".mov",".avi",".mp3",".m4a",".aac",".opus"}
    media_parent_count=0
    for media in source.rglob("*"):
        if not media.is_file() or media.suffix.lower() not in media_exts:
            continue
        folder=media.parent
        key=str(folder.resolve())
        if key not in seen:
            seen.add(key);folders.append(folder);media_parent_count+=1
    result={"source":str(source),"metadata_root":str(metadata or ""),"found_video_folders":len(folders),"moved":0,"merged_folders":0,"moved_files":0,"skipped_same_name_files":0,"errors":[],"steps":[]}
    set_state(phase="Old Library Import", total=len(folders), processed=0, current_status="Scanning legacy folders", message="Preparing import")
    print(f"[OLD IMPORT] Source: {source}; detected folders: {len(folders)} (marker={len(markers)}, media-parent={media_parent_count})")
    if do_db:
        # Direct legacy yt-dlp metadata.info.json recovery. These folders may
        # predate our .video_id marker layout, but their JSON has the real ID.
        con=db_connect();cols={str(r[1]) for r in con.execute("PRAGMA table_info(videos)").fetchall()};info_added=info_filled=0
        for folder in folders:
            try:
                info_path=next(iter(folder.glob("*.info.json")),None)
                if not info_path:continue
                info=json.loads(info_path.read_text(encoding="utf-8",errors="replace"))
                vid=str(info.get("id") or "").strip()
                if not re.fullmatch(r"[A-Za-z0-9_-]{11}",vid):continue
                upload=str(info.get("upload_date") or "")
                if re.fullmatch(r"\d{8}",upload):upload=f"{upload[:4]}-{upload[4:6]}-{upload[6:8]}"
                media=find_any_media(folder)
                record={"video_id":vid,"platform":"youtube","url":str(info.get("webpage_url") or info.get("original_url") or f"https://www.youtube.com/watch?v={vid}"),"original_title":str(info.get("title") or folder.name),"clean_title":str(info.get("title") or folder.name),"channel":str(info.get("channel") or info.get("uploader") or folder.parent.name),"upload_date":upload,"description":str(info.get("description") or ""),"downloaded":1 if media else 0,"local_folder":str(folder),"local_video":str(media or ""),"final_status":"PASS" if media else "WARN"}
                if not con.execute("SELECT 1 FROM videos WHERE video_id=?",(vid,)).fetchone():
                    names=[k for k in record if k in cols];con.execute("INSERT INTO videos("+",".join(names)+") VALUES("+",".join("?" for _ in names)+")",[record[k] for k in names]);info_added+=1
                else:
                    for key,value in record.items():
                        if key not in cols or key=="video_id" or value in {None,""}:continue
                        old=con.execute(f"SELECT \"{key}\" FROM videos WHERE video_id=?",(vid,)).fetchone()
                        if not old or old[0] in {None,""}:con.execute(f"UPDATE videos SET \"{key}\"=? WHERE video_id=?",(value,vid));info_filled+=1
            except Exception as ex:result["errors"].append(f"info.json {folder}: {type(ex).__name__}: {ex}")
        con.commit();con.close();result["info_json_metadata"]={"added":info_added,"filled":info_filled}
        roots=[source.parent]
        if metadata: roots.append(metadata)
        candidates=one_click_database_candidates(roots,stamp)
        merged=[]
        for candidate in candidates:
            summary=one_click_merge_source_db(candidate["path"])
            merged.append({"path":str(candidate["path"]),**summary})
        folder_merge=one_click_merge_folder_roots([source.parent])
        result["metadata_merge"]={"databases":merged,"folders":folder_merge};result["steps"].append("Merged missing/blank metadata only")
    if do_move:
        for index,folder in enumerate(folders,1):
            if web_stop_requested(): break
            try:
                set_state(phase="Old Library Import", processed=index-1, total=len(folders), current_file=str(folder), current_status="Merging video folder")
                rel=folder.relative_to(source)
                target=DOWNLOADS/rel
                if not target.exists():
                    target.parent.mkdir(parents=True,exist_ok=True)
                    shutil.move(str(folder),str(target));result["moved"]+=1
                    set_state(phase="Old Library Import", processed=index, total=len(folders), current_file=str(folder), current_status="Folder moved")
                    continue
                # Merge duplicate folder trees; keep every destination file with
                # the same relative name and move only missing source files.
                result["merged_folders"]+=1
                for item in folder.rglob("*"):
                    if not item.is_file():continue
                    destination=target/item.relative_to(folder)
                    if destination.exists():
                        result["skipped_same_name_files"]+=1;continue
                    destination.parent.mkdir(parents=True,exist_ok=True)
                    shutil.move(str(item),str(destination));result["moved_files"]+=1
                set_state(phase="Old Library Import", processed=index, total=len(folders), current_file=str(folder), current_status="Folder merged")
            except Exception as ex:
                result["errors"].append(f"{folder}: {type(ex).__name__}: {ex}")
        result["steps"].append("Moved folders and merged duplicate folder trees; same-name files were skipped" if do_move else "Kept source media in place")
    if do_paths:
        # Legacy folders can provide their canonical ID through metadata.info.json.
        # Write the marker after any move/merge and point SQLite at that exact folder.
        con=db_connect();info_markers=0
        for old_folder in folders:
            try:
                rel=old_folder.relative_to(source)
                folder=(DOWNLOADS/rel) if (DOWNLOADS/rel).exists() else old_folder
                info_path=next(iter(folder.glob("*.info.json")),None)
                if not info_path:continue
                info=json.loads(info_path.read_text(encoding="utf-8",errors="replace"))
                vid=str(info.get("id") or "").strip()
                if not re.fullmatch(r"[A-Za-z0-9_-]{11}",vid):continue
                marker=support_dir(folder,create=True)/".video_id"
                marker.write_text(vid,encoding="utf-8")
                media=find_any_media(folder)
                con.execute("UPDATE videos SET local_folder=?,local_video=? WHERE video_id=?",(str(folder),str(media or ""),vid))
                info_markers+=1
            except Exception as ex:result["errors"].append(f"video ID marker: {type(ex).__name__}: {ex}")
        con.commit();con.close();result["info_json_markers_created"]=info_markers
        result["path_repair"]=phase1_fix_db_paths();result["marker_repair"]=phase1_repair_video_id_markers();result["steps"].append("Repaired database paths and VIDEO_ID markers")
    if do_reports:
        result["reports"]=refresh_reports();result["steps"].append("Refreshed reports")
    if do_indexes:
        export_csv();build_library_indexes();phase5_build_all();phase6_build_all();result["steps"].append("Rebuilt CSV, indexes and Knowledge Center")
    result["completed_at"]=time.strftime("%Y-%m-%d %H:%M:%S")
    audit.write_text(json.dumps(web_json_safe(result),ensure_ascii=False,indent=2),encoding="utf-8")
    print(f"[OLD IMPORT] Complete. moved folders={result['moved']} moved files={result['moved_files']} skipped same-name files={result['skipped_same_name_files']} audit={audit}")
    return result

def old_library_preflight_scan(options):
    """Read-only inspection of a legacy library before any move or download."""
    options=options or {}
    source=Path(str(options.get("media_root") or "").strip())
    if not source.is_dir():
        raise ValueError("Choose an existing old Downloads/media folder first.")
    ext={".mp4",".mkv",".webm",".m4v",".mov",".avi",".mp3",".m4a",".aac",".opus"}
    media_files=[p for p in source.rglob("*") if p.is_file() and p.suffix.lower() in ext]
    folders=[];seen=set()
    for media in media_files:
        folder=media.parent;key=str(folder.resolve())
        if key not in seen:seen.add(key);folders.append(folder)
    set_state(phase="Old Library Preflight",total=len(folders),processed=0,current_status="Inspecting legacy video folders",message="Preflight scan started")
    records=[];summary={"folders":len(folders),"with_info_json":0,"with_video_id":0,"with_media":0,"with_transcript":0,"with_subtitles":0,"with_comments":0,"with_thumbnail":0,"with_report":0,"already_in_destination":0,"needs_metadata":0,"needs_transcript":0,"needs_comments":0,"needs_thumbnail":0,"needs_report":0}
    for index,folder in enumerate(folders,1):
        set_state(phase="Old Library Preflight",total=len(folders),processed=index-1,current_file=str(folder),current_status="Inspecting folder")
        info={};info_path=next(iter(folder.glob("*.info.json")),None)
        if info_path:
            summary["with_info_json"]+=1
            try:info=json.loads(info_path.read_text(encoding="utf-8",errors="replace"))
            except Exception:info={}
        vid=str(info.get("id") or "").strip()
        if re.fullmatch(r"[A-Za-z0-9_-]{11}",vid):summary["with_video_id"]+=1
        media=next((p for p in folder.iterdir() if p.is_file() and p.suffix.lower() in ext),None)
        transcript=bool(list(folder.glob("*.transcript*.txt")) or list(folder.glob("*.txt")))
        subtitles=bool(list(folder.glob("*.srt")) or list(folder.glob("*.vtt")))
        comments=bool(list(folder.glob("*comment*.json")) or list(folder.glob("*comment*.csv")))
        thumbnail=bool(list(folder.glob("*.jpg"))+list(folder.glob("*.jpeg"))+list(folder.glob("*.png"))+list(folder.glob("*.webp")))
        report=bool(list(folder.glob("*.report.html")))
        rel=folder.relative_to(source);destination=DOWNLOADS/rel
        exists=destination.exists()
        summary["with_media"]+=bool(media);summary["with_transcript"]+=transcript or subtitles;summary["with_subtitles"]+=subtitles;summary["with_comments"]+=comments;summary["with_thumbnail"]+=thumbnail;summary["with_report"]+=report;summary["already_in_destination"]+=exists
        summary["needs_metadata"]+=not bool(vid);summary["needs_transcript"]+=not (transcript or subtitles);summary["needs_comments"]+=not comments;summary["needs_thumbnail"]+=not thumbnail;summary["needs_report"]+=not report
        records.append({"video_id":vid,"folder":str(folder),"destination":str(destination),"destination_exists":exists,"title":str(info.get("title") or folder.name),"channel":str(info.get("channel") or info.get("uploader") or folder.parent.name),"media":bool(media),"metadata_info_json":bool(info_path),"transcript":transcript,"subtitles":subtitles,"comments":comments,"thumbnail":thumbnail,"report":report,"can_create_marker":bool(vid),"can_fetch_artifacts":bool(vid)})
        set_state(phase="Old Library Preflight",total=len(folders),processed=index,current_file=str(folder),current_status="Inspected")
    stamp=time.strftime("%Y%m%d-%H%M%S");out=BASE/"maintenance"/"imports"/f"old_library_preflight_{stamp}.json";out.parent.mkdir(parents=True,exist_ok=True)
    payload={"source":str(source),"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"summary":summary,"records":records,"report":str(out)}
    out.write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
    return payload

def old_library_preflight_many(options):
    roots=[x.strip() for x in re.split(r"[\r\n;]+",str((options or {}).get("media_roots") or (options or {}).get("media_root") or "")) if x.strip()]
    if not roots:raise ValueError("Choose at least one old media folder.")
    reports=[]
    for root in roots:
        if web_stop_requested():break
        reports.append(old_library_preflight_scan({"media_root":root}))
    return {"folders_requested":len(roots),"reports":reports}

def old_library_import_many(options):
    options=dict(options or {})
    roots=[x.strip() for x in re.split(r"[\r\n;]+",str(options.get("media_roots") or options.get("media_root") or "")) if x.strip()]
    if not roots:raise ValueError("Choose at least one old media folder.")
    results=[]
    for root in roots:
        if web_stop_requested():break
        one=dict(options);one["media_root"]=root
        results.append(old_library_import_repair(one))
    return {"folders_requested":len(roots),"imports":results}

def close_previous_app_sessions():
    """Close other VideoHoarder launches while keeping this dashboard alive."""
    if os.name != "nt":
        return {"ok":False,"message":"This control is available on Windows only."}
    current=os.getpid()
    parent=os.getppid()
    command=(
        "$keep=@("+str(current)+","+str(parent)+");"
        "$items=Get-CimInstance Win32_Process -Filter \"Name='VideoHoarder.exe'\" | "
        "Where-Object {$keep -notcontains [int]$_.ProcessId};"
        "$ids=@($items | ForEach-Object {[int]$_.ProcessId});"
        "foreach($id in $ids){taskkill /F /PID $id | Out-Null};"
        "Write-Output ($ids -join ',')"
    )
    try:
        run=subprocess.run(["powershell.exe","-NoProfile","-Command",command],capture_output=True,text=True,timeout=20,creationflags=getattr(subprocess,"CREATE_NO_WINDOW",0))
        closed=[x for x in run.stdout.strip().split(",") if x.strip().isdigit()]
        return {"ok":True,"message":("Closed previous app session(s): "+", ".join(closed)) if closed else "No previous app sessions were running.","closed":closed}
    except Exception as ex:
        return {"ok":False,"message":f"Could not close prior sessions: {type(ex).__name__}: {ex}"}

def repair_selected_video_data(options):
    """Fetch selected non-media artifacts for supplied VIDEO_IDs. Never downloads video media."""
    options=options or {}
    raw=str(options.get("video_ids") or "")
    ids=[];seen=set()
    for value in re.split(r"[\s,;]+",raw):
        value=value.strip()
        if value and value not in seen:seen.add(value);ids.append(value)
    con=db_connect()
    collection_name=str(options.get("collectionScope") or "").strip()
    if not ids and collection_name:
        collection=next((x for x in phase6_load_collections() if str(x.get("name") or "").strip().lower()==collection_name.lower()),None)
        ids=list(dict.fromkeys(str(v) for v in (collection or {}).get("video_ids",[]) if str(v).strip()))
    if not ids:
        ids=[str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(archived,0)=0").fetchall()]
    placeholders=",".join("?" for _ in ids)
    rows=con.execute(f"SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang FROM videos WHERE video_id IN ({placeholders})",ids).fetchall() if ids else []
    con.close()
    checkpoint_dir=BASE/"maintenance"/"repair_checkpoints";checkpoint_dir.mkdir(parents=True,exist_ok=True)
    scope=hashlib.sha256(("|".join(sorted(str(r[0]) for r in rows))+"|transcripts").encode()).hexdigest()[:16]
    checkpoint_path=checkpoint_dir/f"repair_{scope}.json"
    try:checkpoint=json.loads(checkpoint_path.read_text(encoding="utf-8")) if checkpoint_path.exists() else {}
    except Exception:checkpoint={}
    checkpoint.update({"path":str(checkpoint_path),"scope":scope,"total":len(rows),"updated_at":time.strftime("%Y-%m-%d %H:%M:%S")});checkpoint.setdefault("completed",{})
    result={"requested_ids":len(ids),"found_rows":len(rows),"metadata":0,"transcripts":0,"comments":0,"errors":[],"resume_checkpoint":str(checkpoint_path)}
    set_state(phase="Missing Data & AI", total=len(rows), processed=0, current_status="Preparing selected videos", message="Starting selected data recovery")
    if options.get("artifact_manifest"):
        result["artifact_manifest"]=build_video_artifact_manifest([r[0] for r in rows])
    if options.get("metadata"):
        set_state(phase="Missing Data & AI", total=len(rows), processed=0, current_status="Refreshing metadata")
        urls=[str(r[1] or "") for r in rows if r[1]]
        try:
            api_result=metadata_via_youtube_api(urls)
            meta=(api_result or ([],urls))[0]
            if meta:save_metadata(meta);result["metadata"]=len(meta)
        except Exception as ex: result["errors"].append(f"metadata: {type(ex).__name__}: {ex}")
    if options.get("transcripts"):
        set_state(phase="Missing Data & AI", total=len(rows), processed=0, current_status="Fetching transcripts and subtitles")
        try:
            result["transcript_progress"]=prepare_transcripts_rows(rows,checkpoint);name_videos_from_tmp_transcripts();result["transcripts"]=len(rows)
        except Exception as ex: result["errors"].append(f"transcripts: {type(ex).__name__}: {ex}")
    if options.get("comments"):
        for index,(vid,url,*_) in enumerate(rows,1):
            try:
                set_state(phase="Missing Data & AI", processed=index-1, total=len(rows), current_file=str(vid), current_status="Fetching comments")
                if url:save_youtube_comments(str(vid),str(url),max_comments=int(options.get("comment_limit") or 500));result["comments"]+=1
                set_state(phase="Missing Data & AI", processed=index, total=len(rows), current_file=str(vid), current_status="Comments finished")
            except Exception as ex:result["errors"].append(f"comments {vid}: {type(ex).__name__}: {ex}")
    if options.get("reports"):
        try:phase1_repair_missing_reports()
        except Exception as ex:result["errors"].append(f"reports: {type(ex).__name__}: {ex}")
    if options.get("chatgpt_packages"):
        result["chatgpt_packages"]=chatgpt_create_packages_and_tag_cleanup("unclassified",int(options.get("package_size") or 25))
    if options.get("knowledge_ai"):
        result["knowledge_ai"]=knowledge_ai_build_verify_refresh()
    if options.get("media_download"):
        missing=[]
        for vid,url,*_ in rows:
            exists,folder=library_has_video(str(vid))
            if not exists and url:missing.append(str(url))
        if missing:
            result["media_download"]=web_media_only_download(missing,str(options.get("media_quality") or "1080"),"Imported Library",True,"source")
        else:result["media_download"]={"message":"No selected video IDs are missing media."}
    export_csv();build_library_indexes()
    return result

def one_click_recover_rebuild_everything():
    """
    SAFE one-click recovery for a replaced/empty/stale SQLite database.

    Safety:
    - backs up the CURRENT DB/metadata first;
    - never replaces the current DB with an old DB;
    - merges only missing rows and fills blank fields;
    - never deletes/quarantines media;
    - then rebuilds paths/reports/indexes/Phase5/Phase6 and audits.
    """
    stamp=time.strftime("%Y%m%d-%H%M%S")
    recovery_dir=BASE/"maintenance"/"recovery"
    recovery_dir.mkdir(parents=True,exist_ok=True)
    report_path=recovery_dir/f"one_click_recovery_{stamp}.json"

    con=db_connect()
    before=int(con.execute("SELECT COUNT(*) FROM videos").fetchone()[0])
    before_ids={str(r[0]) for r in con.execute("SELECT video_id FROM videos").fetchall()}
    con.close()

    unresolved_before=one_click_recovery_package_missing_ids()
    summary={
        "version":APP_VERSION,"started_at":time.strftime("%Y-%m-%d %H:%M:%S"),
        "database":str(DB),"library_root":str(BASE),
        "before_rows":before,"after_rows":before,
        "recovered":0,"recovered_ids":[],"filled_fields":0,
        "unresolved_before":unresolved_before,"unresolved_after":[],
        "db_sources":[],"folder_recovery":{},"steps":[],
        "message":"Recovery started"
    }

    def step(n,total,label,func,required=False):
        if web_stop_requested():
            raise RuntimeError("Stopped by user")
        msg=f"[RECOVERY {n}/{total}] {label}"
        web_job_progress(msg,n-1,total,"One-Click Recovery")
        started=time.time()
        print("\n"+"="*78)
        print(msg)
        print("="*78,flush=True)
        try:
            result=func()
            summary["steps"].append({"step":label,"ok":True,"seconds":round(time.time()-started,2),"result":web_json_safe(result)})
            return result
        except Exception as ex:
            item={"step":label,"ok":False,"seconds":round(time.time()-started,2),"error":f"{type(ex).__name__}: {ex}"}
            summary["steps"].append(item)
            print(f"[RECOVERY] WARNING: {item['error']}",flush=True)
            if required:raise
            return None

    TOTAL=15

    # 1. Required safety backup.
    backup=step(1,TOTAL,"Create portable metadata backup",phase1_backup_library_metadata,required=True)

    # Extra raw DB snapshot.
    def raw_snapshot():
        if not DB.exists():return ""
        p=recovery_dir/f"pre_recovery_current_video_library_{stamp}.db"
        shutil.copy2(DB,p);return str(p)
    raw_db=step(2,TOTAL,"Snapshot current SQLite database",raw_snapshot,required=True)

    roots=step(3,TOTAL,"Discover old/current library roots",one_click_recovery_roots,required=True) or [BASE]
    roots=[Path(x) for x in roots]
    summary["roots"]=[str(x) for x in roots]

    candidates=step(4,TOTAL,"Find old SQLite databases and metadata-backup databases",lambda:one_click_database_candidates(roots,stamp),required=False) or []
    for i,c in enumerate(candidates,1):
        if web_stop_requested():break
        web_job_progress(f"[RECOVERY] Merging old DB {i}/{len(candidates)} — rows={c['rows']} — {c['path']}",4,TOTAL,"One-Click Recovery")
        res=one_click_merge_source_db(c["path"])
        summary["db_sources"].append({
            "path":str(c["path"]),"origin":c["origin"],"rows":c["rows"],"columns":c["columns"],**res
        })
        summary["filled_fields"]+=int(res.get("filled") or 0)

    folders=step(5,TOTAL,"Recover missing rows from physical VIDEO_ID folders",lambda:one_click_merge_folder_roots(roots),required=True) or {}
    summary["folder_recovery"]=web_json_safe(folders)
    summary["filled_fields"]+=int(folders.get("filled") or 0)

    # Determine genuinely new rows after source+folder merge.
    con=db_connect()
    after_merge_ids={str(r[0]) for r in con.execute("SELECT video_id FROM videos").fetchall()}
    con.close()
    recovered_ids=sorted(after_merge_ids-before_ids)
    summary["recovered_ids"]=recovered_ids
    summary["recovered"]=len(recovered_ids)

    step(6,TOTAL,"Repair missing .video_id markers",phase1_repair_video_id_markers)
    step(7,TOTAL,"Repair SQLite folder/media/report paths",phase1_fix_db_paths)
    step(8,TOTAL,"Repair original-title markers",repair_original_title_markers)
    step(9,TOTAL,"Repair broken HTML video links",phase0_repair_html_video_links)
    step(10,TOTAL,"Repair missing/broken HTML reports",phase1_repair_missing_reports)
    step(11,TOTAL,"Rebuild comment intelligence",rebuild_all_comment_intelligence)
    step(12,TOTAL,"Rebuild CSV and logical library indexes",lambda:(export_csv(),build_library_indexes()))
    step(13,TOTAL,"Rebuild Phase 5 Knowledge Center",phase5_build_all)
    step(14,TOTAL,"Rebuild Phase 6 chunks + embeddings + health",phase6_build_all)
    step(15,TOTAL,"Reconcile Smart Resume and run final audits",lambda:(reconcile_existing_smart_resume_state(),phase1_scan_library(),phase0_core_audit()))

    con=db_connect()
    after=int(con.execute("SELECT COUNT(*) FROM videos").fetchone()[0])
    con.close()
    summary["after_rows"]=after
    summary["unresolved_after"]=one_click_recovery_package_missing_ids()
    summary["finished_at"]=time.strftime("%Y-%m-%d %H:%M:%S")
    summary["message"]=f"Recovery complete: restored {summary['recovered']} missing SQLite video rows; rows {before} -> {after}; unresolved package IDs {len(summary['unresolved_before'])} -> {len(summary['unresolved_after'])}."
    summary["backup"]=str(backup or "")
    summary["raw_db_snapshot"]=str(raw_db or "")
    report_path.write_text(json.dumps(web_json_safe(summary),ensure_ascii=False,indent=2),encoding="utf-8")
    summary["report"]=str(report_path)

    web_job_progress(summary["message"],TOTAL,TOTAL,"One-Click Recovery Complete")
    print("\n"+"#"*78)
    print("ONE-CLICK OLD LIBRARY RECOVERY + REBUILD COMPLETE")
    print(f"SQLite rows before : {before}")
    print(f"SQLite rows after  : {after}")
    print(f"Missing rows restored: {summary['recovered']}")
    if recovered_ids:
        print("Recovered VIDEO_IDs:")
        for vid in recovered_ids[:200]:print(f"  + {vid}")
    print(f"Unresolved package IDs before: {len(summary['unresolved_before'])}")
    print(f"Unresolved package IDs after : {len(summary['unresolved_after'])}")
    if summary["unresolved_after"]:
        print("Still unresolved:")
        for vid in summary["unresolved_after"][:200]:print(f"  ! {vid}")
    print(f"Recovery report    : {report_path}")
    print(f"Safety backup      : {backup}")
    print("#"*78,flush=True)
    return summary

def phase1_repair_center():
    while True:
        print("""
============================================================
 PHASE 1 - LIBRARY HEALTH / STRUCTURE / RECOVERY
============================================================
1 = Full Library Health & Path Audit
2 = Original Title Integrity Audit
3 = Migrate & Modernize Library Structure
4 = Repair & Refresh Library Core
5 = Quarantine Zero-Byte Files [Moves, does not delete]
6 = Full System Health Check, Backup & Safe Repair
7 = Build Recovery DB from Folders [Does not replace current DB]
8 = ONE-CLICK Recover Old Library + Rebuild Everything [Emergency]
0 = Back
""")
        c=input("Choose: ").strip()
        if c=='1': full_library_health_path_audit()
        elif c=='2': original_title_integrity_audit_combined()
        elif c=='3': migrate_modernize_library_structure()
        elif c=='4': repair_refresh_library_core()
        elif c=='5': phase1_quarantine_zero_byte_files()
        elif c=='6': full_system_health_backup_safe_repair()
        elif c=='7': phase1_rebuild_db_from_folders()
        elif c=='8': one_click_recover_rebuild_everything()
        elif c=='0': break


def legacy_chatgpt_package_dirs():
    candidates=[
        BASE/"chatgpt_packages",
        BASE/"chatgpt_package",
        BASE/"packages",
    ]
    return [Path(p) for p in candidates if Path(p).exists() and Path(p).is_dir()]


def phase2_all_package_dirs():
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    dirs=[packages]
    for p in legacy_chatgpt_package_dirs():
        if p.exists() and p not in dirs:
            dirs.append(p)
    return dirs


def phase2_all_result_dirs():
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    dirs=[results]
    if "CHATGPT_RESULTS" in globals():
        p=Path(CHATGPT_RESULTS)
        if p.exists() and p not in dirs:
            dirs.append(p)
    for p in phase2_legacy_paths().get("results",[]):
        if p.exists() and p not in dirs:
            dirs.append(p)
    return dirs


def phase2_sync_legacy_packages():
    """
    Copy legacy option-14 package JSONs into data/chatgpt/packages and create
    manifests when missing.
    """
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    synced=0
    manifests=0

    for srcdir in legacy_chatgpt_package_dirs():
        for p in srcdir.rglob("*.json"):
            if p.name.endswith(".manifest.json"):
                continue
            try:
                target=packages/p.name
                if not target.exists():
                    shutil.copy2(p,target)
                    synced+=1

                manifest_target=packages/f"{p.stem}.manifest.json"
                if not manifest_target.exists():
                    obj=json.loads(p.read_text(encoding="utf-8"))
                    videos=(obj.get("videos") or []) if isinstance(obj,dict) else []
                    if videos:
                        package_id=str(obj.get("package_id") or p.stem)
                        manifest=phase2_manifest_for_videos(package_id,videos)
                        manifest_target.write_text(
                            json.dumps(manifest,ensure_ascii=False,indent=2),
                            encoding="utf-8"
                        )
                        manifests+=1
                        phase2_write_history(package_id,"SYNCED_FROM_LEGACY",len(videos))
            except Exception as ex:
                print(f"Could not sync {p.name}: {ex}")

    return synced,manifests

def phase2_detect_result_files():
    files=[]
    seen=set()
    for d in phase2_all_result_dirs():
        for p in sorted(d.glob("*.json")):
            if p.name.endswith(".manifest.json"):
                continue
            rp=str(p.resolve())
            if rp not in seen:
                seen.add(rp)
                files.append(p)
    return files

def phase2_choose_result_file():
    files=phase2_detect_result_files()
    if not files:
        print("No result JSON files found.")
        print("Checked:")
        for d in phase2_all_result_dirs():
            print(f"  {d}")
        return None

    print("")
    print("Detected result files:")
    for i,p in enumerate(files,1):
        print(f"{i} = {p.name}   [{p.parent}]")
    print("0 = Cancel")

    raw=input("Choose result file: ").strip()
    if not raw or raw=="0":
        return None

    try:
        idx=int(raw)
        if 1 <= idx <= len(files):
            return files[idx-1]
    except Exception:
        pass

    # Allow filename only, not arbitrary path requirement.
    for p in files:
        if p.name.lower()==raw.lower():
            return p

    print("Invalid selection.")
    return None


def phase2_legacy_paths():
    return {
        "packages":[p for p in [BASE/"chatgpt_packages",BASE/"chatgpt_package",BASE/"packages"] if p.exists()],
        "results":[p for p in [BASE/"chatgpt_results",BASE/"chatgpt_result",BASE/"results"] if p.exists()],
        "retry":[p for p in [BASE/"chatgpt_retry",BASE/"retry"] if p.exists()],
        "archive":[p for p in [BASE/"chatgpt_archive",BASE/"archive"] if p.exists()]
    }


def phase2_migrate_legacy_storage(copy_only=True):
    """
    Compatibility migration for Phase 2 storage.

    copy_only=True:
      copies legacy package/result/retry/archive files into new data/chatgpt tree
      without deleting old files.

    This is intentionally non-destructive.
    """
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    targets={
        "packages":packages,
        "results":results,
        "retry":retry,
        "archive":archive
    }

    moved=0
    copied=0
    skipped=0
    failed=0

    for kind,dirs in phase2_legacy_paths().items():
        dest=targets[kind]
        for old in dirs:
            if not old.exists():
                continue
            if old.resolve()==dest.resolve():
                continue

            for item in old.rglob("*"):
                if not item.is_file():
                    continue
                try:
                    rel=item.relative_to(old)
                    target=dest/rel
                    target.parent.mkdir(parents=True,exist_ok=True)

                    if target.exists():
                        # same-size duplicate => skip
                        try:
                            if target.stat().st_size==item.stat().st_size:
                                skipped+=1
                                continue
                        except Exception:
                            pass
                        target=target.with_name(target.stem+"_legacy"+target.suffix)

                    if copy_only:
                        shutil.copy2(item,target)
                        copied+=1
                    else:
                        shutil.move(str(item),str(target))
                        moved+=1
                except Exception as ex:
                    failed+=1
                    print(f"Legacy migration failed: {item} -> {dest}: {ex}")

    print("Phase 2 legacy storage migration complete")
    print(f"Copied : {copied}")
    print(f"Moved  : {moved}")
    print(f"Skipped: {skipped}")
    print(f"Failed : {failed}")
    return copied,moved,skipped,failed


def phase2_resolve_package_json(package_id):
    packages,results,retry,archive,history=phase2_chatgpt_dirs()

    # preferred new path
    candidates=list(packages.glob(f"{package_id}.json"))
    if candidates:
        return candidates[0]

    # any matching new path
    candidates=list(packages.glob(f"{package_id}*.json"))
    candidates=[p for p in candidates if not p.name.endswith(".manifest.json")]
    if candidates:
        return candidates[0]

    # legacy paths
    for d in phase2_legacy_paths()["packages"]:
        if not d.exists():
            continue
        cands=list(d.glob(f"{package_id}*.json"))
        cands=[p for p in cands if not p.name.endswith(".manifest.json")]
        if cands:
            return cands[0]

    # archive
    cands=list(archive.rglob(f"{package_id}*.json"))
    cands=[p for p in cands if not p.name.endswith(".manifest.json")]
    return cands[0] if cands else None


def phase2_resolve_result_file(name_or_path):
    """
    Accept:
    - full path
    - filename only
    - stem only
    """
    raw=str(name_or_path or "").strip()
    if not raw:
        return None

    p=Path(raw)
    if p.is_absolute() and p.exists():
        return p

    names=[raw]
    if not raw.lower().endswith(".json"):
        names.append(raw+".json")

    for d in phase2_all_result_dirs():
        for n in names:
            cand=d/n
            if cand.exists():
                return cand

    return None



def remove_empty_legacy_chatgpt_folders():
    candidates=[
        BASE/"chatgpt_packages",
        BASE/"chatgpt_package",
        BASE/"chatgpt_results",
        BASE/"chatgpt_result",
        BASE/"chatgpt_retry",
        BASE/"chatgpt_archive",
    ]
    removed=0
    kept=0
    for p in candidates:
        if not p.exists() or not p.is_dir():
            continue
        try:
            if any(p.iterdir()):
                print(f"KEEP non-empty legacy folder: {p}")
                kept+=1
            else:
                p.rmdir()
                print(f"REMOVED empty legacy folder: {p}")
                removed+=1
        except Exception as ex:
            print(f"FAILED {p}: {ex}")
    print(f"Legacy ChatGPT folder cleanup: removed={removed}, kept non-empty={kept}")
    return removed,kept

def phase2_integrity_audit():
    """
    Audit Phase 2 folders, manifests, package mappings, and DB compatibility.
    """
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    issues=[]

    def add(check,status,detail=""):
        issues.append((check,status,detail))

    # Required directories
    for name,p in [
        ("Packages",packages),
        ("Results",results),
        ("Retry",retry),
        ("Archive",archive)
    ]:
        add(name,"PASS" if p.exists() else "FAIL",str(p))

    # DB columns
    cols=video_table_columns()
    required=[
        "video_id","chatgpt_imported","chatgpt_summary_file",
        "chatgpt_result_hash","chatgpt_report_hash","identity_json"
    ]
    for c in required:
        add(f"DB column {c}","PASS" if c in cols else "FAIL","")

    # package/manifests
    manifests=list(packages.glob("*.manifest.json"))
    package_jsons=[
        p for p in packages.glob("*.json")
        if not p.name.endswith(".manifest.json")
    ]

    add("Package JSON count","PASS",str(len(package_jsons)))
    add("Manifest count","PASS" if len(manifests)>=len(package_jsons) else "WARN",
        f"{len(manifests)} manifests / {len(package_jsons)} packages")

    for p in package_jsons:
        manifest=packages/f"{p.stem}.manifest.json"
        if not manifest.exists():
            add("Missing manifest","WARN",p.name)

    # result readability
    for p in phase2_detect_result_files():
        try:
            json.loads(p.read_text(encoding="utf-8"))
            add("Result JSON","PASS",p.name)
        except PermissionError:
            add("Result JSON","WARN",f"Access denied: {p}")
        except Exception as ex:
            add("Result JSON","FAIL",f"{p.name}: {ex}")

    # Write audit
    audit_dir=BASE/"maintenance"/"audits"
    audit_dir.mkdir(parents=True,exist_ok=True)
    out=audit_dir/"phase2_integrity_audit.csv"
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Check","Status","Detail"])
        w.writerows(issues)

    print("")
    print("===== PHASE 2 INTEGRITY AUDIT =====")
    for check,status,detail in issues:
        print(f"{status:<5} | {check} | {detail}")
    print(f"Details: {out}")
    return out,issues

def phase2_chatgpt_dirs():
    root=BASE/CFG.get("chatgpt_package_root","data/chatgpt")
    packages=BASE/CFG.get("chatgpt_package_pending","data/chatgpt/packages")
    results=BASE/CFG.get("chatgpt_package_results","data/chatgpt/results")
    retry=BASE/CFG.get("chatgpt_package_retry","data/chatgpt/retry")
    archive=BASE/CFG.get("chatgpt_package_archive","data/chatgpt/archive")
    for p in (root,packages,results,retry,archive):
        p.mkdir(parents=True,exist_ok=True)
    history=BASE/CFG.get("chatgpt_package_history","data/chatgpt/package_history.csv")
    history.parent.mkdir(parents=True,exist_ok=True)
    return packages,results,retry,archive,history

def phase2_package_id():
    stamp=time.strftime("%Y%m%d-%H%M%S")
    return f"pkg_{stamp}"

def phase2_manifest_for_videos(package_id, videos):
    """
    Build canonical package manifest.
    """
    expected=[]
    total_chars=0
    langs={}
    for item in videos:
        vid=str(item.get("video_id") or "").strip()
        transcript=str(item.get("transcript") or item.get("transcript_text") or "")
        lang=str(item.get("source_language") or item.get("language") or "unknown")
        expected.append(vid)
        total_chars+=len(transcript)
        langs[lang]=langs.get(lang,0)+1

    return {
        "package_id":package_id,
        "schema_version":int(CFG.get("chatgpt_schema_version",2)),
        "created_at":time.strftime("%Y-%m-%dT%H:%M:%S"),
        "video_count":len(expected),
        "expected_video_ids":expected,
        "total_transcript_chars":total_chars,
        "source_languages":langs
    }

def phase2_write_history(package_id,status,video_count=0,returned=0,imported=0,reports=0,details=""):
    _,_,_,_,history=phase2_chatgpt_dirs()
    exists=history.exists()
    with open(history,"a",newline="",encoding="utf-8-sig") as f:
        fields=["Timestamp","Package ID","Status","Expected Videos","Returned Videos","Imported Videos","Reports","Details"]
        w=csv.DictWriter(f,fieldnames=fields)
        if not exists:
            w.writeheader()
        w.writerow({
            "Timestamp":time.strftime("%Y-%m-%d %H:%M:%S"),
            "Package ID":package_id,
            "Status":status,
            "Expected Videos":video_count,
            "Returned Videos":returned,
            "Imported Videos":imported,
            "Reports":reports,
            "Details":details
        })

def phase2_normalize_result_payload(payload):
    """
    Normalize old/new ChatGPT result shapes into canonical:
      {"schema_version":2,"package_id":"...","videos":[...]}
    """
    if isinstance(payload,list):
        return {
            "schema_version":2,
            "package_id":"",
            "videos":payload
        }

    if not isinstance(payload,dict):
        return None

    if "videos" in payload and isinstance(payload.get("videos"),list):
        return {
            "schema_version":int(payload.get("schema_version") or 2),
            "package_id":str(payload.get("package_id") or ""),
            "videos":payload.get("videos") or []
        }

    # older single-video result
    if payload.get("video_id"):
        return {
            "schema_version":2,
            "package_id":str(payload.get("package_id") or ""),
            "videos":[payload]
        }

    # common legacy wrapper
    if isinstance(payload.get("results"),list):
        return {
            "schema_version":2,
            "package_id":str(payload.get("package_id") or ""),
            "videos":payload.get("results") or []
        }

    return None

def phase2_find_manifest(package_id):
    packages,results,retry,archive,history=phase2_chatgpt_dirs()

    for d in phase2_all_package_dirs():
        candidates=list(d.glob(f"{package_id}*.manifest.json"))
        if candidates:
            return candidates[0]

    candidates=list(archive.rglob(f"{package_id}*.manifest.json"))
    return candidates[0] if candidates else None


def phase2_create_retry_package(package_id, problem_video_ids, reason=""):
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    manifest_path=phase2_find_manifest(package_id)
    if not manifest_path or not manifest_path.exists():
        print(f"Retry package not created: manifest not found for {package_id}")
        return None

    manifest=json.loads(manifest_path.read_text(encoding="utf-8"))
    source_pkg=phase2_resolve_package_json(package_id)

    if not source_pkg or not source_pkg.exists():
        print(f"Retry package not created: source package not found for {package_id}")
        return None

    obj=json.loads(source_pkg.read_text(encoding="utf-8"))
    videos=obj.get("videos") if isinstance(obj,dict) else None
    if not isinstance(videos,list):
        print("Retry package not created: source package has no videos list")
        return None

    wanted=set(problem_video_ids)

    # Avoid repeatedly creating identical retry packages.
    for existing_manifest in retry.glob(f"{package_id}_retry_*.manifest.json"):
        try:
            em=json.loads(existing_manifest.read_text(encoding="utf-8"))
            existing_ids=set(str(x) for x in (em.get("expected_video_ids") or []))
            if existing_ids==wanted:
                existing_json=existing_manifest.with_name(
                    existing_manifest.name.replace(".manifest.json",".json")
                )
                if existing_json.exists():
                    print(f"Existing retry package already covers these videos: {existing_json}")
                    return existing_json
        except Exception:
            pass

    retry_videos=[v for v in videos if str(v.get("video_id") or "") in wanted]
    if not retry_videos:
        print("Retry package not created: no matching problem videos")
        return None

    retry_id=f"{package_id}_retry_{time.strftime('%H%M%S')}"
    retry_obj={
        "package_id":retry_id,
        "parent_package_id":package_id,
        "schema_version":int(CFG.get("chatgpt_schema_version",2)),
        "repair_reason":reason,
        "videos":retry_videos
    }
    out=retry/f"{retry_id}.json"
    out.write_text(json.dumps(retry_obj,ensure_ascii=False,indent=2),encoding="utf-8")

    retry_manifest=phase2_manifest_for_videos(retry_id,retry_videos)
    retry_manifest["parent_package_id"]=package_id
    retry_manifest["repair_reason"]=reason
    (retry/f"{retry_id}.manifest.json").write_text(
        json.dumps(retry_manifest,ensure_ascii=False,indent=2),
        encoding="utf-8"
    )

    phase2_write_history(retry_id,"RETRY_CREATED",len(retry_videos),details=reason)
    print(f"Retry package created: {out}")
    return out

def phase2_validate_result_against_manifest(result_path):
    """
    Return completeness/partial-import information.
    """
    p=Path(result_path)
    payload=json.loads(p.read_text(encoding="utf-8"))
    norm=phase2_normalize_result_payload(payload)
    if not norm:
        return None,{"fatal":"Unsupported result structure"}

    package_id=norm.get("package_id") or p.stem
    manifest_path=phase2_find_manifest(package_id)
    if not manifest_path:
        # try stripping common result suffixes
        stem=p.stem
        for suffix in ("_result","_results","_returned"):
            if stem.endswith(suffix):
                manifest_path=phase2_find_manifest(stem[:-len(suffix)])
                if manifest_path:
                    package_id=stem[:-len(suffix)]
                    break

    if not manifest_path:
        return norm,{
            "package_id":package_id,
            "manifest_found":False,
            "expected":[],
            "returned":[str(v.get("video_id") or "") for v in norm["videos"]],
            "missing":[],
            "unexpected":[],
            "duplicate_returned":[]
        }

    manifest=json.loads(manifest_path.read_text(encoding="utf-8"))
    expected=[str(x) for x in (manifest.get("expected_video_ids") or [])]
    returned=[str(v.get("video_id") or "") for v in norm["videos"] if str(v.get("video_id") or "").strip()]

    duplicates=sorted({x for x in returned if returned.count(x)>1})
    missing=[x for x in expected if x not in returned]
    unexpected=[x for x in returned if x not in expected]

    return norm,{
        "package_id":package_id,
        "manifest_found":True,
        "manifest_path":str(manifest_path),
        "expected":expected,
        "returned":returned,
        "missing":missing,
        "unexpected":unexpected,
        "duplicate_returned":duplicates
    }

def phase2_archive_package(package_id,force=False):
    packages,results,retry,archive,history=phase2_chatgpt_dirs()

    if not force:
        complete,problems=package_is_fully_complete(package_id)
        if not complete:
            print(f"Package {package_id} is NOT complete and will not be archived.")
            for problem in problems:
                print(f"  {problem}")
            return None
    month=time.strftime("%Y-%m")
    dest=archive/month/package_id
    dest.mkdir(parents=True,exist_ok=True)

    moved=0
    source_dirs=[packages,results]
    for d in phase2_legacy_paths()["packages"]+phase2_legacy_paths()["results"]:
        if d.exists() and d not in source_dirs:
            source_dirs.append(d)

    for base in source_dirs:
        for p in list(base.glob(f"{package_id}*")):
            try:
                target=dest/p.name
                if target.exists():
                    target.unlink()
                shutil.move(str(p),str(target))
                moved+=1
            except Exception:
                pass

    phase2_write_history(package_id,"ARCHIVED",details=f"Moved {moved} files")
    print(f"Archived package {package_id} -> {dest}")
    return dest

def phase2_package_dashboard():
    packages,results,retry,archive,history=phase2_chatgpt_dirs()

    synced,manifests_created=phase2_sync_legacy_packages()
    if synced or manifests_created:
        print(f"Synced legacy packages: {synced}, manifests created: {manifests_created}")

    manifests=[]
    seen=set()
    for d in phase2_all_package_dirs():
        for mp in d.glob("*.manifest.json"):
            rp=str(mp.resolve())
            if rp not in seen:
                seen.add(rp)
                manifests.append(mp)

    print("")
    print("===== CHATGPT PACKAGE DASHBOARD =====")
    if not manifests:
        print("No pending package manifests found.")
        print("Checked package folders:")
        for d in phase2_all_package_dirs():
            print(f"  {d}")
        return

    for mp in sorted(manifests,key=lambda p:p.name.lower()):
        try:
            man=json.loads(mp.read_text(encoding="utf-8"))
            pkg=man.get("package_id") or mp.stem.replace(".manifest","")
            expected=len(man.get("expected_video_ids") or [])
            result_files=[]
            for rd in phase2_all_result_dirs():
                result_files.extend(rd.glob(f"{pkg}*.json"))
            returned=0
            imported=0
            reports=0

            if result_files:
                try:
                    norm,info=phase2_validate_result_against_manifest(result_files[0])
                    returned=len(info.get("returned") or [])
                except Exception:
                    pass

            vids=man.get("expected_video_ids") or []
            con=db_connect()
            if vids:
                q=",".join("?" for _ in vids)
                rows=con.execute(
                    f"SELECT chatgpt_imported,report_html FROM videos WHERE video_id IN ({q})",
                    vids
                ).fetchall()
                imported=sum(1 for x,_ in rows if int(x or 0)==1)
                reports=sum(1 for _,rp in rows if rp and Path(rp).exists())
            con.close()

            print(f"{pkg} | expected={expected} | returned={returned} | imported={imported} | reports={reports}")
            status_rows=phase2_package_status_rows(pkg)
            not_returned=sum(1 for r in status_rows if r["status"]=="NOT_RETURNED")
            returned_not_imported=sum(1 for r in status_rows if r["status"]=="RETURNED_NOT_IMPORTED")
            if not_returned or returned_not_imported:
                print(f"  Problems: not returned={not_returned}, returned but not imported={returned_not_imported}")

            complete,archive_problems=package_is_fully_complete(pkg)
            print(f"  Archive eligible: {'YES' if complete else 'NO'}")
        except Exception as ex:
            print(f"{mp.name} | ERROR {ex}")


def phase2_import_result_file(result_path):
    """
    Import ONLY the selected ChatGPT result file.

    - Does not invoke the legacy folder-scanning importer.
    - Good videos import independently.
    - Missing/rejected videos get explicit reasons.
    - Automatic Phase 3 -> Phase 4 -> report pipeline runs for imported videos.
    """
    p=Path(result_path)
    norm,info=phase2_validate_result_against_manifest(p)
    if not norm:
        print(f"Rejected result: {info.get('fatal')}")
        return

    pkg=info.get("package_id") or p.stem
    expected=info.get("expected") or []
    returned_videos=norm.get("videos") or []

    try:
        phase5_build_all()
    except Exception as _p5_ex:
        print(f"Phase 5 refresh warning: {type(_p5_ex).__name__}: {_p5_ex}")

    returned_map={}
    duplicate_ids=set()

    for v in returned_videos:
        if not isinstance(v,dict):
            continue
        vid=str(v.get("video_id") or "").strip()
        if not vid:
            continue
        if vid in returned_map:
            duplicate_ids.add(vid)
            continue
        returned_map[vid]=v

    problem_reasons={}
    imported_ids=[]

    # Missing from ChatGPT result.
    for vid in expected:
        if vid not in returned_map:
            problem_reasons[vid]="Missing from ChatGPT returned result"

    # Duplicate IDs in result.
    for vid in duplicate_ids:
        problem_reasons[vid]="Duplicate Video ID in ChatGPT returned result"

    # Report unexpected IDs but don't silently import them into a different package.
    for vid in info.get("unexpected") or []:
        print(f"WARNING unexpected Video ID in selected result: {vid}")

    target_ids=expected or list(returned_map.keys())

    for vid in target_ids:
        if vid not in returned_map or vid in duplicate_ids:
            continue

        obj=returned_map[vid]

        # If this exact canonical summary is already present/imported, don't recreate it.
        con=db_connect()
        dbrow=con.execute(
            "SELECT chatgpt_imported,chatgpt_summary_file FROM videos WHERE video_id=?",
            (vid,)
        ).fetchone()
        con.close()

        already_imported=False
        if dbrow and int(dbrow[0] or 0)==1 and dbrow[1]:
            try:
                cp=Path(dbrow[1])
                if cp.exists():
                    existing=json.loads(cp.read_text(encoding="utf-8"))
                    # Compare the substantive returned video object, ignoring wrapper metadata.
                    comparable=dict(existing)
                    comparable.pop("package_id",None)
                    comparable.pop("schema_version",None)
                    candidate=dict(obj)
                    candidate.pop("package_id",None)
                    candidate.pop("schema_version",None)
                    already_imported=(
                        json.dumps(comparable,ensure_ascii=False,sort_keys=True)
                        == json.dumps(candidate,ensure_ascii=False,sort_keys=True)
                    )
            except Exception:
                already_imported=False

        if already_imported:
            imported_ids.append(vid)
            print(f"SKIP {vid}: same ChatGPT content already imported")
            continue

        ok,reason=phase2_import_single_video_payload(pkg,obj)
        if ok:
            imported_ids.append(vid)
            print(f"IMPORTED {vid}: {reason}")
        else:
            problem_reasons[vid]=reason
            print(f"REJECTED {vid}: {reason}")

    problem_ids=sorted(problem_reasons)

    # Per-video import-status audit.
    audit_dir=BASE/"maintenance"/"audits"
    audit_dir.mkdir(parents=True,exist_ok=True)
    reason_file=audit_dir/f"{pkg}_import_status.csv"
    with open(reason_file,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Status","Reason"])
        for vid in target_ids:
            if vid in imported_ids:
                w.writerow([vid,"IMPORTED","Imported successfully / already current"])
            elif vid in problem_reasons:
                w.writerow([vid,"NOT_IMPORTED",problem_reasons[vid]])
            else:
                w.writerow([vid,"UNKNOWN","No final state"])

    # Count report state before post-pipeline.
    reports=0
    if imported_ids:
        con=db_connect()
        q=",".join("?" for _ in imported_ids)
        rows=con.execute(
            f"SELECT report_html FROM videos WHERE video_id IN ({q})",
            imported_ids
        ).fetchall()
        con.close()
        reports=sum(1 for (rp,) in rows if rp and Path(rp).exists())

    phase2_write_history(
        pkg,
        "PARTIAL_IMPORTED" if problem_ids else "IMPORTED",
        len(target_ids),
        len(info.get("returned") or []),
        len(imported_ids),
        reports,
        " | ".join(f"{vid}: {problem_reasons[vid]}" for vid in problem_ids)
    )

    # Missing/import failures get retry package.
    if problem_ids and CFG.get("chatgpt_auto_retry_package",True):
        try:
            phase2_create_retry_package(
                pkg,
                problem_ids,
                " | ".join(f"{vid}: {problem_reasons[vid]}" for vid in problem_ids)
            )
        except Exception as ex:
            print(f"Retry package warning: {type(ex).__name__}: {ex}")

    print("")
    print(f"Package : {pkg}")
    print(f"Expected: {len(target_ids)}")
    print(f"Returned: {len(info.get('returned') or [])}")
    print(f"Imported: {len(imported_ids)}")
    print(f"Problems: {len(problem_ids)}")
    for vid in problem_ids:
        print(f"  {vid}: {problem_reasons[vid]}")
    print(f"Details : {reason_file}")

    # Automatic post-ChatGPT orchestration.
    if CFG.get("auto_post_chatgpt_pipeline",True) and imported_ids:
        try:
            auto_post_chatgpt_pipeline_for_videos(pkg,imported_ids)
        except Exception as ex:
            print(f"Automatic post-ChatGPT pipeline failed: {type(ex).__name__}: {ex}")


def phase2_package_status_rows(package_id):
    manifest_path=phase2_find_manifest(package_id)
    if not manifest_path:
        return []

    manifest=json.loads(manifest_path.read_text(encoding="utf-8"))
    expected=[str(x) for x in (manifest.get("expected_video_ids") or [])]

    # Find most relevant result file.
    result_file=None
    for d in phase2_all_result_dirs():
        cands=sorted(d.glob(f"*{package_id.split('chatgpt_package_')[-1]}*.json"))
        if cands:
            result_file=cands[-1]
            break
        cands=sorted(d.glob(f"{package_id}*.json"))
        if cands:
            result_file=cands[-1]
            break

    returned_ids=[]
    returned_map={}
    if result_file and result_file.exists():
        try:
            payload=json.loads(result_file.read_text(encoding="utf-8"))
            norm=phase2_normalize_result_payload(payload)
            if norm:
                for v in norm.get("videos") or []:
                    vid=str(v.get("video_id") or "").strip()
                    if vid:
                        returned_ids.append(vid)
                        returned_map[vid]=v
        except Exception:
            pass

    con=db_connect()
    rows={}
    if expected:
        q=",".join("?" for _ in expected)
        dbrows=con.execute(
            f"""SELECT video_id,original_title,clean_title,chatgpt_imported,
                       chatgpt_summary_file,failure_reason
                FROM videos WHERE video_id IN ({q})""",
            expected
        ).fetchall()
        rows={r[0]:r for r in dbrows}
    con.close()

    out=[]
    for vid in expected:
        db=rows.get(vid)
        title=(db[2] or db[1] or "") if db else ""
        imported=bool(db and int(db[3] or 0)==1)
        summary_file=(db[4] or "") if db else ""
        failure_reason=(db[5] or "") if db else ""

        if imported:
            status="IMPORTED"
            reason="Already imported successfully"
        elif vid not in returned_ids:
            status="NOT_RETURNED"
            reason="Missing from ChatGPT returned result"
        elif vid in returned_ids:
            status="RETURNED_NOT_IMPORTED"
            reason=failure_reason or "Returned by ChatGPT but not imported; validation/import issue"
        else:
            status="UNKNOWN"
            reason="Unknown state"

        out.append({
            "video_id":vid,
            "title":title,
            "status":status,
            "reason":reason,
            "result_file":str(result_file or ""),
            "summary_file":summary_file
        })
    return out


def phase2_choose_package():
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    phase2_sync_legacy_packages()

    manifests=[]
    seen=set()
    for d in phase2_all_package_dirs():
        for mp in sorted(d.glob("*.manifest.json")):
            try:
                obj=json.loads(mp.read_text(encoding="utf-8"))
                pkg=str(obj.get("package_id") or mp.stem.replace(".manifest",""))
                if pkg not in seen:
                    seen.add(pkg)
                    manifests.append((pkg,mp,obj))
            except Exception:
                pass

    if not manifests:
        print("No packages/manifests found.")
        return None

    print("")
    print("Select Package")
    for i,(pkg,mp,obj) in enumerate(manifests,1):
        statuses=phase2_package_status_rows(pkg)
        expected=len(obj.get("expected_video_ids") or [])
        imported=sum(1 for x in statuses if x["status"]=="IMPORTED")
        not_returned=sum(1 for x in statuses if x["status"]=="NOT_RETURNED")
        returned_not_imported=sum(1 for x in statuses if x["status"]=="RETURNED_NOT_IMPORTED")
        print(
            f"{i} = {pkg} | expected={expected} | imported={imported} | "
            f"not returned={not_returned} | returned/not imported={returned_not_imported}"
        )
    print("0 = Cancel")

    raw=input("Choose package: ").strip()
    if raw=="0" or not raw:
        return None
    try:
        idx=int(raw)
        if 1 <= idx <= len(manifests):
            return manifests[idx-1][0]
    except Exception:
        pass
    print("Invalid selection.")
    return None


def phase2_choose_problem_videos(package_id):
    rows=phase2_package_status_rows(package_id)
    problems=[r for r in rows if r["status"]!="IMPORTED"]

    if not problems:
        print("No problem videos in this package.")
        return []

    print("")
    print(f"Problem videos for {package_id}:")
    for i,r in enumerate(problems,1):
        print(f"{i} = {r['video_id']} | {r['status']} | {r['title']}")
        print(f"    Reason: {r['reason']}")
    print("A = All problem videos")
    print("0 = Cancel")

    raw=input("Choose video(s), comma separated: ").strip()
    if not raw or raw=="0":
        return []
    if raw.lower()=="a":
        return [r["video_id"] for r in problems]

    selected=[]
    for part in raw.split(","):
        try:
            idx=int(part.strip())
            if 1 <= idx <= len(problems):
                selected.append(problems[idx-1]["video_id"])
        except Exception:
            pass
    return sorted(set(selected))


def phase2_import_single_video_payload(package_id, video_obj):
    """
    Import exactly one video payload without scanning every legacy result file.
    Uses the existing canonical normalization/distribution logic directly.
    """
    vid=str(video_obj.get("video_id") or "").strip()
    if not vid:
        return False,"Missing Video ID"

    try:
        norm=normalize_chatgpt_result_video(video_obj)
    except Exception as ex:
        return False,f"Normalization failed: {ex}"

    # Use the existing validation helpers.
    sections=norm.get("sections") or []
    try:
        sections,ts_errors,ts_warnings=validate_and_normalize_sections(sections)
    except Exception as ex:
        return False,f"Timestamp validation failed: {ex}"

    if ts_errors:
        return False,"; ".join(ts_errors)

    folder=locate_existing_folder(vid)
    if folder is None:
        return False,"Video folder not found"
    folder=Path(folder)

    # Canonical payload based on existing importer format.
    payload=dict(video_obj)
    payload["package_id"]=package_id
    payload["schema_version"]=int(CFG.get("chatgpt_schema_version",2))
    payload["video_id"]=vid
    payload["sections"]=sections

    canonical=canonical_chatgpt_summary_path(folder,vid)
    canonical.parent.mkdir(parents=True,exist_ok=True)
    canonical.write_text(
        json.dumps(payload,ensure_ascii=False,indent=2),
        encoding="utf-8"
    )

    # Build DB fields.
    meaningful_title=str(
        payload.get("meaningful_title")
        or payload.get("imported_title")
        or norm.get("meaningful_title")
        or ""
    ).strip()
    category=str(norm.get("category") or payload.get("category") or "")
    subcategory=str(norm.get("subcategory") or payload.get("subcategory") or "")
    tags=norm.get("tags") or payload.get("tags") or []
    if isinstance(tags,list):
        tags_text=", ".join(str(x) for x in tags if str(x).strip())
    else:
        tags_text=str(tags or "")

    result_hash=short_hash(json.dumps(payload,ensure_ascii=False,sort_keys=True))

    con=db_connect()
    cols=video_table_columns()

    sets=[
        "chatgpt_summary_file=?",
        "chatgpt_imported=1",
        "chatgpt_result_hash=?",
        "category=?",
        "subcategory=?",
        "tags=?"
    ]
    vals=[
        str(canonical),
        result_hash,
        category,
        subcategory,
        tags_text
    ]

    if "identity_json" in cols:
        sets.append("identity_json=?")
        identity={
            "meaningful_title":meaningful_title,
            "summary":str(
                payload.get("summary")
                or payload.get("overall_summary")
                or norm.get("summary")
                or ""
            )
        }
        vals.append(json.dumps(identity,ensure_ascii=False))

    if "chapters_temp" in cols:
        sets.append("chapters_temp=?")
        vals.append(json.dumps(sections,ensure_ascii=False))

    vals.append(vid)
    con.execute(
        f"UPDATE videos SET {', '.join(sets)} WHERE video_id=?",
        vals
    )
    con.commit()
    con.close()

    # Regenerate report only for this imported video.
    try:
        title=resolved_approved_title(vid,meaningful_title or None)
        ok,msg=rebuild_report_after_rename(vid,folder,title)
        if not ok:
            return False,f"Imported summary but report rebuild failed: {msg}"
    except Exception as ex:
        return False,f"Imported summary but report rebuild failed: {ex}"

    return True,"Imported and report regenerated"



def phase2_package_manager():
    packages,results,retry,archive,history=phase2_chatgpt_dirs()
    try:
        phase2_migrate_legacy_storage(copy_only=True);phase2_sync_legacy_packages()
    except Exception as ex: print(f"Phase 2 compatibility sync warning: {ex}")
    while True:
        print("""
============================================================
 PHASE 2 - CHATGPT PACKAGE MANAGER + AUTO POST-PROCESS
============================================================
1 = Package Dashboard
2 = Validate Detected Result File Against Manifest
3 = Import Detected Result File with Partial Import + Retry
4 = Create Retry Package Manually
5 = Archive Completed Package
6 = Show Package History CSV Path
7 = Legacy Migration — Sync ChatGPT Folders [Copy Only]
8 = Phase 2 Package Integrity & Completeness Audit
9 = Run Automatic Post-ChatGPT Pipeline for Existing Package
0 = Back
""")
        c=input("Choose: ").strip()
        if c=='1': phase2_package_dashboard()
        elif c=='2':
            p=phase2_choose_result_file()
            if p:
                try:
                    norm,info=phase2_validate_result_against_manifest(p);print(json.dumps(info,indent=2))
                except Exception as ex: print(f"Validation failed: {type(ex).__name__}: {ex}")
        elif c=='3':
            p=phase2_choose_result_file()
            if p:
                try: phase2_import_result_file(p)
                except Exception as ex: print(f"Import failed: {type(ex).__name__}: {ex}")
        elif c=='4':
            pkg=phase2_choose_package()
            if pkg:
                ids=phase2_choose_problem_videos(pkg)
                if ids:
                    sm={r['video_id']:r for r in phase2_package_status_rows(pkg)}
                    phase2_create_retry_package(pkg,ids,' | '.join(f"{vid}: {sm.get(vid,{}).get('reason','Manual retry')}" for vid in ids))
        elif c=='5':
            pkg=phase2_choose_package()
            if pkg: phase2_archive_package(pkg)
        elif c=='6': print(history)
        elif c=='7': phase2_migrate_legacy_storage(copy_only=True);phase2_sync_legacy_packages()
        elif c=='8': phase2_package_integrity_completeness_audit()
        elif c=='9':
            pkg=phase2_choose_package()
            if pkg: auto_post_chatgpt_pipeline_for_package(pkg)
        elif c=='0': break


def _p3_seconds(value):
    if value is None:
        return None
    if isinstance(value,(int,float)):
        return float(value)
    s=str(value).strip()
    if not s:
        return None
    parts=s.split(":")
    try:
        if len(parts)==3:
            h,m,sec=parts
            return int(h)*3600+int(m)*60+float(sec)
        if len(parts)==2:
            m,sec=parts
            return int(m)*60+float(sec)
        return float(s)
    except Exception:
        return None

def _p3_fmt(sec):
    if sec is None:
        return ""
    sec=max(0,int(round(sec)))
    h=sec//3600
    m=(sec%3600)//60
    s=sec%60
    return f"{h:02d}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"

def _p3_ascii_ratio(text_value):
    text=str(text_value or "")
    letters=[c for c in text if c.isalpha()]
    if not letters:
        return 1.0
    latin=sum(1 for c in letters if ("A"<=c<="Z" or "a"<=c<="z"))
    return latin/len(letters)

def _p3_extract_numbers(text_value):
    text=str(text_value or "")
    # preserve numbers, decimals, ratios, percentages and common fractions
    pats=re.findall(
        r'(?<!\w)(?:\d+(?:\.\d+)?\s*[:/]\s*\d+(?:\.\d+)?|\d+(?:\.\d+)?%?|\b(?:1/2|1/3|1/4|3/4)\b)',
        text
    )
    return [re.sub(r'\s+','',x.lower()) for x in pats]

def _p3_extract_units(text_value):
    text=str(text_value or "").lower()
    units=re.findall(
        r'\b\d+(?:\.\d+)?\s*(?:mg|g|kg|ml|l|teaspoon|teaspoons|tsp|tablespoon|tablespoons|tbsp|minutes?|mins?|hours?|hrs?|days?|weeks?|months?|years?|°c|°f)\b',
        text
    )
    return [re.sub(r'\s+',' ',x.strip()) for x in units]

def _p3_get_video_duration(video_id, sections=None):
    con=db_connect()
    cols=video_table_columns()
    duration_expr="duration_iso" if "duration_iso" in cols else "NULL AS duration_iso"
    row=con.execute(
        f"SELECT {duration_expr} FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()

    if row and row[0]:
        iso=str(row[0])
        m=re.fullmatch(r'PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?',iso)
        if m:
            return int(m.group(1) or 0)*3600+int(m.group(2) or 0)*60+int(m.group(3) or 0)

    if sections:
        ends=[_p3_seconds(s.get("end") or s.get("end_time")) for s in sections if isinstance(s,dict)]
        ends=[x for x in ends if x is not None]
        if ends:
            return max(ends)
    return None

def _p3_section_times(section):
    start=_p3_seconds(section.get("start") or section.get("start_time") or section.get("timestamp_start"))
    end=_p3_seconds(section.get("end") or section.get("end_time") or section.get("timestamp_end"))
    return start,end

def phase3_timestamp_analysis(video_id, sections):
    intervals=[]
    nested=[]
    invalid=[]
    for idx,s in enumerate(sections):
        if not isinstance(s,dict):
            invalid.append({"index":idx,"reason":"Section is not object"})
            continue
        start,end=_p3_section_times(s)
        if start is None or end is None or end<=start:
            invalid.append({"index":idx,"reason":"Invalid/missing timestamp","start":start,"end":end})
            continue
        intervals.append((start,end,idx,s))

    intervals.sort(key=lambda x:(x[0],x[1]))
    top_level=[]

    # Treat fully-contained overlaps as nested subtopics, not errors.
    for cur in intervals:
        placed=False
        for parent in reversed(top_level):
            if cur[0]>=parent[0] and cur[1]<=parent[1]:
                nested.append({
                    "child_index":cur[2],
                    "parent_index":parent[2],
                    "child_range":f"{_p3_fmt(cur[0])}-{_p3_fmt(cur[1])}",
                    "parent_range":f"{_p3_fmt(parent[0])}-{_p3_fmt(parent[1])}"
                })
                placed=True
                break
        if not placed:
            top_level.append(cur)

    # Coverage uses union of all valid intervals.
    merged=[]
    for start,end,idx,s in intervals:
        if not merged or start>merged[-1][1]:
            merged.append([start,end])
        else:
            merged[-1][1]=max(merged[-1][1],end)

    duration=_p3_get_video_duration(video_id,sections)
    covered=sum(end-start for start,end in merged)
    coverage=(covered/duration) if duration and duration>0 else None

    gaps=[]
    if duration and merged:
        cursor=0.0
        for start,end in merged:
            if start>cursor:
                gaps.append((cursor,start))
            cursor=max(cursor,end)
        if cursor<duration:
            gaps.append((cursor,duration))

    # Partial overlaps that are not containment.
    overlap_warnings=[]
    for i in range(len(intervals)-1):
        a=intervals[i]
        b=intervals[i+1]
        if b[0]<a[1] and not (b[0]>=a[0] and b[1]<=a[1]) and not (a[0]>=b[0] and a[1]<=b[1]):
            overlap_warnings.append({
                "a_index":a[2],"b_index":b[2],
                "a":f"{_p3_fmt(a[0])}-{_p3_fmt(a[1])}",
                "b":f"{_p3_fmt(b[0])}-{_p3_fmt(b[1])}"
            })

    return {
        "duration_seconds":duration,
        "covered_seconds":covered,
        "coverage_ratio":coverage,
        "gaps":[{"start":_p3_fmt(a),"end":_p3_fmt(b),"seconds":round(b-a,1)} for a,b in gaps],
        "nested_sections":nested,
        "partial_overlap_warnings":overlap_warnings,
        "invalid_sections":invalid
    }

def phase3_language_analysis(summary_obj, sections):
    fields=[]
    for label,key in [
        ("Meaningful Title","meaningful_title"),
        ("Overall Summary","overall_summary"),
        ("Summary","summary")
    ]:
        val=str(summary_obj.get(key) or "").strip()
        if val:
            fields.append((label,val))

    for i,s in enumerate(sections):
        if not isinstance(s,dict):
            continue
        for label,key in [
            (f"Section {i+1} Heading","title"),
            (f"Section {i+1} Heading","heading"),
            (f"Section {i+1} Summary","detailed_summary"),
            (f"Section {i+1} Summary","summary")
        ]:
            val=str(s.get(key) or "").strip()
            if val:
                fields.append((label,val))
                break

    out=[]
    threshold=float(CFG.get("phase3_min_english_ratio",0.75))
    for label,val in fields:
        ratio=_p3_ascii_ratio(val)
        out.append({
            "field":label,
            "english_ratio":round(ratio,3),
            "status":"PASS" if ratio>=threshold else "FAIL"
        })
    return out

def phase3_fact_preservation(video_id, summary_obj, sections):
    folder=locate_existing_folder(video_id)
    if not folder:
        return {"status":"UNKNOWN","reason":"Video folder not found"}

    folder=Path(folder)
    transcript_files=list(support_dir(folder).glob("*.transcript_timestamped.txt"))
    if not transcript_files:
        transcript_files=list(support_dir(folder).glob("*.transcript_clean.txt"))
    if not transcript_files:
        return {"status":"UNKNOWN","reason":"Transcript not found"}

    source=transcript_files[0].read_text(encoding="utf-8",errors="replace")

    target_parts=[
        str(summary_obj.get("overall_summary") or ""),
        str(summary_obj.get("summary") or ""),
        str(summary_obj.get("meaningful_title") or "")
    ]
    for s in sections:
        if isinstance(s,dict):
            target_parts.extend([
                str(s.get("title") or s.get("heading") or ""),
                str(s.get("detailed_summary") or s.get("summary") or ""),
                json.dumps(s.get("steps") or s.get("instructions") or [],ensure_ascii=False)
            ])
    target="\n".join(target_parts)

    src_nums=set(_p3_extract_numbers(source))
    tgt_nums=set(_p3_extract_numbers(target))
    src_units=set(_p3_extract_units(source))
    tgt_units=set(_p3_extract_units(target))

    num_ratio=(len(src_nums & tgt_nums)/len(src_nums)) if src_nums else 1.0
    unit_ratio=(len(src_units & tgt_units)/len(src_units)) if src_units else 1.0
    combined=(num_ratio+unit_ratio)/2

    threshold=float(CFG.get("phase3_numeric_preservation_threshold",0.75))
    return {
        "source_numeric_count":len(src_nums),
        "preserved_numeric_count":len(src_nums & tgt_nums),
        "numeric_ratio":round(num_ratio,3),
        "source_unit_count":len(src_units),
        "preserved_unit_count":len(src_units & tgt_units),
        "unit_ratio":round(unit_ratio,3),
        "combined_ratio":round(combined,3),
        "status":"PASS" if combined>=threshold else "WARN",
        "missing_numbers":sorted(src_nums-tgt_nums)[:50],
        "missing_units":sorted(src_units-tgt_units)[:50]
    }

def phase3_chapter_confidence(sections):
    results=[]
    for i,s in enumerate(sections):
        if not isinstance(s,dict):
            continue
        start,end=_p3_section_times(s)
        title=str(s.get("title") or s.get("heading") or "").strip()
        summary=str(s.get("detailed_summary") or s.get("summary") or "").strip()

        score=0
        if start is not None and end is not None and end>start:
            score+=40
        if title and len(title)>=4:
            score+=25
        if summary and len(summary)>=60:
            score+=25
        if end is not None and start is not None and (end-start)>=15:
            score+=10

        if score>=85:
            level="HIGH"
        elif score>=65:
            level="MEDIUM"
        else:
            level="LOW"

        results.append({
            "index":i,
            "title":title,
            "range":f"{_p3_fmt(start)}-{_p3_fmt(end)}",
            "score":score,
            "confidence":level
        })
    return results

def phase3_quality_score(video_id, summary_obj, sections):
    lang=phase3_language_analysis(summary_obj,sections)
    ts=phase3_timestamp_analysis(video_id,sections)
    facts=phase3_fact_preservation(video_id,summary_obj,sections)
    conf=phase3_chapter_confidence(sections)

    english_pass=(sum(1 for x in lang if x["status"]=="PASS")/len(lang)) if lang else 1.0
    coverage=ts.get("coverage_ratio")
    coverage_score=min(1.0,coverage) if coverage is not None else 0.5
    fact_score=float(facts.get("combined_ratio",0.5))
    chapter_score=(sum(x["score"] for x in conf)/(100*len(conf))) if conf else 0.5

    has_title=bool(str(summary_obj.get("meaningful_title") or "").strip())
    has_overall=bool(str(summary_obj.get("overall_summary") or summary_obj.get("summary") or "").strip())
    has_sections=bool(sections)

    completeness=(sum([has_title,has_overall,has_sections])/3)

    score=round(
        20*english_pass +
        25*coverage_score +
        20*fact_score +
        15*chapter_score +
        20*completeness
    )

    pass_cut=int(CFG.get("phase3_quality_score_pass",85))
    warn_cut=int(CFG.get("phase3_quality_score_warn",70))
    status="PASS" if score>=pass_cut else ("WARN" if score>=warn_cut else "FAIL")

    return {
        "score":score,
        "status":status,
        "english_field_pass_ratio":round(english_pass,3),
        "timestamp_coverage_ratio":coverage,
        "fact_preservation_ratio":facts.get("combined_ratio"),
        "chapter_confidence_ratio":round(chapter_score,3),
        "completeness_ratio":round(completeness,3)
    }

def phase3_validate_video(video_id):
    folder=locate_existing_folder(video_id)
    if not folder:
        return None,{"fatal":"Video folder not found"}

    summary_path=canonical_chatgpt_summary_path(folder,video_id)
    if not summary_path.exists():
        return None,{"fatal":"Canonical ChatGPT summary missing"}

    try:
        summary_obj=json.loads(summary_path.read_text(encoding="utf-8"))
    except Exception as ex:
        return None,{"fatal":f"Invalid summary JSON: {ex}"}

    norm=normalize_chatgpt_result_video(summary_obj)
    sections=norm.get("sections") or summary_obj.get("sections") or []

    report={
        "video_id":video_id,
        "language":phase3_language_analysis(summary_obj,sections),
        "timestamps":phase3_timestamp_analysis(video_id,sections),
        "fact_preservation":phase3_fact_preservation(video_id,summary_obj,sections),
        "chapter_confidence":phase3_chapter_confidence(sections),
        "quality":phase3_quality_score(video_id,summary_obj,sections)
    }
    return report,None

def phase3_write_video_report(video_id, report):
    audit_dir=BASE/"maintenance"/"audits"/"phase3"
    audit_dir.mkdir(parents=True,exist_ok=True)
    out=audit_dir/f"{video_id}.quality.json"
    out.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    return out

def phase3_validate_all():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id FROM videos WHERE chatgpt_imported=1 ORDER BY rowid"
    ).fetchall()
    con.close()

    summary_rows=[]
    passed=warned=failed=missing=0

    for (vid,) in rows:
        report,err=phase3_validate_video(vid)
        if err:
            missing+=1
            summary_rows.append({
                "Video ID":vid,"Status":"MISSING","Score":"",
                "English Pass":"","Coverage":"","Fact Preservation":"",
                "Low Confidence Chapters":"","Gap Count":"","Reason":err.get("fatal","")
            })
            continue

        phase3_write_video_report(vid,report)
        q=report["quality"]
        status=q["status"]
        if status=="PASS": passed+=1
        elif status=="WARN": warned+=1
        else: failed+=1

        lang=report["language"]
        english_pass=f"{sum(1 for x in lang if x['status']=='PASS')}/{len(lang)}" if lang else ""
        cov=report["timestamps"].get("coverage_ratio")
        fact=report["fact_preservation"].get("combined_ratio")
        low=sum(1 for x in report["chapter_confidence"] if x["confidence"]=="LOW")
        gaps=len(report["timestamps"].get("gaps") or [])

        summary_rows.append({
            "Video ID":vid,
            "Status":status,
            "Score":q["score"],
            "English Pass":english_pass,
            "Coverage":round(cov,3) if cov is not None else "",
            "Fact Preservation":fact,
            "Low Confidence Chapters":low,
            "Gap Count":gaps,
            "Reason":""
        })

    audit_dir=BASE/"maintenance"/"audits"
    audit_dir.mkdir(parents=True,exist_ok=True)
    out=audit_dir/"phase3_summary_quality.csv"
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        fields=[
            "Video ID","Status","Score","English Pass","Coverage",
            "Fact Preservation","Low Confidence Chapters","Gap Count","Reason"
        ]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        w.writerows(summary_rows)

    print("")
    print("===== PHASE 3 SUMMARY QUALITY =====")
    print(f"Imported videos checked: {len(rows)}")
    print(f"PASS   : {passed}")
    print(f"WARN   : {warned}")
    print(f"FAIL   : {failed}")
    print(f"MISSING: {missing}")
    print(f"Details: {out}")
    return out

def phase3_show_video_details():
    vid=input("Video ID: ").strip()
    if not vid:
        return
    report,err=phase3_validate_video(vid)
    if err:
        print(err.get("fatal"))
        return

    q=report["quality"]
    print("")
    print(f"Video ID: {vid}")
    print(f"Quality: {q['status']} {q['score']}/100")

    print("\nLanguage:")
    for x in report["language"]:
        print(f"  {x['status']} | {x['field']} | English ratio={x['english_ratio']}")

    ts=report["timestamps"]
    cov=ts.get("coverage_ratio")
    print("\nTimestamps:")
    print(f"  Coverage: {round(cov*100,1) if cov is not None else 'Unknown'}%")
    for g in ts.get("gaps") or []:
        print(f"  GAP: {g['start']} - {g['end']} ({g['seconds']} sec)")
    for n in ts.get("nested_sections") or []:
        print(f"  NESTED: child {n['child_range']} inside parent {n['parent_range']}")
    for o in ts.get("partial_overlap_warnings") or []:
        print(f"  OVERLAP WARNING: {o['a']} overlaps {o['b']}")

    facts=report["fact_preservation"]
    print("\nFact/Numeric preservation:")
    print(f"  Status: {facts.get('status')}")
    print(f"  Combined: {facts.get('combined_ratio')}")
    if facts.get("missing_numbers"):
        print("  Missing numbers:",", ".join(facts["missing_numbers"][:20]))
    if facts.get("missing_units"):
        print("  Missing units:",", ".join(facts["missing_units"][:20]))

    print("\nChapter confidence:")
    for c in report["chapter_confidence"]:
        print(f"  {c['confidence']} {c['score']:3} | {c['range']} | {c['title']}")

    out=phase3_write_video_report(vid,report)
    print(f"\nSaved: {out}")

def phase3_create_retry_for_failed():
    """
    Create retry package containing videos whose Phase 3 quality is FAIL.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id FROM videos WHERE chatgpt_imported=1 ORDER BY rowid"
    ).fetchall()
    con.close()

    failed_ids=[]
    reasons=[]
    for (vid,) in rows:
        report,err=phase3_validate_video(vid)
        if err:
            continue
        if report["quality"]["status"]=="FAIL":
            failed_ids.append(vid)
            reasons.append(f"{vid}: quality score {report['quality']['score']}")

    if not failed_ids:
        print("No Phase 3 FAIL videos found.")
        return

    # group by originating package when possible
    package_map={}
    for vid in failed_ids:
        found_pkg=None
        for d in phase2_all_package_dirs():
            for mp in d.glob("*.manifest.json"):
                try:
                    obj=json.loads(mp.read_text(encoding="utf-8"))
                    if vid in (obj.get("expected_video_ids") or []):
                        found_pkg=str(obj.get("package_id") or mp.stem.replace(".manifest",""))
                        break
                except Exception:
                    pass
            if found_pkg: break
        package_map.setdefault(found_pkg or "unknown",[]).append(vid)

    for pkg,ids in package_map.items():
        if pkg=="unknown":
            print("Could not map these videos to a package:",", ".join(ids))
            continue
        phase2_create_retry_package(
            pkg,
            ids,
            "Phase 3 quality failure"
        )

def phase3_quality_manager():
    while True:
        print("""
============================================================
 CHATGPT SUMMARY QUALITY / VALIDATION
============================================================
1 = Import, Validate & Extract ChatGPT Results
2 = Show Detailed Quality for One Video
3 = Create Retry Package for Phase 3 FAIL Videos
4 = Open Phase 3 Audit Folder
0 = Back
""")
        c=input("Choose: ").strip()
        if c=='1': import_validate_extract_chatgpt_results()
        elif c=='2': phase3_show_video_details()
        elif c=='3': phase3_create_retry_for_failed()
        elif c=='4':
            folder=BASE/'maintenance'/'audits'/'phase3';folder.mkdir(parents=True,exist_ok=True)
            try: os.startfile(str(folder))
            except Exception: print(folder)
        elif c=='0': break


def phase4_dirs():
    root=BASE/CFG.get("phase4_output_folder","data/intelligence")
    cards=BASE/CFG.get("phase4_cards_folder","data/intelligence/cards")
    tables=BASE/CFG.get("phase4_tables_folder","data/intelligence/tables")
    for p in (root,cards,tables):
        p.mkdir(parents=True,exist_ok=True)
    return root,cards,tables

def _p4_text(value):
    if value is None:
        return ""
    if isinstance(value,(dict,list)):
        try:
            return json.dumps(value,ensure_ascii=False)
        except Exception:
            return str(value)
    return str(value)

def _p4_list(value):
    if value is None:
        return []
    if isinstance(value,list):
        return [x for x in value if x not in (None,"")]
    if isinstance(value,str):
        s=value.strip()
        if not s:
            return []
        try:
            obj=json.loads(s)
            if isinstance(obj,list):
                return obj
        except Exception:
            pass
        return [x.strip() for x in re.split(r'[,;\n]+',s) if x.strip()]
    return [value]

def _p4_section_text(section):
    parts=[
        section.get("title"),
        section.get("heading"),
        section.get("summary"),
        section.get("detailed_summary"),
        section.get("source_text"),
        section.get("source_transcript"),
    ]
    parts.extend(_p4_list(section.get("steps")))
    parts.extend(_p4_list(section.get("instructions")))
    return "\n".join(_p4_text(x) for x in parts if x)

def phase4_detect_content_types(summary_obj, sections, category="", subcategory=""):
    text_blob=" ".join([
        _p4_text(category),_p4_text(subcategory),
        _p4_text(summary_obj.get("meaningful_title")),
        _p4_text(summary_obj.get("summary")),
        _p4_text(summary_obj.get("overall_summary")),
        " ".join(_p4_section_text(s) for s in sections if isinstance(s,dict))
    ]).lower()

    scores={
        "health_remedy":0,
        "cooking_recipe":0,
        "gardening_diy":0,
        "technology":0,
        "comparison":0,
        "ranked_list":0,
        "qa_interview":0
    }

    health_terms=["remedy","dosage","dose","ayurvedic","weight","blood sugar","inflammation",
                  "pregnant","medicine","medication","health","benefit","side effect","contraindication"]
    cook_terms=["recipe","ingredients","cook","bake","boil","fry","serve","tablespoon","teaspoon"]
    garden_terms=["plant","garden","grow","soil","seed","harvest","dye","compost","prune","watering","diy"]
    tech_terms=["iphone","android","phone","laptop","cpu","gpu","camera","software","app","specification",
                "processor","snapdragon","mediatek","battery","display"]
    compare_terms=["versus"," vs ","compare","comparison","better than","pros and cons"]
    rank_terms=["ranked","top 10","top 5","best ","worst ","number 1","number one"]
    qa_terms=["question","answer","interview","asks","asked","q&a"]

    for key,terms in [
        ("health_remedy",health_terms),("cooking_recipe",cook_terms),
        ("gardening_diy",garden_terms),("technology",tech_terms),
        ("comparison",compare_terms),("ranked_list",rank_terms),("qa_interview",qa_terms)
    ]:
        scores[key]=sum(1 for t in terms if t in text_blob)

    # category hints
    cat=(category+" "+subcategory).lower()
    if any(x in cat for x in ["health","ayurveda","nutrition","medical"]): scores["health_remedy"]+=4
    if any(x in cat for x in ["cooking","recipe","food"]): scores["cooking_recipe"]+=4
    if any(x in cat for x in ["garden","gardening","diy"]): scores["gardening_diy"]+=4
    if any(x in cat for x in ["technology","tech","mobile","computer"]): scores["technology"]+=4

    detected=[k for k,v in scores.items() if v>=2]
    if not detected:
        detected=["generic"]
    return detected,scores

def _p4_extract_safety(summary_obj, sections):
    terms=[str(x).lower() for x in CFG.get("phase4_health_safety_terms",[])]
    out=[]
    for i,s in enumerate(sections):
        if not isinstance(s,dict):
            continue
        text=_p4_section_text(s)
        low=text.lower()
        if any(t in low for t in terms):
            out.append({
                "section_index":i,
                "title":str(s.get("title") or s.get("heading") or ""),
                "start":str(s.get("start") or s.get("start_time") or ""),
                "end":str(s.get("end") or s.get("end_time") or ""),
                "text":str(s.get("detailed_summary") or s.get("summary") or text)[:2000]
            })
    # Explicit model-produced safety field
    for x in _p4_list(summary_obj.get("safety"))+_p4_list(summary_obj.get("safety_notes")):
        out.append({"section_index":None,"title":"Safety","start":"","end":"","text":_p4_text(x)})
    return out

def _p4_extract_cards(summary_obj, sections, content_types):
    cards=[]

    # First honor structured cards already returned by ChatGPT.
    explicit=[]
    for key in ["remedy_cards","recipe_cards","how_to_cards","cards","structured_cards"]:
        explicit.extend(_p4_list(summary_obj.get(key)))
    for item in explicit:
        if isinstance(item,dict):
            c=dict(item)
            c.setdefault("source","chatgpt_structured")
            cards.append(c)

    # Section-level structured data.
    for i,s in enumerate(sections):
        if not isinstance(s,dict):
            continue
        title=str(s.get("title") or s.get("heading") or f"Section {i+1}")
        start=str(s.get("start") or s.get("start_time") or "")
        end=str(s.get("end") or s.get("end_time") or "")
        summary=str(s.get("detailed_summary") or s.get("summary") or "")
        steps=_p4_list(s.get("steps")) or _p4_list(s.get("instructions"))

        # Only create a deterministic card when enough structured data exists.
        if steps:
            if "health_remedy" in content_types:
                card_type="remedy"
            elif "cooking_recipe" in content_types:
                card_type="recipe"
            elif "gardening_diy" in content_types or "technology" in content_types:
                card_type="how_to"
            else:
                card_type="instruction"

            cards.append({
                "type":card_type,
                "title":title,
                "start":start,
                "end":end,
                "summary":summary,
                "steps":[_p4_text(x) for x in steps],
                "ingredients":_p4_list(s.get("ingredients")),
                "quantities":_p4_list(s.get("quantities")),
                "timing":_p4_list(s.get("timing")),
                "frequency":_p4_text(s.get("frequency")),
                "duration":_p4_text(s.get("duration")),
                "warnings":_p4_list(s.get("warnings")),
                "tips":_p4_list(s.get("tips")),
                "requirements":_p4_list(s.get("requirements")),
                "source":"section_structured"
            })
    return cards

def _p4_extract_comparisons(summary_obj, sections):
    tables=[]
    explicit=_p4_list(summary_obj.get("comparisons"))+_p4_list(summary_obj.get("comparison_tables"))
    for x in explicit:
        if isinstance(x,dict):
            tables.append(dict(x,source="chatgpt_structured"))

    for i,s in enumerate(sections):
        if not isinstance(s,dict):
            continue
        comp=s.get("comparison") or s.get("comparison_table")
        if isinstance(comp,dict):
            tables.append(dict(comp,section_index=i,source="section_structured"))
    return tables

def _p4_extract_rankings(summary_obj, sections):
    rankings=[]
    explicit=_p4_list(summary_obj.get("rankings"))+_p4_list(summary_obj.get("ranked_list"))
    for x in explicit:
        if isinstance(x,dict):
            rankings.append(x)
    for i,s in enumerate(sections):
        if not isinstance(s,dict):
            continue
        for x in _p4_list(s.get("ranking"))+_p4_list(s.get("ranked_items")):
            if isinstance(x,dict):
                y=dict(x)
                y["section_index"]=i
                rankings.append(y)
    return rankings

def _p4_extract_entities(summary_obj):
    return {
        "products":_p4_list(summary_obj.get("products")),
        "people":_p4_list(summary_obj.get("people")),
        "locations":_p4_list(summary_obj.get("locations")),
        "entities":_p4_list(summary_obj.get("entities")),
        "ingredients":_p4_list(summary_obj.get("ingredients")),
        "herbs":_p4_list(summary_obj.get("herbs")),
        "sources":_p4_list(summary_obj.get("sources"))+_p4_list(summary_obj.get("named_sources")),
        "organizations":_p4_list(summary_obj.get("organizations")),
    }

def _p4_extract_glossary_qa(summary_obj, sections):
    glossary=[]
    qa=[]
    for x in _p4_list(summary_obj.get("glossary")):
        if isinstance(x,dict): glossary.append(x)
    for x in _p4_list(summary_obj.get("qa"))+_p4_list(summary_obj.get("questions_answers")):
        if isinstance(x,dict): qa.append(x)

    for i,s in enumerate(sections):
        if not isinstance(s,dict): continue
        for x in _p4_list(s.get("glossary")):
            if isinstance(x,dict):
                y=dict(x); y["section_index"]=i; glossary.append(y)
        for x in _p4_list(s.get("qa")):
            if isinstance(x,dict):
                y=dict(x); y["section_index"]=i; qa.append(y)
    return glossary,qa

def phase4_extract_video(video_id):
    folder=locate_existing_folder(video_id)
    if not folder:
        return None,{"fatal":"Video folder not found"}

    summary_path=canonical_chatgpt_summary_path(folder,video_id)
    if not summary_path.exists():
        return None,{"fatal":"Canonical ChatGPT summary missing"}

    try:
        summary_obj=json.loads(summary_path.read_text(encoding="utf-8"))
    except Exception as ex:
        return None,{"fatal":f"Invalid summary JSON: {ex}"}

    norm=normalize_chatgpt_result_video(summary_obj)
    sections=norm.get("sections") or summary_obj.get("sections") or []

    con=db_connect()
    cols=video_table_columns()
    sql=select_existing_video_columns([
        "original_title","clean_title","category","subcategory","channel","upload_date"
    ])
    row=con.execute(f"SELECT {sql} FROM videos WHERE video_id=?",(video_id,)).fetchone()
    con.close()
    orig,clean,category,subcategory,channel,upload_date=row if row else ("","","","","","")

    content_types,scores=phase4_detect_content_types(
        summary_obj,sections,category or "",subcategory or ""
    )
    cards=_p4_extract_cards(summary_obj,sections,content_types)
    comparisons=_p4_extract_comparisons(summary_obj,sections)
    rankings=_p4_extract_rankings(summary_obj,sections)
    safety=_p4_extract_safety(summary_obj,sections)
    entities=_p4_extract_entities(summary_obj)
    glossary,qa=_p4_extract_glossary_qa(summary_obj,sections)

    result={
        "schema_version":1,
        "video_id":video_id,
        "title":clean or orig or video_id,
        "original_title":orig or "",
        "channel":channel or "",
        "upload_date":upload_date or "",
        "category":category or "",
        "subcategory":subcategory or "",
        "content_types":content_types,
        "content_type_scores":scores,
        "cards":cards,
        "comparisons":comparisons,
        "rankings":rankings,
        "safety":safety,
        "entities":entities,
        "glossary":glossary,
        "qa":qa
    }
    return result,None

def phase4_write_video_intelligence(video_id,result):
    root,cards_dir,tables_dir=phase4_dirs()
    out=root/f"{video_id}.intelligence.json"
    out.write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding="utf-8")

    if result.get("cards"):
        (cards_dir/f"{video_id}.cards.json").write_text(
            json.dumps(result["cards"],ensure_ascii=False,indent=2),encoding="utf-8"
        )

    table_payload={
        "comparisons":result.get("comparisons") or [],
        "rankings":result.get("rankings") or []
    }
    if table_payload["comparisons"] or table_payload["rankings"]:
        (tables_dir/f"{video_id}.tables.json").write_text(
            json.dumps(table_payload,ensure_ascii=False,indent=2),encoding="utf-8"
        )
    return out

def phase4_extract_all():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id FROM videos WHERE chatgpt_imported=1 ORDER BY rowid"
    ).fetchall()
    con.close()

    summary=[]
    ok=failed=0

    for (vid,) in rows:
        result,err=phase4_extract_video(vid)
        if err:
            failed+=1
            summary.append({
                "Video ID":vid,"Status":"FAIL","Content Types":"",
                "Cards":0,"Comparisons":0,"Rankings":0,"Safety":0,
                "Products":0,"People":0,"Glossary":0,"QA":0,
                "Reason":err.get("fatal","")
            })
            continue

        phase4_write_video_intelligence(vid,result)
        ok+=1
        ent=result.get("entities") or {}
        summary.append({
            "Video ID":vid,
            "Status":"PASS",
            "Content Types":", ".join(result.get("content_types") or []),
            "Cards":len(result.get("cards") or []),
            "Comparisons":len(result.get("comparisons") or []),
            "Rankings":len(result.get("rankings") or []),
            "Safety":len(result.get("safety") or []),
            "Products":len(ent.get("products") or []),
            "People":len(ent.get("people") or []),
            "Glossary":len(result.get("glossary") or []),
            "QA":len(result.get("qa") or []),
            "Reason":""
        })

    audit=BASE/"maintenance"/"audits"/"phase4_content_intelligence.csv"
    audit.parent.mkdir(parents=True,exist_ok=True)
    with open(audit,"w",newline="",encoding="utf-8-sig") as f:
        fields=[
            "Video ID","Status","Content Types","Cards","Comparisons","Rankings",
            "Safety","Products","People","Glossary","QA","Reason"
        ]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader(); w.writerows(summary)

    print("")
    print("===== PHASE 4 CONTENT INTELLIGENCE =====")
    print(f"Videos processed: {ok}")
    print(f"Failed          : {failed}")
    print(f"Audit           : {audit}")
    return audit

def phase4_show_video():
    vid=input("Video ID: ").strip()
    if not vid: return
    result,err=phase4_extract_video(vid)
    if err:
        print(err.get("fatal"))
        return
    out=phase4_write_video_intelligence(vid,result)

    print("")
    print(f"Video: {result['title']}")
    print("Content types:",", ".join(result["content_types"]))
    print(f"Cards       : {len(result['cards'])}")
    print(f"Comparisons : {len(result['comparisons'])}")
    print(f"Rankings    : {len(result['rankings'])}")
    print(f"Safety      : {len(result['safety'])}")

    ent=result["entities"]
    for key in ["ingredients","herbs","products","people","sources","organizations"]:
        vals=ent.get(key) or []
        if vals:
            print(f"{key.title():13}: {', '.join(_p4_text(x) for x in vals[:20])}")

    if result["cards"]:
        print("\nCards:")
        for i,c in enumerate(result["cards"],1):
            print(f"  {i}. [{c.get('type','card')}] {c.get('title','')}")
    if result["safety"]:
        print("\nSafety:")
        for x in result["safety"][:20]:
            print(f"  - {x.get('title','Safety')}: {x.get('text','')[:300]}")

    print(f"\nSaved: {out}")

def phase4_export_cards_csv():
    root,cards_dir,tables_dir=phase4_dirs()
    rows=[]
    for p in sorted(cards_dir.glob("*.cards.json")):
        try:
            cards=json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            continue
        vid=p.stem.replace(".cards","")
        for i,c in enumerate(cards,1):
            rows.append({
                "Video ID":vid,
                "Card No":i,
                "Type":c.get("type",""),
                "Title":c.get("title",""),
                "Start":c.get("start",""),
                "End":c.get("end",""),
                "Summary":c.get("summary",""),
                "Steps":" | ".join(_p4_text(x) for x in _p4_list(c.get("steps"))),
                "Ingredients":" | ".join(_p4_text(x) for x in _p4_list(c.get("ingredients"))),
                "Quantities":" | ".join(_p4_text(x) for x in _p4_list(c.get("quantities"))),
                "Warnings":" | ".join(_p4_text(x) for x in _p4_list(c.get("warnings")))
            })
    out=root/"all_content_cards.csv"
