def web_job_log_path(job_id):
    folder=BASE/"logs"/"runs";folder.mkdir(parents=True,exist_ok=True)
    return folder/(safe_name(str(job_id),"job")+".jsonl")

def web_job_log(job_id,event,**data):
    """Persistent per-run diagnostics. Retained until a reviewed manual purge."""
    try:
        row={"at":time.strftime("%Y-%m-%d %H:%M:%S"),"event":str(event),**web_json_safe(data)}
        with open(web_job_log_path(job_id),"a",encoding="utf-8") as f:f.write(json.dumps(row,ensure_ascii=False)+"\n")
    except Exception:pass

def purge_reviewed_run_logs():
    """Remove retained diagnostic run logs only when no task is active."""
    state=web_queue_state()
    if state.get("running") or state.get("queued"):
        return {"ok":False,"message":"Wait for all tasks to finish before purging reviewed logs."}
    folder=BASE/"logs"/"runs"
    removed=0
    if folder.is_dir():
        for path in folder.glob("*.jsonl"):
            try:path.unlink();removed+=1
            except Exception:pass
    return {"ok":True,"message":f"Purged {removed} reviewed run log(s).","removed":removed}


def web_job_snapshot(job_id=None):
    with WEB_JOB_LOCK:
        if job_id:
            return dict(WEB_JOBS.get(job_id) or {})
        items=sorted(WEB_JOBS.values(),key=lambda x:x.get("created_at",0),reverse=True)
        compact=[]
        for x in items[:60]:
            d=dict(x)
            result=d.pop("result",None)
            error=d.pop("error",None)
            if result is not None:
                d["has_result"]=True
                if isinstance(result,dict):
                    d["result_summary"]={
                        str(k):web_json_safe(v)
                        for k,v in list(result.items())[:12]
                        if k not in {"items","records","rows","details","checks","messages","files"}
                    }
            if error:
                d["has_error"]=True
            compact.append(d)
        return compact


def web_job_update(job_id,**kwargs):
    with WEB_JOB_LOCK:
        if job_id in WEB_JOBS:WEB_JOBS[job_id].update(kwargs)
    if kwargs.get("status") in {"RUNNING","SUCCESS","WARN","FAILED","CANCELLED"}:
        web_job_log(job_id,"status",**kwargs)

def web_register_process(proc):
    if proc is None:return
    try:
        with WEB_PROCESS_LOCK:WEB_ACTIVE_PROCESSES.add(proc)
    except Exception:pass

def web_unregister_process(proc):
    if proc is None:return
    try:
        with WEB_PROCESS_LOCK:WEB_ACTIVE_PROCESSES.discard(proc)
    except Exception:pass

def web_register_driver(driver):
    if driver is None:return
    try:
        with WEB_DRIVER_LOCK:WEB_ACTIVE_DRIVERS.add(driver)
    except Exception:pass

def web_unregister_driver(driver):
    if driver is None:return
    try:
        with WEB_DRIVER_LOCK:WEB_ACTIVE_DRIVERS.discard(driver)
    except Exception:pass

def web_stop_requested():
    return bool(WEB_STOP_EVENT.is_set() or globals().get("STOP",False))

def web_job_progress(message,processed=None,total=None,phase=None):
    """Update CMD, global progress and the currently running browser job."""
    msg=str(message or "")
    jid=getattr(WEB_JOB_CONTEXT,"job_id",None)
    if jid:
        kw={"message":msg}
        if processed is not None:kw["processed"]=int(processed)
        if total is not None:kw["total"]=int(total)
        web_job_update(jid,**kw)
        web_job_log(jid,"progress",message=msg,processed=processed,total=total,phase=phase)
    state_kw={"message":msg,"current_status":msg}
    if phase:state_kw["phase"]=str(phase)
    if processed is not None:state_kw["processed"]=int(processed)
    if total is not None:state_kw["total"]=int(total)
    try:set_state(**state_kw)
    except Exception:pass
    if msg:
        print(msg,flush=True)

def selenium_status():
    try:
        import selenium
        return {"ok":True,"installed":True,"version":str(getattr(selenium,"__version__","unknown")),"message":"Selenium is installed"}
    except Exception as ex:
        return {"ok":True,"installed":False,"version":"","message":f"Selenium is not installed: {type(ex).__name__}: {ex}"}

def ensure_selenium_installed(auto_install=True):
    """
    No-admin Selenium setup.
    First installs into the app's portable tools/python_packages directory.
    If that fails, tries --user as a secondary fallback.
    """
    st=selenium_status()
    if st.get("installed") or not auto_install:
        return st

    PY_PACKAGES.mkdir(parents=True,exist_ok=True)
    attempts=[
        [sys.executable,"-m","pip","install","--upgrade","--target",str(PY_PACKAGES),"selenium"],
        [sys.executable,"-m","pip","install","--user","selenium"],
    ]
    last=""
    for idx,cmd in enumerate(attempts,1):
        if web_stop_requested():
            return {"ok":False,"installed":False,"version":"","message":"Selenium installation stopped by user."}
        web_job_progress(
            f"[SELENIUM] Not installed. Installation attempt {idx}/{len(attempts)}: {' '.join(str(x) for x in cmd[2:])}",
            phase="Selenium Setup"
        )
        proc=None
        timer=None
        try:
            flags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0)
            proc=subprocess.Popen(
                cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,
                encoding="utf-8",errors="replace",bufsize=1,creationflags=flags
            )
            web_register_process(proc)

            def _timeout_install():
                try:
                    if proc and proc.poll() is None:
                        proc.terminate()
                except Exception:pass
            timer=threading.Timer(300,_timeout_install);timer.daemon=True;timer.start()

            if proc.stdout:
                for line in proc.stdout:
                    line=line.rstrip()
                    if line:
                        print("[SELENIUM INSTALL] "+line,flush=True)
                    if web_stop_requested():
                        try:proc.terminate()
                        except Exception:pass
                        break
            rc=proc.wait()
            last=f"exit code {rc}"
            if rc==0:
                if str(PY_PACKAGES) not in sys.path:
                    sys.path.insert(0,str(PY_PACKAGES))
                import importlib as _importlib
                _importlib.invalidate_caches()
                st=selenium_status()
                if st.get("installed"):
                    web_job_progress(f"[SELENIUM] READY — version {st.get('version')}",phase="Selenium Setup")
                    return st
        except Exception as ex:
            last=f"{type(ex).__name__}: {ex}"
        finally:
            try:
                if timer:timer.cancel()
            except Exception:pass
            web_unregister_process(proc)

    return {"ok":False,"installed":False,"version":"","message":f"Automatic Selenium installation failed: {last}"}

def web_stop_everything():
    """
    Emergency stop:
      1) sets the existing global STOP flag used by long Python loops,
      2) sets an additional browser stop event,
      3) cancels all QUEUED jobs,
      4) terminates subprocesses started/tracked by the app,
      5) closes active Selenium WebDrivers.
    """
    global STOP
    STOP=True
    WEB_STOP_EVENT.set()
    stopped=[]
    errors=[]

    try:
        with WEB_JOB_LOCK:
            for jid,j in WEB_JOBS.items():
                status=str(j.get("status") or "").upper()
                if status=="QUEUED":
                    j.update(status="CANCELLED",message="Cancelled by STOP EVERYTHING",finished_at=time.time())
                    stopped.append(str(jid))
                elif status=="RUNNING":
                    j.update(status="CANCELLING",message="STOP EVERYTHING requested")
    except Exception as ex:
        errors.append(f"jobs: {type(ex).__name__}: {ex}")

    try:
        with WEB_PROCESS_LOCK:
            procs=list(WEB_ACTIVE_PROCESSES)
        for proc in procs:
            try:
                if proc.poll() is None:
                    proc.terminate()
                    try:proc.wait(timeout=2)
                    except Exception:
                        try:proc.kill()
                        except Exception:pass
                    stopped.append(f"PID {getattr(proc,'pid','?')}")
            except Exception as ex:
                errors.append(f"process {getattr(proc,'pid','?')}: {type(ex).__name__}: {ex}")
    except Exception as ex:
        errors.append(f"process registry: {type(ex).__name__}: {ex}")

    # WebDriver quit can block, so fire daemon quit threads rather than blocking
    # the emergency-stop HTTP response.
    try:
        with WEB_DRIVER_LOCK:
            drivers=list(WEB_ACTIVE_DRIVERS)
        for d in drivers:
            try:
                threading.Thread(target=lambda drv=d: drv.quit(),daemon=True).start()
                stopped.append("Selenium WebDriver")
            except Exception as ex:
                errors.append(f"webdriver: {type(ex).__name__}: {ex}")
    except Exception as ex:
        errors.append(f"driver registry: {type(ex).__name__}: {ex}")

    try:
        set_state(phase="STOPPED",current_status="STOP EVERYTHING requested",message="STOP EVERYTHING requested")
    except Exception:pass
    print("\n"+"!"*76)
    print("STOP EVERYTHING REQUESTED — queued work cancelled; child processes/drivers terminating.")
    print("!"*76,flush=True)
    return {"ok":not errors,"message":"STOP EVERYTHING requested","stopped":stopped,"errors":errors}


def web_queue_state():
    with WEB_JOB_LOCK:
        return {
            "paused":bool(WEB_QUEUE_PAUSED),
            "running":sum(1 for x in WEB_JOBS.values() if x.get("status")=="RUNNING"),
            "queued":sum(1 for x in WEB_JOBS.values() if x.get("status")=="QUEUED"),
            "failed":sum(1 for x in WEB_JOBS.values() if x.get("status")=="FAILED"),
            "warn":sum(1 for x in WEB_JOBS.values() if x.get("status")=="WARN"),
            "stop_requested":web_stop_requested()
        }



def cmd_result_summary(result,max_len=700):
    try:
        if result is None:return ""
        if isinstance(result,Path):return str(result)
        if isinstance(result,(str,int,float,bool)):s=str(result)
        elif isinstance(result,dict):
            parts=[]
            for key in ["message","path","file","csv","count","processed","total","applied","updated","created","repaired","deleted","moved","failed","source"]:
                if key in result and result.get(key) not in (None,"",[],{}):
                    parts.append(f"{key}={result.get(key)}")
            s=" | ".join(parts) if parts else json.dumps(web_json_safe(result),ensure_ascii=False)
        elif isinstance(result,(list,tuple,set)):s=f"{type(result).__name__} items={len(result)}"
        else:s=str(result)
        s=re.sub(r"\s+"," ",s).strip()
        return s if len(s)<=max_len else s[:max_len-3]+"..."
    except Exception:return ""


def web_result_outcome(result,http_status=None):
    """Return truthful terminal dashboard status: SUCCESS, WARN or FAILED."""
    if http_status is not None:
        try:
            if int(http_status)>=400:
                return "FAILED"
        except Exception:
            pass
    if not isinstance(result,dict):
        return "SUCCESS"

    status_text=" ".join(
        str(result.get(k) or "")
        for k in ("status","final_status","overall_status","result_status","state")
    ).upper()

    if any(t in status_text for t in ("FAILED","FAIL","ERROR","FATAL")):
        return "FAILED"

    warning_tokens=("WARN","WARNING","PARTIAL","ACTION REQUIRED","ATTENTION","INCOMPLETE")
    if any(t in status_text for t in warning_tokens):
        return "WARN"

    if result.get("ok") is False:
        return "FAILED"

    for key in ("failed","failures","errors","warnings","warn","unresolved","incomplete"):
        val=result.get(key)
        try:
            if isinstance(val,(int,float)) and val>0:
                return "WARN"
            if isinstance(val,(list,tuple,set,dict)) and len(val)>0:
                return "WARN"
        except Exception:
            pass

    steps=result.get("steps")
    if isinstance(steps,list):
        for step in steps:
            if not isinstance(step,dict):
                continue
            ss=str(step.get("status") or "").upper()
            if step.get("ok") is False or any(t in ss for t in warning_tokens) or any(t in ss for t in ("FAILED","FAIL","ERROR")):
                return "WARN"

    return "SUCCESS"

def cmd_dashboard_banner(status,label,job_id="",duration=None,result=None,error=""):
    state=str(status or "").upper();width=78
    if state in {"SUCCESS","COMPLETED"}:heading="DASHBOARD COMMAND COMPLETED SUCCESSFULLY";mark="="
    elif state in {"WARN","WARNING","PARTIAL"}:heading="DASHBOARD COMMAND COMPLETED WITH WARNINGS / ACTION REQUIRED";mark="!"
    elif state in {"FAILED","ERROR"}:heading="DASHBOARD COMMAND FAILED";mark="!"
    elif state in {"CANCELLED","CANCELED","STOPPED"}:heading="DASHBOARD COMMAND CANCELLED / STOPPED";mark="!"
    elif state=="STARTED":heading="DASHBOARD COMMAND STARTED";mark="-"
    elif state=="QUEUED":heading="DASHBOARD COMMAND QUEUED";mark="-"
    else:heading=f"DASHBOARD COMMAND {state or 'STATUS'}";mark="-"
    print("\n"+mark*width)
    print(heading)
    print(f"Command : {label or 'Dashboard command'}")
    if job_id:print(f"Job ID  : {job_id}")
    if duration is not None:
        try:print(f"Duration: {float(duration):.2f} seconds")
        except Exception:pass
    summary=cmd_result_summary(result)
    if summary:print(f"Result  : {summary}")
    if error:
        one=re.sub(r"\s+"," ",str(error)).strip()
        if len(one)>1200:one=one[:1197]+"..."
        print(f"Error   : {one}")
    print(mark*width,flush=True)

