def web_worker_loop():
    while True:
        job_id=WEB_JOB_QUEUE.get()
        started=None;label="Dashboard Job"
        try:
            while True:
                with WEB_JOB_LOCK:
                    paused=bool(WEB_QUEUE_PAUSED)
                    status=(WEB_JOBS.get(job_id) or {}).get("status")
                if status=="CANCELLED" or not paused:break
                time.sleep(0.25)

            with WEB_JOB_LOCK:
                job=WEB_JOBS.get(job_id);task=WEB_JOB_TASKS.get(job_id)
            if not job or not task or job.get("status")=="CANCELLED":continue

            label=str(job.get("label") or "Dashboard Job")
            web_job_log(job_id,"started",label=label)
            if web_stop_requested():
                web_job_update(job_id,status="CANCELLED",finished_at=time.time(),message="Cancelled by STOP EVERYTHING")
                cmd_dashboard_banner("CANCELLED",label,job_id,error="Cancelled by STOP EVERYTHING before start")
                continue

            func,args,kwargs=task
            WEB_JOB_CONTEXT.job_id=job_id
            started=time.time()
            web_job_update(job_id,status="RUNNING",started_at=started,message=label)
            cmd_dashboard_banner("STARTED",label,job_id)
            try:
                result=func(*args,**kwargs)
                safe=web_json_safe(result)
                elapsed=time.time()-started
                if web_stop_requested():
                    web_job_update(job_id,status="CANCELLED",finished_at=time.time(),result=safe,message="Stopped by user")
                    cmd_dashboard_banner("CANCELLED",label,job_id,elapsed,result=safe,error="Stopped by user")
                else:
                    outcome=web_result_outcome(safe)
                    terminal_message={"SUCCESS":"Completed","WARN":"Completed with warnings / action required","FAILED":"Failed"}.get(outcome,outcome.title())
                    web_job_update(job_id,status=outcome,finished_at=time.time(),result=safe,message=terminal_message)
                    err=""
                    if outcome=="FAILED" and isinstance(safe,dict):
                        err=str(safe.get("message") or safe.get("error") or "Command returned a failed result")
                    cmd_dashboard_banner(outcome,label,job_id,elapsed,result=safe,error=err)
            except Exception as ex:
                elapsed=(time.time()-started) if started else None
                status="CANCELLED" if web_stop_requested() else "FAILED"
                msg="Stopped by user" if status=="CANCELLED" else f"{type(ex).__name__}: {ex}"
                web_job_update(job_id,status=status,finished_at=time.time(),message=msg,error=traceback.format_exc())
                cmd_dashboard_banner(status,label,job_id,elapsed,error=msg)
                web_job_log(job_id,"exception",error=traceback.format_exc())
            finally:
                try:WEB_JOB_CONTEXT.job_id=None
                except Exception:pass
        finally:
            WEB_JOB_QUEUE.task_done()


def web_ensure_worker():
    global WEB_WORKER_STARTED
    with WEB_JOB_LOCK:
        if WEB_WORKER_STARTED:return
        WEB_WORKER_STARTED=True
    threading.Thread(target=web_worker_loop,daemon=True,name="VLM-Web-Job-Worker").start()



def web_start_job(label,func,*args,**kwargs):
    global STOP
    STOP=False
    WEB_STOP_EVENT.clear()
    web_ensure_worker()
    jid=time.strftime("%Y%m%d%H%M%S")+"-"+uuid.uuid4().hex[:6]
    with WEB_JOB_LOCK:
        WEB_JOBS[jid]={"job_id":jid,"label":label,"status":"QUEUED","created_at":time.time(),"message":"Queued","processed":0,"total":0}
        WEB_JOB_TASKS[jid]=(func,args,kwargs)
    web_job_log(jid,"queued",label=label,args=[str(x) for x in args],kwargs=kwargs)
    WEB_JOB_QUEUE.put(jid)
    cmd_dashboard_banner("QUEUED",label,jid)
    return jid


def web_cancel_job(job_id):
    with WEB_JOB_LOCK:
        x=WEB_JOBS.get(str(job_id))
        if not x:return False,"Job not found"
        if x.get("status")=="RUNNING":
            WEB_STOP_EVENT.set()
            for proc in list(WEB_ACTIVE_PROCESSES):
                try:proc.terminate()
                except Exception:pass
            x["message"]="Stop requested; active child process termination sent"
            web_job_log(str(job_id),"stop_requested")
            return True,"Stop requested for the running job."
        if x.get("status") in {"SUCCESS","WARN","FAILED","CANCELLED"}:return False,f"Job is already {x.get('status')}"
        x["status"]="CANCELLED";x["message"]="Cancelled before start";x["finished_at"]=time.time()
    return True,"Queued job cancelled"

def web_retry_job(job_id):
    with WEB_JOB_LOCK:
        old=WEB_JOBS.get(str(job_id));task=WEB_JOB_TASKS.get(str(job_id))
    if not old or not task:return False,"Job/task not found",None
    func,args,kwargs=task
    jid=web_start_job("Retry: "+str(old.get("label") or "Job"),func,*args,**kwargs)
    return True,"Retry queued",jid

def web_pause_queue():
    global WEB_QUEUE_PAUSED
    with WEB_JOB_LOCK:WEB_QUEUE_PAUSED=True
    return True,"Queue paused. Current running job finishes; new jobs wait."

def web_resume_queue():
    global WEB_QUEUE_PAUSED
    with WEB_JOB_LOCK:WEB_QUEUE_PAUSED=False
    return True,"Queue resumed."

