def normalize_comment_text(value):
    s=html.unescape(str(value or ""))
    s=re.sub(r"<br\s*/?>","\n",s,flags=re.I)
    s=re.sub(r"<[^>]+>"," ",s)
    s=s.replace("\u200b"," ").replace("\ufeff"," ")
    s=re.sub(r"[ \t]+"," ",s)
    s=re.sub(r"\n{3,}","\n\n",s)
    return s.strip()

def _comment_simple_key(text):
    s=normalize_comment_text(text).lower()
    s=re.sub(r"https?://\S+"," ",s)
    s=re.sub(r"[^a-z0-9\u0900-\u097f\u0a00-\u0a7f]+"," ",s)
    return re.sub(r"\s+"," ",s).strip()

def comment_meaningfulness(row,topic_terms=None):
    """Return (score, reasons, keep). Viewer comments are not fact-checked here."""
    text=normalize_comment_text(row.get("text"))
    if not text:return 0,["empty"],False
    key=_comment_simple_key(text)
    words=[x for x in key.split() if x]
    unique=set(words)
    lower=text.lower()
    if sum(ch.isalnum() for ch in text)<4:
        return 0,["emoji/punctuation only"],False

    generic={
        "nice","nice video","good","good video","great","great video","awesome",
        "amazing","wow","first","lol","lmao","super","excellent","very good",
        "thank you","thanks","thanks sir","thanks bro","love it","i love it",
        "beautiful","wonderful","best video","jai hind","op","legend"
    }
    if key in generic:return 0,["generic reaction"],False

    spam_patterns=[
        r"\bsubscribe\s+(to\s+)?my\b",r"\bcheck\s+(out\s+)?my\s+channel\b",
        r"\bwhatsapp\b.*\b\d{6,}\b",r"\btelegram\b.*\b(join|contact|dm)\b",
        r"\bcontact\s+me\b",r"\bdm\s+me\b",r"\bpromo\s*code\b",
        r"\buse\s+my\s+(code|link)\b",
        r"\bcrypto\b.*\b(contact|whatsapp|telegram|investment)\b"
    ]
    if any(re.search(p,lower,re.I) for p in spam_patterns):
        return 0,["promotion/spam"],False

    score=0;reasons=[]
    if len(words)>=6:score+=1;reasons.append("substantive length")
    if len(words)>=15:score+=1;reasons.append("detailed")
    if len(words)>=35:score+=1;reasons.append("high detail")

    if "?" in text or re.search(r"\b(why|how|what|when|where|which|can|could|should|does|do|is|are|anyone|kya|kaise|kyun|क्यों|कैसे|क्या)\b",lower):
        score+=2;reasons.append("question")

    signals={
        "experience":r"\b(i tried|i used|for me|worked for me|didn't work|did not work|my experience|after \d+|since \d+|mujhe|maine)\b",
        "correction":r"\b(actually|incorrect|wrong|correction|not true|misleading|should be|instead|however)\b",
        "advice":r"\b(try|avoid|recommend|suggest|make sure|be careful|warning|side effect|dose|dosage|steps?|method|process)\b",
        "evidence":r"\b(study|research|source|reference|paper|data|evidence|doctor|clinical|test|result)\b",
        "specifics":r"\b\d+(\.\d+)?\s*(mg|ml|g|kg|cm|mm|minutes?|mins?|hours?|days?|weeks?|months?|years?|%|degrees?|cups?|tbsp|tsp)\b"
    }
    for label,pat in signals.items():
        if re.search(pat,lower,re.I):
            score+=2 if label in {"correction","specifics"} else 1
            reasons.append(label)

    likes=int(row.get("like_count") or 0);replies=int(row.get("reply_count") or 0)
    if likes>=2:score+=1;reasons.append("liked")
    if likes>=10:score+=1;reasons.append("highly liked")
    if likes>=100:score+=1;reasons.append("very highly liked")
    if replies>0:score+=1;reasons.append("discussion")
    if replies>=5:score+=1;reasons.append("active discussion")

    if topic_terms:
        tset={str(x).lower() for x in topic_terms if len(str(x))>=3}
        if unique&tset:
            score+=1;reasons.append("topic overlap")

    keep=(score>=2 and len(words)>=4) or score>=3
    return score,reasons,keep

def _comment_topic_terms(video_id):
    terms=set()
    try:
        con=db_connect();cols=video_table_columns()
        wanted=[c for c in ["original_title","clean_title","category","subcategory","source_category","youtube_category_name","main_topic","tags","youtube_tags"] if c in cols]
        row=con.execute("SELECT "+",".join(f'"{c}"' for c in wanted)+" FROM videos WHERE video_id=?",(str(video_id),)).fetchone() if wanted else None
        con.close()
        if row:
            raw=" ".join(str(x or "") for x in row)
            for w in re.findall(r"[A-Za-z0-9\u0900-\u097f\u0a00-\u0a7f]{3,}",raw.lower()):
                if w not in {"video","youtube","channel","official","the","and","for","with","this","that","from"}:
                    terms.add(w)
    except Exception:pass
    return terms

def build_comment_intelligence(video_id,folder=None,rows=None,source=""):
    vid=str(video_id)
    folder_value=folder or locate_existing_folder(vid) or working_folder_for_video(vid)
    if not folder_value:return {"ok":False,"message":"Video folder not found"}
    folder=Path(folder_value)
    jp,cp=comments_output_paths(vid,folder)
    if rows is None:
        if not jp.exists():return {"ok":False,"message":"Raw comments JSON not found"}
        try:
            obj=json.loads(jp.read_text(encoding="utf-8",errors="replace"))
            rows=obj.get("comments") or [];source=source or str(obj.get("source") or "")
        except Exception as ex:
            return {"ok":False,"message":f"Cannot read raw comments JSON: {ex}"}

    paths=comment_intelligence_paths(vid,folder)
    topic_terms=_comment_topic_terms(vid)
    all_rows=[];meaningful=[];seen=set()
    for r in rows:
        x=dict(r or {});ct=normalize_comment_text(x.get("text"))
        if not ct:continue
        x["text"]=ct;all_rows.append(x)
        key=_comment_simple_key(ct)
        if not key or key in seen:continue
        seen.add(key)
        score,reasons,keep=comment_meaningfulness(x,topic_terms)
        x["meaningfulness_score"]=score;x["meaningfulness_reasons"]=reasons
        if keep:meaningful.append(x)

    meaningful.sort(key=lambda x:(int(x.get("meaningfulness_score") or 0),int(x.get("like_count") or 0),int(x.get("reply_count") or 0),len(str(x.get("text") or ""))),reverse=True)

    all_lines=[
        "VIDEO LIBRARY COMMENT TRANSCRIPT — ALL DOWNLOADED COMMENTS","="*88,
        f"VIDEO_ID: {vid}",f"SOURCE: {source}",f"TOTAL COMMENTS: {len(all_rows)}",
        "NOTE: Viewer comments are audience-generated content, not verified facts.","="*88,""
    ]
    for i,x in enumerate(all_rows,1):
        all_lines += [f"[COMMENT {i}] Author: {x.get('author','')} | Likes: {x.get('like_count',0)} | Replies: {x.get('reply_count',0)} | Published: {x.get('published_at','')}",str(x.get("text") or ""),""]

    meaningful_lines=[
        "VIDEO LIBRARY COMMENT INTELLIGENCE — CHATGPT-READY MEANINGFUL COMMENTS","="*88,
        f"VIDEO_ID: {vid}",f"SOURCE: {source}",f"RAW COMMENTS: {len(all_rows)}",
        f"MEANINGFUL COMMENTS: {len(meaningful)}","",
        "INSTRUCTIONS FOR CHATGPT:",
        "- Treat these as viewer/audience comments, NOT as verified facts.",
        "- Use them for audience questions, experiences, corrections, caveats, recurring concerns, observations and disagreements.",
        "- Distinguish viewer claims from the video's own claims.",
        "- Do not infer consensus merely from repeated comments.","="*88,""
    ]
    for i,x in enumerate(meaningful,1):
        meaningful_lines += [
            f"[MEANINGFUL COMMENT {i}] Score: {x.get('meaningfulness_score',0)} | Likes: {x.get('like_count',0)} | Replies: {x.get('reply_count',0)} | Author: {x.get('author','')} | Published: {x.get('published_at','')}",
            "Why kept: "+", ".join(x.get("meaningfulness_reasons") or []),
            str(x.get("text") or ""),""
        ]

    paths["all_txt"].write_text("\n".join(all_lines),encoding="utf-8")
    paths["meaningful_txt"].write_text("\n".join(meaningful_lines),encoding="utf-8")
    paths["meaningful_json"].write_text(json.dumps({
        "video_id":vid,"source":source,"raw_count":len(all_rows),
        "meaningful_count":len(meaningful),"filter_version":"v1-deterministic",
        "note":"Audience comments are not verified facts.","comments":meaningful
    },ensure_ascii=False,indent=2),encoding="utf-8")

    con=db_connect();cols=video_table_columns();updates={}
    if "comments_transcript_file" in cols:updates["comments_transcript_file"]=str(paths["all_txt"])
    if "comments_meaningful_file" in cols:updates["comments_meaningful_file"]=str(paths["meaningful_txt"])
    if "comments_meaningful_json" in cols:updates["comments_meaningful_json"]=str(paths["meaningful_json"])
    if "comments_meaningful_count" in cols:updates["comments_meaningful_count"]=len(meaningful)
    if "comments_intelligence_updated_at" in cols:updates["comments_intelligence_updated_at"]=time.strftime("%Y-%m-%d %H:%M:%S")
    if updates:
        con.execute("UPDATE videos SET "+",".join(f'"{k}"=?' for k in updates)+" WHERE video_id=?",tuple(updates.values())+(vid,));con.commit()
    con.close()
    return {"ok":True,"video_id":vid,"raw_count":len(all_rows),"meaningful_count":len(meaningful),"all_transcript":str(paths["all_txt"]),"chatgpt_transcript":str(paths["meaningful_txt"]),"meaningful_json":str(paths["meaningful_json"]),"comments":meaningful}

def load_meaningful_comments(video_id,limit=100):
    vid=str(video_id);folder=locate_existing_folder(vid) or working_folder_for_video(vid)
    if not folder:return []
    p=comment_intelligence_paths(vid,folder)["meaningful_json"]
    if not p.exists():
        try:
            r=build_comment_intelligence(vid,folder)
            if not r.get("ok"):return []
        except Exception:return []
    try:return list(json.loads(p.read_text(encoding="utf-8",errors="replace")).get("comments") or [])[:max(0,int(limit))]
    except Exception:return []

def meaningful_comments_report_html(video_id,limit=60):
    comments=load_meaningful_comments(video_id,limit)
    if not comments:return ""
    items=[]
    for x in comments:
        items.append("<div class='viewer-comment'>"
            f"<div class='viewer-comment-meta'><b>{html.escape(str(x.get('author') or 'Viewer'))}</b> · Likes {int(x.get('like_count') or 0)} · Replies {int(x.get('reply_count') or 0)} · Signal score {int(x.get('meaningfulness_score') or 0)}</div>"
            f"<div class='viewer-comment-text'>{html.escape(str(x.get('text') or ''))}</div></div>")
    return "<!-- VLM_MEANINGFUL_COMMENTS_START --><div class='card meaningful-comments-card'>"+f"<h2>Meaningful Viewer Comments <span class='comment-count'>({len(comments)} shown)</span></h2>"+"<p class='comment-note'>Filtered viewer discussion for useful questions, experiences, corrections, caveats and observations. Viewer comments are not verified facts.</p>"+"".join(items)+"</div><!-- VLM_MEANINGFUL_COMMENTS_END -->"

def inject_meaningful_comments_into_report(video_id):
    vid=str(video_id);con=db_connect();cols=video_table_columns();rp=""
    if "report_html" in cols:
        row=con.execute("SELECT report_html FROM videos WHERE video_id=?",(vid,)).fetchone();rp=str(row[0] or "") if row else ""
    con.close();p=Path(rp) if rp else None
    if not p or not p.exists():
        folder=locate_existing_folder(vid)
        p=next(Path(folder).glob("*.report.html"),None) if folder else None
    if not p or not p.exists():return False,"HTML report not found"
    doc=p.read_text(encoding="utf-8",errors="replace");block=meaningful_comments_report_html(vid)
    start="<!-- VLM_MEANINGFUL_COMMENTS_START -->";end="<!-- VLM_MEANINGFUL_COMMENTS_END -->"
    if start in doc and end in doc:
        doc=re.sub(re.escape(start)+r".*?"+re.escape(end),block,doc,flags=re.S)
    elif block:
        marker='<footer class="reportfooter">'
        doc=doc.replace(marker,block+marker,1) if marker in doc else doc.replace("</body>",block+"</body>",1)
    p.write_text(doc,encoding="utf-8");return True,str(p)

def rebuild_all_comment_intelligence(limit=0):
    con=db_connect();cols=video_table_columns()
    if "comments_file" not in cols:
        con.close();return {"ok":True,"processed":0,"message":"No comments_file column"}
    rows=con.execute("SELECT video_id,comments_file FROM videos WHERE COALESCE(comments_file,'')<>'' ORDER BY rowid").fetchall();con.close()
    if int(limit or 0)>0:rows=rows[:int(limit)]
    processed=0;meaningful=0;failed=[]
    for vid,_ in rows:
        try:
            result=build_comment_intelligence(vid,locate_existing_folder(vid))
            if result.get("ok"):
                processed+=1;meaningful+=int(result.get("meaningful_count") or 0);inject_meaningful_comments_into_report(vid)
            else:failed.append({"video_id":vid,"error":result.get("message")})
        except Exception as ex:failed.append({"video_id":vid,"error":f"{type(ex).__name__}: {ex}"})
    return {"ok":not failed,"processed":processed,"meaningful_comments":meaningful,"failed":failed}

def phase6_comments_for_chatgpt(video_id,focused=False):
    vid=str(video_id);folder=locate_existing_folder(vid)
    if not folder:return ""
    p=comment_intelligence_paths(vid,folder)["meaningful_txt"]
    if not p.exists():
        try:build_comment_intelligence(vid,folder)
        except Exception:return ""
    if not p.exists():return ""
    return p.read_text(encoding="utf-8",errors="replace").strip()[:20000 if focused else 40000]

def save_youtube_comments(video_id,url,max_comments=500):
    folder=locate_existing_folder(video_id) or working_folder_for_video(video_id)
    if not folder:return {"ok":False,"message":"Video folder not found"}
    jp,cp=comments_output_paths(video_id,folder);rows=[];source=""
    key=str(CFG.get("youtube_data_api_key","")).strip() or load_youtube_api_key()
    if key:
        try:
            token=None
            while len(rows)<max_comments:
                params={"part":"snippet,replies","videoId":video_id,"maxResults":min(100,max_comments-len(rows)),"textFormat":"plainText","order":"relevance"}
                if token:params["pageToken"]=token
                data=youtube_api_get("commentThreads",params)
                for th in data.get("items",[]):
                    sn=th.get("snippet",{});top=(sn.get("topLevelComment") or {}).get("snippet",{})
                    rows.append({"comment_id":(sn.get("topLevelComment") or {}).get("id",th.get("id","")),"parent_id":"","author":top.get("authorDisplayName","") ,"text":top.get("textDisplay") or top.get("textOriginal") or "","like_count":top.get("likeCount",0),"published_at":top.get("publishedAt","") ,"reply_count":sn.get("totalReplyCount",0)})
                    for rep in (th.get("replies",{}).get("comments") or []):
                        rs=rep.get("snippet",{});rows.append({"comment_id":rep.get("id",""),"parent_id":rs.get("parentId","") ,"author":rs.get("authorDisplayName","") ,"text":rs.get("textDisplay") or rs.get("textOriginal") or "","like_count":rs.get("likeCount",0),"published_at":rs.get("publishedAt","") ,"reply_count":0})
                        if len(rows)>=max_comments:break
                    if len(rows)>=max_comments:break
                token=data.get("nextPageToken")
                if not token:break
            source="YouTube Data API"
        except Exception as ex:
            log(f"YouTube comments API failed {video_id}: {ex}")
    if not rows:
        try:
            tmp=support_dir(Path(folder),create=True)/f"{video_id}.comments_source.%(ext)s"
            args=strict_common_args()+["--skip-download","--no-playlist","--write-info-json","--write-comments","--no-clean-info-json","-o",str(tmp),str(url)]
            rc,out,err=run(args,timeout=max(300,int(CFG.get("timeout_seconds",60))*5))
            infos=sorted(support_dir(Path(folder)).glob(f"{video_id}.comments_source*.info.json"),key=lambda p:p.stat().st_mtime,reverse=True)
            if infos:
                obj=json.loads(infos[0].read_text(encoding="utf-8",errors="replace"))
                for c in (obj.get("comments") or [])[:max_comments]:
                    rows.append({"comment_id":c.get("id","") ,"parent_id":c.get("parent","") ,"author":c.get("author","") ,"text":c.get("text","") ,"like_count":c.get("like_count",0),"published_at":c.get("timestamp","") ,"reply_count":0})
                source="yt-dlp"
        except Exception as ex:log(f"yt-dlp comments failed {video_id}: {ex}")
    payload={"video_id":video_id,"url":url,"source":source,"saved_at":time.strftime("%Y-%m-%d %H:%M:%S"),"count":len(rows),"comments":rows}
    jp.write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
    fields=["comment_id","parent_id","author","text","like_count","published_at","reply_count"]
    with open(cp,"w",encoding="utf-8-sig",newline="") as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
    con=db_connect();con.execute("UPDATE videos SET comments_file=?,comments_count_saved=? WHERE video_id=?",(str(jp),len(rows),video_id));con.commit();con.close()
    intelligence=build_comment_intelligence(video_id,folder,rows,source)
    try:inject_meaningful_comments_into_report(video_id)
    except Exception as ex:log(f"Meaningful comments report injection warning {video_id}: {type(ex).__name__}: {ex}")
    return {"ok":True,"count":len(rows),"source":source,"json":str(jp),"csv":str(cp),
            "meaningful_count":int(intelligence.get("meaningful_count") or 0),
            "comments_transcript":intelligence.get("all_transcript",""),
            "chatgpt_comments_transcript":intelligence.get("chatgpt_transcript",""),
            "meaningful_json":intelligence.get("meaningful_json","")}

def web_media_only_download(urls,quality="1080",category="Entertainment",vtt=True,category_mode="source"):
    urls=web_write_urls(urls)
    if not urls:return {"ok":False,"message":"No URLs supplied"}
    success=failed=0;details=[]
    for i,url in enumerate(urls,1):
        meta,meta_err=extract_single_source_metadata(url)
        if not meta:
            failed+=1;details.append({"url":url,"status":"FAILED","reason":meta_err});continue
        vid=str(meta.get("id") or ("GEN_"+hashlib.sha1(url.encode()).hexdigest()[:11]))
        folder_category=choose_source_category(meta,category) if str(category_mode).lower()=="source" else (str(category or "Entertainment") or "Entertainment")
        channel=safe_name(meta.get("channel") or "Unknown Channel","Unknown Channel")
        title=safe_name(meta.get("title") or vid,vid)
        root=DOWNLOADS/phase6_category_folder_name(folder_category)/channel
        folder=root/f"{truncate_title_chars(title,50)} [{vid}]";data=folder/"_data";data.mkdir(parents=True,exist_ok=True)
        (data/".video_id").write_text(vid,encoding="utf-8")
        identity={"video_id":vid,"url":meta.get("url") or url,"title":meta.get("title") or title,"channel":meta.get("channel") or channel,"platform":meta.get("platform"),"source_category":meta.get("source_category") or meta.get("youtube_category_name") or "","library_folder_category":folder_category,"created_at":time.strftime("%Y-%m-%d %H:%M:%S")}
        identity_path=data/"video_identity.json";identity_path.write_text(json.dumps(identity,indent=2,ensure_ascii=False),encoding="utf-8");(data/"video_id.json").write_text(json.dumps(identity,indent=2,ensure_ascii=False),encoding="utf-8");(data/"video.url").write_text(str(meta.get("url") or url),encoding="utf-8")
        meta["source_category"]=str(meta.get("source_category") or meta.get("youtube_category_name") or "");meta["source_categories"]=meta.get("source_categories") or ([meta["source_category"]] if meta["source_category"] else []);save_metadata([meta])
        con=db_connect();con.execute("UPDATE videos SET category=CASE WHEN COALESCE(category,'')='' THEN ? ELSE category END,local_folder=?,video_identity_file=? WHERE video_id=?",(folder_category,str(folder),str(identity_path),vid));con.commit();con.close()
        fmt=quality_format_selector(quality);output=folder/f"{truncate_title_chars(title,50)} [{vid}].%(ext)s"
        args=strict_common_args()+["--no-playlist","--windows-filenames","--retries","10","--fragment-retries","10","-f",fmt,"-o",str(output)]
        if str(quality).lower()!="audio":args += ["--merge-output-format","mp4"]
        args.append(url)
        rc,out_text,err_text=run_download_with_progress(args,title,"Media Only Video")
        if rc==0:
            media=find_any_media(folder);success+=1;vtt_status="disabled"
            if vtt:
                sub_args=strict_common_args()+["--skip-download","--no-playlist","--windows-filenames","--write-subs","--write-auto-subs","--sub-langs","en.*,en","--sub-format","vtt","-o",str(output),url]
                rc2,so,se=run(sub_args,timeout=max(60,int(CFG.get("timeout_seconds",60))));vtt_status="ok_or_unavailable" if rc2==0 else "failed_but_video_kept"
            subtitle=next(iter(folder.glob("*.vtt")),None)
            con=db_connect();con.execute("UPDATE videos SET downloaded=1,downloaded_quality=?,local_folder=?,local_video=?,subtitle_file=?,downloaded_at=?,final_status='PASS',failure_reason='',last_error='' WHERE video_id=?",(str(quality),str(folder),str(media or ''),str(subtitle or ''),time.strftime("%Y-%m-%d %H:%M:%S"),vid));con.commit();con.close()
            details.append({"video_id":vid,"url":url,"title":title,"source_category":meta.get("source_category"),"folder_category":folder_category,"folder":str(folder),"status":"SUCCESS","vtt":vtt_status})
        else:
            failed+=1;con=db_connect();con.execute("UPDATE videos SET final_status='FAIL',failure_reason=?,last_error=? WHERE video_id=?",((err_text or out_text)[-2000:],(err_text or out_text)[-2000:],vid));con.commit();con.close();details.append({"video_id":vid,"url":url,"status":"FAILED","reason":err_text or out_text})
    export_csv()
    registry=""
    try: registry=str(export_artifact_registry())
    except Exception as ex: print(f"Artifact registry refresh warning: {type(ex).__name__}: {ex}")
    print_all_downloads_done_banner()
    return {"ok":failed==0,"success":success,"failed":failed,"details":details,"artifact_registry":registry}



def web_full_download(urls,quality="1080",use_ollama=False,save_srt=False,prefix_upload_date=False,download_comments=False):
    urls=web_write_urls(urls)
    if not urls:return {"ok":False,"message":"No URLs supplied"}
    old_cfg=dict(CFG); old_runtime=dict(RUNTIME)
    try:
        CFG["download_video"]=True; CFG["download_quality"]=str(quality)
        RUNTIME["save_srt"]=bool(save_srt);RUNTIME["prefix_upload_date"]=bool(prefix_upload_date)
        RUNTIME["use_llm"]=bool(use_ollama);RUNTIME["resume_mode"]="smart";RUNTIME["smart_resume"]=True
        metadata_scan();rows=rows_for_current_urls()
        results=[]
        for row in rows:
            vid,url,orig,clean,channel,upload_date=row[:6];title=clean or orig or vid
            sr=smart_resume_artifact_status(vid)

            if sr["action"]=="COMPLETE":
                comment_result=None
                if download_comments:
                    try:
                        comment_result=save_youtube_comments(vid,url)
                    except Exception as ex:
                        comment_result={"ok":False,"message":f"{type(ex).__name__}: {ex}"}
                results.append({
                    "video_id":vid,"title":title,"status":"SKIPPED",
                    "reason":sr["reason"],"comments":comment_result
                })
                continue

            trrow=None
            try:
                con=db_connect();trrow=con.execute("""SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang FROM videos WHERE video_id=?""",(vid,)).fetchone();con.close()
            except Exception:pass
            if trrow and not has_usable_transcript(vid) and transcript_retry_count(vid)<2:
                increment_transcript_retry(vid,"Browser full download")
                try:
                    tok,msg=prepare_transcript_row(trrow)
                    if tok:clear_transcript_retry(vid)
                except Exception:pass

            try:ok=process_download(row,str(quality))
            except Exception as ex:ok=False;log(f"Browser full download failed {vid}: {ex}")

            comment_result=None
            if ok and download_comments:
                try:comment_result=save_youtube_comments(vid,url)
                except Exception as ex:comment_result={"ok":False,"message":f"{type(ex).__name__}: {ex}"}

            results.append({
                "video_id":vid,"title":title,
                "status":"SUCCESS" if ok else "FAILED",
                "comments":comment_result
            })
        registry=""
        try: registry=str(export_artifact_registry())
        except Exception as ex: print(f"Artifact registry refresh warning: {type(ex).__name__}: {ex}")
        print_all_downloads_done_banner()
        return {"ok":all(x["status"]!="FAILED" for x in results),"results":results,"artifact_registry":registry}
    finally:
        CFG.clear();CFG.update(old_cfg);RUNTIME.clear();RUNTIME.update(old_runtime)


def web_smart_resume_download(use_ollama=False):
    old=dict(RUNTIME)
    try:
        RUNTIME["use_llm"]=bool(use_ollama);RUNTIME["smart_resume"]=True;RUNTIME["resume_mode"]="smart"
        return download_stage()
    finally:RUNTIME.clear();RUNTIME.update(old)


def web_download_failure_rows(limit=500):
    con=db_connect();cols=video_table_columns()
    wanted=["video_id","url","original_title","clean_title","channel","local_video","final_status","failure_reason","last_error","downloaded_at"]
    sel=[c for c in wanted if c in cols];rows=[]
    if sel:
        try:
            for r in con.execute("SELECT "+",".join(f'"{c}"' for c in sel)+" FROM videos ORDER BY rowid DESC LIMIT ?",(int(limit),)).fetchall():
                d=dict(zip(sel,r));reason=str(d.get("failure_reason") or d.get("last_error") or "").strip()
                if str(d.get("final_status") or "").upper()=="FAIL" or reason:
                    d["failure_reason"]=reason;rows.append(d)
        except Exception:pass
    con.close()
    seen={(str(x.get("video_id") or ""),str(x.get("failure_reason") or "")) for x in rows}
    for p in [LOGS/"failed_videos.csv",BASE/"maintenance"/"failed_videos.csv",BASE/"data"/"failed_videos.csv"]:
        try:
            if not p.exists():continue
            with open(p,"r",encoding="utf-8-sig",errors="replace",newline="") as f:
                for rr in csv.DictReader(f):
                    vid=str(rr.get("video_id") or rr.get("Video ID") or "").strip()
                    reason=str(rr.get("reason") or rr.get("Reason") or rr.get("failure_reason") or rr.get("Failure Reason") or rr.get("error") or rr.get("Error") or "").strip()
                    if (vid,reason) in seen:continue
                    rows.append({"video_id":vid,"url":rr.get("url") or rr.get("URL") or "","original_title":rr.get("title") or rr.get("Title") or "","clean_title":rr.get("clean_title") or rr.get("New Title") or "","channel":rr.get("channel") or rr.get("Channel") or "","final_status":"FAIL","failure_reason":reason,"last_error":reason})
                    seen.add((vid,reason))
                    if len(rows)>=limit:break
        except Exception:pass
        if len(rows)>=limit:break
    return rows[:limit]



def web_failure_summary():
    counts=Counter()
    for r in web_download_failure_rows(2000):
        reason=str(r.get("failure_reason") or r.get("last_error") or "Unknown").lower()
        if "429" in reason:key="YouTube / subtitle 429 rate limit"
        elif "403" in reason:key="YouTube 403 forbidden"
        elif "transcript" in reason and any(x in reason for x in ["missing","unavailable","empty"]):key="Transcript unavailable"
        elif "subtitle" in reason or "vtt" in reason or "srt" in reason:key="Subtitle/VTT problem"
        elif "ffmpeg" in reason:key="FFmpeg/media merge"
        elif "timeout" in reason or "timed out" in reason:key="Timeout"
        elif "report" in reason or "html" in reason:key="HTML/report problem"
        elif "path" in reason or "filename" in reason:key="Path/filename problem"
        elif not reason.strip() or reason=="unknown":key="Unknown / no captured reason"
        else:key="Other"
        counts[key]+=1
    return [{"reason":k,"count":v} for k,v in counts.most_common()]


def web_library_stats():
    con=db_connect();cols=video_table_columns()
    arch="COALESCE(archived,0)=0" if "archived" in cols else "1=1"
    total=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch}").fetchone()[0]
    downloaded=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND ((local_video IS NOT NULL AND local_video<>'') OR COALESCE(downloaded,0)=1)").fetchone()[0]
    failed=con.execute("SELECT COUNT(*) FROM videos WHERE UPPER(COALESCE(final_status,''))='FAIL'").fetchone()[0] if "final_status" in cols else 0
    fav=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND COALESCE(favorite,0)=1").fetchone()[0] if "favorite" in cols else 0
    watched=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND COALESCE(watched,0)=1").fetchone()[0] if "watched" in cols else 0
    latest=0
    if "downloaded_at" in cols:
        try:latest=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND downloaded_at>=?",((datetime.now()-timedelta(days=7)).strftime("%Y-%m-%d %H:%M:%S"),)).fetchone()[0]
        except Exception:pass
    con.close()

    db_total=int(total or 0)
    stat_source="SQLite database"
    recovery_needed=False
    fs_media=0;fs_latest=0
    exts={".mp4",".mkv",".webm",".m4v",".mov",".avi",".mp3",".m4a",".aac",".opus"}
    if DOWNLOADS.exists():
        cutoff=time.time()-7*86400
        try:
            for p in DOWNLOADS.rglob("*"):
                if not p.is_file() or p.suffix.lower() not in exts:
                    continue
                fs_media+=1
                try:
                    if p.stat().st_mtime>=cutoff:fs_latest+=1
                except Exception:pass
        except Exception:pass

    if db_total==0 and fs_media>0:
        # Do not hide the existing library just because SQLite is empty. These
        # counts are filesystem-derived until the recovery DB/index is rebuilt.
        total=fs_media
        downloaded=fs_media
        if not latest:latest=fs_latest
        watched=0
        fav=0
        stat_source="Filesystem fallback — SQLite has 0 video rows"
        recovery_needed=True
    elif db_total>0 and latest==0 and fs_latest>0:
        # Older rows may not have downloaded_at populated.
        latest=fs_latest

    return {
        "total":int(total or 0),"downloaded":int(downloaded or 0),"failed":int(failed or 0),
        "favorites":int(fav or 0),"unwatched":max(0,int(total or 0)-int(watched or 0)),"latest7":int(latest or 0),
        "database_rows":db_total,"filesystem_media":fs_media,"source":stat_source,
        "recovery_needed":recovery_needed,"library_root":str(BASE),"database_path":str(DB),
        "root_source":str(BASE_RESOLUTION.get("source") or "")
    }


