def web_local_related(video_id,limit=8):
    out=[]
    try:
        hits=phase5_related_for_video(video_id,limit)
        for score,d in hits:
            out.append({"video_id":d.get("video_id"),"title":d.get("title"),"channel":d.get("channel"),"category":d.get("category"),"score":round(score,3),"thumbnail":"/thumb/"+urllib.parse.quote(str(d.get("video_id"))),"local":True})
    except Exception:pass
    if out:return out
    con=db_connect();row=con.execute("SELECT clean_title,original_title,category,channel FROM videos WHERE video_id=?",(video_id,)).fetchone();
    if not row:con.close();return []
    title=(row[0] or row[1] or "");cat=row[2] or "";tokens=set(re.findall(r"[a-z0-9]{3,}",title.lower()))
    rows=con.execute("SELECT video_id,COALESCE(NULLIF(clean_title,''),original_title),channel,category FROM videos WHERE video_id<>? AND COALESCE(archived,0)=0",(video_id,)).fetchall();con.close();sc=[]
    for vid,t,ch,c in rows:
        tt=set(re.findall(r"[a-z0-9]{3,}",str(t or '').lower()));score=len(tokens&tt)+(1 if cat and c==cat else 0)
        if score:sc.append((score,vid,t,ch,c))
    sc.sort(reverse=True)
    return [{"video_id":v,"title":t,"channel":ch,"category":c,"score":s,"thumbnail":"/thumb/"+urllib.parse.quote(str(v)),"local":True} for s,v,t,ch,c in sc[:limit]]

def web_youtube_suggestions(video_id,limit=8):
    con=db_connect();row=con.execute("SELECT COALESCE(NULLIF(main_topic,''),NULLIF(primary_topic,''),NULLIF(clean_title,''),original_title),source_category FROM videos WHERE video_id=?",(video_id,)).fetchone();con.close()
    if not row:return []
    query=str(row[0] or '').strip()
    if not query:return []
    out=[];key=str(CFG.get("youtube_data_api_key","")).strip() or load_youtube_api_key()
    if key:
        try:
            data=youtube_api_get("search",{"part":"snippet","type":"video","q":query,"maxResults":min(12,max(1,int(limit)+2)),"safeSearch":"moderate"})
            for item in data.get("items",[]):
                vid=str((item.get("id") or {}).get("videoId") or '')
                if not vid or vid==video_id:continue
                sn=item.get("snippet",{});thumb=((sn.get("thumbnails") or {}).get("medium") or (sn.get("thumbnails") or {}).get("default") or {}).get("url","")
                out.append({"video_id":vid,"title":sn.get("title") or "","channel":sn.get("channelTitle") or "","url":f"https://www.youtube.com/watch?v={vid}","thumbnail":thumb,"local":False,"source":"YouTube Data API search"})
                if len(out)>=limit:break
            return out
        except Exception as ex:log(f"YouTube suggestions API failed: {ex}")
    try:
        args=common_args()+["--skip-download","--flat-playlist","--dump-json",f"ytsearch{max(1,int(limit)+2)}:{query}"]
        rc,stdout,stderr=run(args,timeout=120)
        for line in stdout.splitlines():
            try:d=json.loads(line)
            except Exception:continue
            vid=str(d.get("id") or '')
            if not vid or vid==video_id:continue
            out.append({"video_id":vid,"title":d.get("title") or "","channel":d.get("channel") or d.get("uploader") or "","url":d.get("webpage_url") or f"https://www.youtube.com/watch?v={vid}","thumbnail":d.get("thumbnail") or f"https://i.ytimg.com/vi/{vid}/mqdefault.jpg","local":False,"source":"yt-dlp YouTube search"})
            if len(out)>=limit:break
    except Exception:pass
    return out

