def web_system_health():
    checks=[]
    def add(name,ok,detail="",severity=None):checks.append({"name":name,"ok":bool(ok),"detail":str(detail or ""),"severity":severity or ("PASS" if ok else "WARN")})
    try:
        con=db_connect();n=con.execute("SELECT COUNT(*) FROM videos").fetchone()[0];con.close();add("Database",True,f"{n} video rows")
    except Exception as ex:add("Database",False,str(ex),"FAIL")
    for name,p in [("yt-dlp",YTDLP),("ffmpeg",FFMPEG),("ffprobe",FFPROBE),("Deno",DENO)]:add(name,Path(p).exists(),str(p))
    add("Phase 5 search index",phase5_search_index_path().exists(),str(phase5_search_index_path()));add("Phase 6 chunk index",phase6_chunk_index_path().exists(),str(phase6_chunk_index_path()));add("Semantic embeddings",phase6_embedding_manifest_path().exists(),str(phase6_embedding_manifest_path()))
    try:
        online,models,error=phase6_ollama_status();add("Ollama / Qwen",online,(", ".join(models[:5]) if online else error))
    except Exception as ex:add("Ollama / Qwen",False,str(ex))
    con=db_connect();rows=con.execute("SELECT video_id,local_video,report_html FROM videos").fetchall();con.close()
    mm=sum(1 for _,v,_ in rows if v and not Path(str(v)).exists());mr=sum(1 for _,_,r in rows if r and not Path(str(r)).exists());add("Stored media paths",mm==0,f"{mm} invalid media path(s)");add("Stored report paths",mr==0,f"{mr} invalid report path(s)")
    counts=Counter()
    try:
        for m in DOWNLOADS.rglob(".video_id"):
            try:counts[m.read_text(encoding="utf-8",errors="ignore").strip()]+=1
            except Exception:pass
    except Exception:pass
    dup={k:v for k,v in counts.items() if k and v>1};add("Duplicate VIDEO_ID folders",not dup,f"{len(dup)} duplicated ID(s)")
    status="PASS" if all(x["ok"] for x in checks) else ("FAIL" if any(not x["ok"] and x["severity"]=="FAIL" for x in checks) else "WARN")
    return {"ok":status!="FAIL","status":status,"checks":checks}

