def web_config_view():
    keys=["workers","download_quality","download_subtitles","download_description","download_thumbnail","download_info_json","html_report","ai_enabled","max_retries","timeout_seconds","cookies_mode","browser_for_cookies","save_srt_default","prefix_upload_date_default","smart_resume","ai_parallel_workers","fast_no_llm_mode","ollama_model","ollama_timeout_seconds"]
    return {k:CFG.get(k) for k in keys}

def web_config_update(values):
    allowed=set(web_config_view())
    bool_keys={"download_subtitles","download_description","download_thumbnail","download_info_json","html_report","ai_enabled","save_srt_default","prefix_upload_date_default","smart_resume","fast_no_llm_mode"}
    int_keys={"workers","max_retries","timeout_seconds","ai_parallel_workers","ollama_timeout_seconds"}
    for k,v in (values or {}).items():
        if k not in allowed:continue
        if k in bool_keys:v=bool(v)
        elif k in int_keys:
            try:v=int(v)
            except Exception:continue
        CFG[k]=v
    CONFIG.parent.mkdir(parents=True,exist_ok=True)
    CONFIG.write_text(json.dumps(CFG,indent=2,ensure_ascii=False),encoding="utf-8")
    return {"ok":True,"message":"Settings saved","settings":web_config_view()}



def _combined_step(title,index,total,func,*args,**kwargs):
    print("")
    print("-"*78)
    print(f"[{index}/{total}] {title}")
    print("-"*78)
    started=time.time()
    try:
        result=func(*args,**kwargs)
        elapsed=round(time.time()-started,2)
        explicit_bad=(result is False) or (isinstance(result,dict) and result.get("ok") is False)
        print(f"[{index}/{total}] {'WARN' if explicit_bad else 'DONE'} {title} ({elapsed}s)")
        return {"name":title,"ok":not explicit_bad,"result":web_json_safe(result),"seconds":elapsed}
    except Exception as ex:
        elapsed=round(time.time()-started,2)
        print(f"[{index}/{total}] FAILED {title}: {type(ex).__name__}: {ex}")
        return {"name":title,"ok":False,"error":f"{type(ex).__name__}: {ex}","seconds":elapsed}


def _combined_finish(title,steps,extra=None):
    bad=[x for x in steps if not x.get("ok")]
    status="SUCCESS" if not bad else "WARN / ACTION REQUIRED"
    print("")
    print("="*78)
    print(title)
    print(f"OVERALL RESULT: {status}")
    print(f"Steps: {len(steps)-len(bad)} OK / {len(bad)} WARN-FAIL")
    if bad:
        for x in bad: print(f"  ! {x.get('name')}: {x.get('error') or 'reported a warning/failure'}")
    print("="*78,flush=True)
    out={"ok":not bad,"status":status,"message":f"{title}: {status}","steps":steps}
    if extra: out.update(extra)
    return out


