def _valid_youtube_video_id(value):
    return bool(re.fullmatch(r"[A-Za-z0-9_-]{11}",str(value or "").strip()))


def phase2_all_package_completeness_audit():
    manifests=[];seen=set()
    for d in phase2_all_package_dirs():
        for mp in sorted(Path(d).glob("*.manifest.json")):
            try:
                obj=json.loads(mp.read_text(encoding="utf-8"))
                pkg=str(obj.get("package_id") or mp.stem.replace(".manifest",""))
                if pkg in seen: continue
                seen.add(pkg);manifests.append((pkg,mp,obj))
            except Exception as ex:
                print(f"Unreadable manifest {mp}: {ex}")
    rows=[];complete_count=0;invalid_placeholders=[]
    for pkg,mp,obj in manifests:
        raw=[str(x).strip() for x in (obj.get("expected_video_ids") or []) if str(x).strip()]
        invalid=[x for x in raw if not _valid_youtube_video_id(x)]
        expected=[x for x in raw if _valid_youtube_video_id(x)]
        invalid_placeholders.extend(invalid)
        problems=[]
        if not expected:
            problems.append("Manifest has no valid YouTube VIDEO_IDs")
        else:
            con=db_connect();q=",".join("?" for _ in expected)
            dbrows=con.execute(f"SELECT video_id,chatgpt_imported,chatgpt_summary_file,report_html FROM videos WHERE video_id IN ({q})",expected).fetchall();con.close()
            found={r[0]:r for r in dbrows}
            for vid in expected:
                row=found.get(vid)
                if not row: problems.append(f"{vid}: missing from SQLite");continue
                _,imp,summary,report=row
                if int(imp or 0)!=1: problems.append(f"{vid}: not imported")
                if not summary or not Path(summary).exists(): problems.append(f"{vid}: canonical summary missing")
                if not report or not Path(report).exists(): problems.append(f"{vid}: report missing")
        complete=not problems
        complete_count+=1 if complete else 0
        print(f"Package: {pkg} | Archive eligible: {'YES' if complete else 'NO'} | valid IDs={len(expected)} | ignored placeholders={len(invalid)}")
        for x in invalid: print(f"  IGNORED invalid/placeholder VIDEO_ID: {x}")
        for p in problems: print(f"  {p}")
        rows.append({"package_id":pkg,"complete":complete,"valid_video_ids":len(expected),"ignored_invalid_ids":invalid,"problems":problems,"manifest":str(mp)})
    out=BASE/'maintenance'/'audits'/'phase2_package_completeness_all.json'
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(json.dumps({"generated_at":time.strftime("%Y-%m-%d %H:%M:%S"),"packages":rows,"ignored_invalid_ids":sorted(set(invalid_placeholders))},indent=2,ensure_ascii=False),encoding='utf-8')
    print(f"Package completeness audit: {out}")
    return {"ok":all(x['complete'] for x in rows) if rows else True,"packages":len(rows),"complete":complete_count,"incomplete":len(rows)-complete_count,"ignored_invalid_ids":sorted(set(invalid_placeholders)),"report":str(out)}


