def chatgpt_processing_coverage(feature_id="",status="",limit=500):
    con=db_connect();where=[];args=[]
    if feature_id:where.append("c.feature_id=?");args.append(feature_id)
    if status:where.append("c.status=?");args.append(status)
    sql="SELECT c.video_id,c.feature_id,c.feature_version,c.status,c.package_id,c.completed_at,c.last_error,v.clean_title,v.channel FROM video_feature_coverage c LEFT JOIN videos v ON v.video_id=c.video_id"+(" WHERE "+" AND ".join(where) if where else "")+" ORDER BY c.completed_at DESC LIMIT ?";args.append(int(limit))
    rows=con.execute(sql,args).fetchall();con.close();keys=["video_id","feature_id","feature_version","status","package_id","completed_at","last_error","title","channel"]
    return [dict(zip(keys,r)) for r in rows]

def chatgpt_package_transcript_preflight(video_ids, fetch_missing=False, package_preflight_id=""):
    """Persist local/fetched transcript availability before package routing. No video media is downloaded."""
    ids=list(dict.fromkeys(str(x).strip() for x in (video_ids or []) if str(x).strip()))
    if not ids:return {"total":0,"available":0,"unavailable":0,"checked":False}
    con=db_connect();q=','.join('?' for _ in ids)
    rows=con.execute(f"SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang FROM videos WHERE video_id IN ({q})",ids).fetchall();con.close()
    if fetch_missing:
        missing=[r for r in rows if not has_usable_transcript(str(r[0]))]
        if missing: prepare_transcripts_rows(missing)
    build_video_artifact_manifest([str(r[0]) for r in rows])
    stamp=time.strftime("%Y-%m-%d %H:%M:%S");con=db_connect();available=[];unavailable=[]
    for row in rows:
        vid=str(row[0]);manifest=artifact_manifest_for_video(vid) or {};ready=bool(has_usable_transcript(vid) or manifest.get("timestamped_transcript") or manifest.get("clean_transcript") or manifest.get("subtitle"))
        source="local_or_fetched" if ready else "not_available"
        con.execute("INSERT OR REPLACE INTO transcript_availability(video_id,status,source,checked_at,detail,package_preflight_id) VALUES(?,?,?,?,?,?)",(vid,"AVAILABLE" if ready else "UNAVAILABLE",source,stamp,"Transcript/subtitle available locally" if ready else "No usable transcript/subtitle found after check",package_preflight_id))
        (available if ready else unavailable).append(vid)
    con.commit();con.close()
    return {"total":len(rows),"available":len(available),"unavailable":len(unavailable),"available_ids":available,"unavailable_ids":unavailable,"checked":bool(fetch_missing)}

def create_manual_chatgpt_processing_package(options):
    """Create files only. The user manually uploads them to ChatGPT."""
    options=options or {};mode=str(options.get("mode") or "MASTER").upper();requested=[x for x in options.get("features") or ["taxonomy.v3","executive_summary.v2","detailed_summary.v3","timeline_sections.v3"] if x in CHATGPT_FEATURES]
    raw=str(options.get("video_ids") or "");ids=list(dict.fromkeys(x for x in re.split(r"[\s,;]+",raw) if x))
    con=db_connect()
    if not ids:
        q="SELECT video_id FROM videos WHERE COALESCE(archived,0)=0";sel_args=[]
        selector_map={"folderScope":"local_folder","topicScope":"main_topic","categoryScope":"category"}
        for key,column in selector_map.items():
            value=str(options.get(key) or "").strip()
            if value:q+=f" AND {column}=?";sel_args.append(value)
        if mode=="FEATURE_ENRICHMENT" and requested:
            first_feature=requested[0].split('.',1)[0]
            q+=" AND video_id NOT IN (SELECT video_id FROM video_feature_coverage WHERE feature_id=? AND status='COMPLETE')";sel_args.append(first_feature)
        ids=[str(r[0]) for r in con.execute(q,tuple(sel_args)).fetchall()]
    if not ids:con.close();raise ValueError("No eligible videos selected for this manual package.")
    if options.get("verify_transcript_availability"):
        # For a single package this records the state; SMART_QUALITY additionally
        # uses it to route unavailable videos into the separate profile.
        chatgpt_package_transcript_preflight(ids,True,str(options.get("preflight_id") or ""))
    fields="video_id,url,original_title,clean_title,channel,upload_date,description,source_category,youtube_category_name,comments_file,comments_transcript_file,local_folder"
    qmarks=','.join('?' for _ in ids);rows=con.execute(f"SELECT {fields} FROM videos WHERE video_id IN ({qmarks})",ids).fetchall();con.close()
    stamp=time.strftime("%Y%m%d_%H%M%S");package_id=f"vh_{mode.lower()}_{stamp}_{uuid.uuid4().hex[:6]}";root=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/package_id;root.mkdir(parents=True,exist_ok=True)
    videos=[];request_id=str(uuid.uuid4())
    for row in rows:
        d=dict(zip(fields.split(','),row));vid=str(d["video_id"]);manifest=artifact_manifest_for_video(vid) or artifact_inventory(vid)
        evidence={"metadata":True,"description":bool(d.get("description")),"transcript":bool((manifest or {}).get("timestamped_transcript") or (manifest or {}).get("clean_transcript") or (manifest or {}).get("subtitle")),"comments":bool(d.get("comments_file") or d.get("comments_transcript_file")),"artifact_manifest":manifest}
        transcript,_lang=best_transcript_for_video(vid);comments=""
        for key in ("comments_transcript_file","comments_file"):
            p=Path(str(d.get(key) or ""));
            if p.is_file(): comments=p.read_text(encoding="utf-8",errors="replace")[:12000];break
        videos.append({"video_id":vid,"metadata":{k:d.get(k) for k in ("url","original_title","clean_title","channel","upload_date","description","source_category","youtube_category_name")},"requested_features":requested,"evidence":{"transcript":transcript[:30000],"comments":comments,"manifest":evidence}})
    response_template={"package_id":package_id,"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"video_updates":[{"video_id":"EXACT_VIDEO_ID_FROM_EVIDENCE_JSON","evidence_references":["transcript","metadata","comments"],"features":{"title_en.v1":{"title":"Example title"},"taxonomy.v3":{"primary_topic":"Example topic","keywords":["example"]}}}]}
    schema={"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"package_id":package_id,"manual_exchange_only":True,"allowed_feature_ids":requested,"result_contract":"Return ONE final combined JSON object only after completing every VIDEO_ID in evidence.json. Do not return partial JSON, progress JSON, or a dictionary keyed by VIDEO_ID. video_updates MUST be a JSON ARRAY. Every array item MUST include video_id (exactly as supplied), evidence_references (an array) and features (an object). If a source is missing, return the requested feature with an empty value and a reason; never invent evidence. Do not request or perform deletion, file movement, clipping, or upload.","response_template":response_template}
    batch_context=options.get("batch_context") or {}
    prompt={"manual_exchange_notice":"Upload this package manually to ChatGPT. VideoHoarder never uploads data automatically.","mode":mode,"requested_features":requested,"instructions":"Process all VIDEO_IDs in evidence.json internally. Do not return any partial JSON or interim batch result. Return ONE final combined JSON only after all supplied VIDEO_IDs have been processed. Do not claim a VIDEO_ID was processed unless it appears in video_updates. Return only requested feature fields per exact video_id. Source-grounded evidence only; use empty arrays/objects plus a reason when evidence is unavailable. CRITICAL: return video_updates as an ARRAY using the exact response_template. Do not return a dictionary keyed by VIDEO_ID. Proposed rename, move, duplicate, and clip actions remain suggestions for later manual review.","response_template":response_template}
    if batch_context:
        batch_instruction=f"This is independently importable batch {batch_context.get('batch_number')} of {batch_context.get('batch_total')} in master set {batch_context.get('master_set_id')}. Process only the VIDEO_IDs in this evidence.json. Return one final JSON only for this batch; do not add videos from another batch."
        if batch_context.get("profile")=="NO_TRANSCRIPT_METADATA":
            batch_instruction+=" This is a NO-TRANSCRIPT package: use only title, description, metadata and comments. Do not invent transcript summaries, timeline sections, timestamps, claims, or clip plans."
        schema["batch_context"]=batch_context;prompt["batch_context"]=batch_context;prompt["batch_instruction"]=batch_instruction
    (root/"schema.json").write_text(json.dumps(schema,indent=2,ensure_ascii=False),encoding="utf-8");(root/"prompt.json").write_text(json.dumps(prompt,indent=2,ensure_ascii=False),encoding="utf-8");(root/"evidence.json").write_text(json.dumps({"package_id":package_id,"videos":videos},indent=2,ensure_ascii=False),encoding="utf-8")
    hashes={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in root.glob("*.json")};manifest={"request_id":request_id,"package_id":package_id,"mode":mode,"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"prompt_version":CHATGPT_PROCESSING_PROMPT_VERSION,"requested_features":requested,"video_ids":[v["video_id"] for v in videos],"hashes":hashes,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"manual_exchange_only":True};(root/"manifest.json").write_text(json.dumps(manifest,indent=2,ensure_ascii=False),encoding="utf-8");(root/"PACKAGE_README.txt").write_text("MANUAL EXCHANGE ONLY. Upload evidence.json with prompt.json and schema.json to ChatGPT manually. Save the returned JSON and import it manually in VideoHoarder. No files are uploaded by this app.\n",encoding="utf-8")
    package_hash=hashlib.sha256((root/"manifest.json").read_bytes()).hexdigest();con=db_connect();con.execute("INSERT INTO chatgpt_requests VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",(request_id,package_id,mode,CHATGPT_PROCESSING_SCHEMA_VERSION,CHATGPT_PROCESSING_PROMPT_VERSION,json.dumps(requested),package_hash,json.dumps(manifest),manifest["created_at"],"AWAITING_RESULT","","","NOT_IMPORTED","NOT_APPLIED",""))
    for v in videos:
        snap=chatgpt_source_snapshot(v["metadata"],v["evidence"]);con.execute("INSERT INTO chatgpt_request_videos VALUES(?,?,?,?,?)",(request_id,v["video_id"],snap,json.dumps(v["evidence"]["manifest"]),json.dumps(requested)))
        for fid in requested:
            name,ver=fid.split('.',1);con.execute("INSERT OR REPLACE INTO video_feature_coverage(video_id,feature_id,feature_version,status,source_snapshot_hash,package_id,result_hash,evidence_coverage,completed_at,stale_reason,last_error) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(v["video_id"],name,"v"+ver,"REQUESTED",snap,package_id,"",json.dumps(v["evidence"]),"","",""))
    con.commit();con.close();return {"ok":True,"package_id":package_id,"request_id":request_id,"folder":str(root),"videos":len(videos),"features":requested,"manual_exchange_only":True}

def create_manual_chatgpt_processing_batch_set(options):
    """Create quality-sized manual packages, separating transcript and no-transcript videos."""
    options=options or {};raw=str(options.get("video_ids") or "")
    ids=list(dict.fromkeys(x for x in re.split(r"[\s,;]+",raw) if x))
    if not ids:
        con=db_connect();ids=[str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(archived,0)=0 ORDER BY video_id").fetchall()];con.close()
    try: batch_size=int(options.get("batch_size") or 25)
    except Exception: batch_size=25
    batch_size=max(1,min(batch_size,25))
    try: no_transcript_batch_size=int(options.get("no_transcript_batch_size") or 50)
    except Exception: no_transcript_batch_size=50
    no_transcript_batch_size=max(1,min(no_transcript_batch_size,100))
    if not ids: raise ValueError("No eligible videos selected for batch set.")
    master_set_id=f"vh_batch_set_{time.strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}"
    # Do the potentially slow availability check before creating the set folder.
    # If the user cancels or the app is closed, we do not leave an empty package
    # directory that looks like a completed export.
    set_state(phase="ChatGPT transcript preflight",total=len(ids),processed=0,
              current_file="",current_status="Checking local transcript and subtitle availability")
    preflight=chatgpt_package_transcript_preflight(ids,bool(options.get("verify_transcript_availability")),master_set_id)
    if web_stop_requested():
        raise RuntimeError("ChatGPT package creation stopped during transcript preflight.")
    set_root=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/master_set_id;set_root.mkdir(parents=True,exist_ok=True)
    with_transcript=preflight["available_ids"];without_transcript=preflight["unavailable_ids"]
    planned=options.get("planned_groups") or {}
    if planned:
        full_chunks=[(str(g.get("group_name") or "Similar videos"),list(g.get("video_ids") or [])) for g in planned.get("transcript_groups") or []]
        no_transcript_chunks=[(str(g.get("group_name") or "No-transcript videos"),list(g.get("video_ids") or [])) for g in planned.get("no_transcript_groups") or []]
    else:
        full_chunks=[("Library batch",with_transcript[n:n+batch_size]) for n in range(0,len(with_transcript),batch_size)]
        no_transcript_chunks=[("No-transcript batch",without_transcript[n:n+no_transcript_batch_size]) for n in range(0,len(without_transcript),no_transcript_batch_size)]
    entries=[];full_features=[x for x in options.get("features") or list(CHATGPT_FEATURES) if x in CHATGPT_FEATURES]
    no_transcript_features=[x for x in full_features if x in {"title_en.v1","taxonomy.v3","entities.v2","viewer_comment_intelligence.v2"}]
    groups=[("FULL_INTELLIGENCE",full_chunks,full_features,batch_size),("NO_TRANSCRIPT_METADATA",no_transcript_chunks,no_transcript_features,no_transcript_batch_size)]
    created_video_count=0
    total_packages=len(full_chunks)+len(no_transcript_chunks)
    package_number=0
    for profile,chunks,features,size in groups:
        for number,(group_name,chunk) in enumerate(chunks,1):
            if web_stop_requested():
                raise RuntimeError("ChatGPT package creation stopped by user.")
            package_number+=1
            set_state(phase="Writing ChatGPT packages",total=len(ids),processed=created_video_count,
                      current_file=str(chunk[0]) if chunk else "",
                      current_status=f"Writing {profile} package {package_number}/{total_packages} ({len(chunk)} videos)",
                      current_percent=f"{(created_video_count*100/len(ids)):.0f}%" if ids else "100%")
            child=dict(options);child["mode"]=profile;child["video_ids"]="\n".join(chunk);child["features"]=features;child["verify_transcript_availability"]=False;child["batch_context"]={"master_set_id":master_set_id,"profile":profile,"group_name":group_name,"batch_number":number,"batch_total":len(chunks),"batch_size":size}
            created=create_manual_chatgpt_processing_package(child)
            entries.append({"profile":profile,"group_name":group_name,"number":number,"package_id":created["package_id"],"folder":created["folder"],"video_count":len(chunk),"video_ids":chunk,"features":features})
            created_video_count+=len(chunk)
            set_state(phase="Writing ChatGPT packages",total=len(ids),processed=created_video_count,
                      current_file=str(chunk[-1]) if chunk else "",
                      current_status=f"Completed {profile} package {package_number}/{total_packages}",
                      current_percent=f"{(created_video_count*100/len(ids)):.0f}%" if ids else "100%")
    index={"master_set_id":master_set_id,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"manual_exchange_only":True,"video_count":len(ids),"transcript_preflight":preflight,"with_transcript_videos":len(with_transcript),"without_transcript_videos":len(without_transcript),"full_intelligence_batch_size":batch_size,"no_transcript_batch_size":no_transcript_batch_size,"batch_count":len(entries),"instructions":"Upload and import each package separately. FULL_INTELLIGENCE packages contain at most 25 transcript-backed videos and all selected features. NO_TRANSCRIPT_METADATA packages contain at most 50 videos and only title, taxonomy, entities and comment intelligence; they must not invent transcript-derived content. Do not combine returned JSON files.","batches":entries}
    (set_root/"BATCH_SET_INDEX.json").write_text(json.dumps(index,indent=2,ensure_ascii=False),encoding="utf-8")
    (set_root/"BATCH_SET_README.txt").write_text(index["instructions"]+"\n",encoding="utf-8")
    set_state(phase="ChatGPT package creation complete",total=len(ids),processed=len(ids),
              current_file="",current_status=f"Created {len(entries)} local package(s)",current_percent="100%",current_eta="")
    return {"ok":True,"master_set_id":master_set_id,"folder":str(set_root),"videos":len(ids),"transcript_preflight":preflight,"with_transcript_videos":len(with_transcript),"without_transcript_videos":len(without_transcript),"full_intelligence_batch_size":batch_size,"no_transcript_batch_size":no_transcript_batch_size,"batches":len(entries),"packages":entries,"manual_exchange_only":True}

def create_chatgpt_processing_package_job(options):
    """Queue-safe entry point used by the browser command center."""
    options=options or {}
    if str(options.get("mode") or "").upper()=="SMART_QUALITY":
        return create_manual_chatgpt_processing_batch_set(options)
    return create_manual_chatgpt_processing_package(options)

def chatgpt_batch_planner_exclusions(video_ids, options):
    """Preview explicit opt-in exclusions for the similarity planner."""
    options=options or {};ids=list(dict.fromkeys(str(x) for x in (video_ids or []) if str(x)))
    if not ids:return {"included_ids":[],"skipped":[],"skipped_count":0,"summary":{}}
    categories={str(x).strip().lower() for x in (options.get("exclude_youtube_categories") or []) if str(x).strip()}
    words=[x.strip().lower() for x in re.split(r"[,;\n]+",str(options.get("exclude_keywords") or "")) if x.strip()]
    con=db_connect();q=','.join('?' for _ in ids);rows=con.execute(f"SELECT video_id,original_title,clean_title,channel,youtube_category_name FROM videos WHERE video_id IN ({q})",ids).fetchall();con.close()
    included=[];skipped=[]
    for vid,title,clean,channel,youtube in rows:
        text=" ".join(str(x or "") for x in (title,clean,channel)).lower();reasons=[]
        if str(youtube or "").strip().lower() in categories:reasons.append("YouTube category: "+str(youtube))
        hits=[word for word in words if word in text]
        if hits:reasons.append("title/channel keyword: "+", ".join(hits))
        entry={"video_id":str(vid),"title":clean or title or "","channel":channel or "","youtube_category":youtube or "","reasons":reasons}
        (skipped if reasons else included).append(entry)
    summary={}
    for x in skipped:
        for reason in x["reasons"]:summary[reason]=summary.get(reason,0)+1
    return {"included_ids":[x["video_id"] for x in included],"skipped":skipped,"skipped_count":len(skipped),"included_count":len(included),"summary":summary}

def create_manual_chatgpt_batch_planner(options):
    """Create a small metadata-only package for manual topical batch planning."""
    options=options or {};raw=str(options.get("video_ids") or "")
    ids=list(dict.fromkeys(x for x in re.split(r"[\s,;]+",raw) if x))
    if not ids:
        con=db_connect();ids=[str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(archived,0)=0 ORDER BY video_id").fetchall()];con.close()
    if not ids: raise ValueError("No eligible videos selected for batch planning.")
    excluded=chatgpt_batch_planner_exclusions(ids,options);ids=excluded["included_ids"]
    if not ids:raise ValueError("All selected videos were excluded. Preview and adjust the skip filters.")
    planner_id=f"vh_batch_planner_{time.strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}"
    set_state(phase="Batch planner transcript preflight",total=len(ids),processed=0,current_file="",current_status="Checking local transcript and subtitle availability")
    preflight=chatgpt_package_transcript_preflight(ids,bool(options.get("verify_transcript_availability",True)),planner_id)
    if web_stop_requested(): raise RuntimeError("Batch planner creation stopped during transcript preflight.")
    con=db_connect();q=','.join('?' for _ in ids)
    rows=con.execute(f"SELECT video_id,original_title,clean_title,channel,upload_date,description,source_category,youtube_category_name FROM videos WHERE video_id IN ({q})",ids).fetchall();con.close()
    avail=set(preflight["available_ids"]);root=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/planner_id;root.mkdir(parents=True,exist_ok=True)
    catalog=[]
    for n,row in enumerate(rows,1):
        vid,title,clean,channel,date,desc,source,youtube=row
        catalog.append({"video_id":str(vid),"title":clean or title or "","channel":channel or "","upload_date":date or "","description":(desc or "")[:1000],"library_category":source or "","youtube_category":youtube or "","transcript_available":str(vid) in avail})
        set_state(phase="Writing batch planner",total=len(rows),processed=n,current_file=str(vid),current_status="Adding catalog record",current_percent=f"{n*100/len(rows):.0f}%")
    template={"package_id":planner_id,"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"plan_type":"SIMILARITY_BATCH_PLAN","transcript_groups":[{"group_name":"Example topic","video_ids":["EXACT_AVAILABLE_VIDEO_ID"]}],"no_transcript_groups":[{"group_name":"Example metadata-only topic","video_ids":["EXACT_UNAVAILABLE_VIDEO_ID"]}]}
    schema={"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"package_id":planner_id,"manual_exchange_only":True,"result_contract":"Return one JSON object matching response_template. Every catalog VIDEO_ID must appear exactly once. Put transcript_available=true videos only in transcript_groups (maximum 25 IDs per group). Put transcript_available=false videos only in no_transcript_groups (maximum 50 IDs per group). Do not invent, omit, duplicate, or change IDs.","response_template":template}
    prompt={"manual_exchange_notice":"Manual exchange only: upload catalog.json, prompt.json and schema.json yourself. Nothing is uploaded by VideoHoarder.","instructions":"Group similar videos by topic, subject, channel/theme and likely shared research context. Use titles, descriptions and categories only. Return one final JSON object only. The app, not ChatGPT, decides transcript availability. All catalog IDs must occur exactly once in the correct group type.","response_template":template}
    (root/"catalog.json").write_text(json.dumps({"package_id":planner_id,"videos":catalog},indent=2,ensure_ascii=False),encoding="utf-8")
    (root/"schema.json").write_text(json.dumps(schema,indent=2,ensure_ascii=False),encoding="utf-8")
    (root/"prompt.json").write_text(json.dumps(prompt,indent=2,ensure_ascii=False),encoding="utf-8")
    hashes={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in root.glob("*.json")};request_id=str(uuid.uuid4());manifest={"request_id":request_id,"package_id":planner_id,"mode":"BATCH_PLANNING","schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"prompt_version":CHATGPT_PROCESSING_PROMPT_VERSION,"video_ids":ids,"transcript_preflight":preflight,"hashes":hashes,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"manual_exchange_only":True};(root/"manifest.json").write_text(json.dumps(manifest,indent=2,ensure_ascii=False),encoding="utf-8")
    (root/"PACKAGE_README.txt").write_text("MANUAL ONLY: upload catalog.json, prompt.json and schema.json. Import the returned batch-plan JSON in VideoHoarder before creating actual packages.\n",encoding="utf-8")
    package_hash=hashlib.sha256((root/"manifest.json").read_bytes()).hexdigest();con=db_connect();con.execute("INSERT INTO chatgpt_requests VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",(request_id,planner_id,"BATCH_PLANNING",CHATGPT_PROCESSING_SCHEMA_VERSION,CHATGPT_PROCESSING_PROMPT_VERSION,json.dumps(["batch_planning.v1"]),package_hash,json.dumps(manifest),manifest["created_at"],"AWAITING_PLAN","","","NOT_IMPORTED","NOT_APPLIED",""))
    for item in catalog:con.execute("INSERT INTO chatgpt_request_videos VALUES(?,?,?,?,?)",(request_id,item["video_id"],"",json.dumps({"transcript_available":item["transcript_available"]}),json.dumps(["batch_planning.v1"])))
    con.commit();con.close();return {"ok":True,"package_id":planner_id,"folder":str(root),"videos":len(catalog),"skipped_videos":excluded["skipped_count"],"skip_summary":excluded["summary"],"transcript_preflight":preflight,"manual_exchange_only":True}

def import_validate_chatgpt_batch_plan(payload):
    payload=payload or {};raw=str(payload.get("result_json") or "")
    try:plan=json.loads(raw)
    except Exception as ex:raise ValueError(f"Returned planner file is not valid JSON: {ex}")
    package_id=str(plan.get("package_id") or "");schema=str(plan.get("schema_version") or "")
    con=db_connect();req=con.execute("SELECT request_id,schema_version,mode,manifest_json,package_hash FROM chatgpt_requests WHERE package_id=?",(package_id,)).fetchone()
    if not req:con.close();raise ValueError("Unknown planner package_id.")
    request_id,expected_schema,mode,manifest_json,package_hash=req
    if mode!="BATCH_PLANNING":con.close();raise ValueError("This result belongs to an intelligence package, not a batch planner.")
    manifest=json.loads(manifest_json or "{}");expected=set(manifest.get("video_ids") or []);available=set((manifest.get("transcript_preflight") or {}).get("available_ids") or []);unavailable=expected-available
    integrity_errors,verified_files=_validate_chatgpt_package_integrity(package_id,manifest,package_hash)
    def groups(key,allowed,limit):
        out=[];seen=[];errors=[]
        for g in plan.get(key) or []:
            if not isinstance(g,dict):errors.append(f"{key}: group is not an object");continue
            vids=[str(v).strip() for v in (g.get("video_ids") or []) if str(v).strip()]
            if not vids:errors.append(f"{key}: empty group");continue
            if len(vids)>limit:errors.append(f"{key}: group {g.get('group_name') or '?'} has {len(vids)} IDs; limit is {limit}")
            for v in vids:
                if v not in allowed:errors.append(f"{key}: {v} is not allowed in this group type")
            seen.extend(vids);out.append({"group_name":str(g.get("group_name") or "Untitled group"),"video_ids":vids})
        if len(seen)!=len(set(seen)):errors.append(f"{key}: duplicate VIDEO_IDs")
        return out,seen,errors
    full,full_ids,errors=groups("transcript_groups",available,25);none,none_ids,more=groups("no_transcript_groups",unavailable,50);errors+=more;errors+=integrity_errors
    returned=set(full_ids+none_ids);missing=sorted(expected-returned);unexpected=sorted(returned-expected)
    if schema!=expected_schema:errors.append(f"Schema mismatch: expected {expected_schema}, received {schema or 'missing'}")
    if missing:errors.append(f"Missing {len(missing)} catalog VIDEO_ID(s)")
    if unexpected:errors.append("Unexpected VIDEO_IDs: "+", ".join(unexpected[:10]))
    valid=not errors
    review=BASE/"data"/"chatgpt"/"exchange"/"review";review.mkdir(parents=True,exist_ok=True);path=review/f"{package_id}_validated_batch_plan.json";normalized={"package_id":package_id,"schema_version":expected_schema,"valid":valid,"errors":errors,"transcript_groups":full,"no_transcript_groups":none,"created_at":time.strftime("%Y-%m-%d %H:%M:%S")};path.write_text(json.dumps(normalized,indent=2,ensure_ascii=False),encoding="utf-8")
    con.execute("UPDATE chatgpt_requests SET status=?,result_path=?,result_hash=?,validation_status=? WHERE package_id=?",("PLAN_VALIDATED" if valid else "PLAN_INVALID",str(path),hashlib.sha256(raw.encode()).hexdigest(),"VALIDATED" if valid else "INVALID",package_id));con.commit();con.close()
    return {"ok":valid,"package_id":package_id,"valid":valid,"errors":errors,"verified_package_files":verified_files,"plan_file":str(path),"transcript_groups":len(full),"no_transcript_groups":len(none)}

def create_chatgpt_packages_from_validated_plan(options):
    options=options or {};planner_id=str(options.get("planner_package_id") or "").strip()
    if not planner_id:raise ValueError("Select a validated batch planner package first.")
    con=db_connect();row=con.execute("SELECT result_path,validation_status,manifest_json FROM chatgpt_requests WHERE package_id=? AND mode='BATCH_PLANNING'",(planner_id,)).fetchone();con.close()
    if not row or str(row[1])!="VALIDATED":raise ValueError("The selected planner has not been validated successfully.")
    path=Path(str(row[0] or ""));
    if not path.is_file():raise ValueError("Validated planner file is missing.")
    plan=json.loads(path.read_text(encoding="utf-8"))
    if not plan.get("valid"):raise ValueError("Validated planner contains errors and cannot create packages.")
    manifest=json.loads(row[2] or "{}");child=dict(options);child["mode"]="SMART_QUALITY";child["video_ids"]="\n".join(manifest.get("video_ids") or []);child["verify_transcript_availability"]=False;child["planned_groups"]={"transcript_groups":plan.get("transcript_groups") or [],"no_transcript_groups":plan.get("no_transcript_groups") or []}
    result=create_manual_chatgpt_processing_batch_set(child);result["planner_package_id"]=planner_id;return result

def _chatgpt_timestamp_seconds(value):
    if value in (None,""): return None
    if isinstance(value,(int,float)): return float(value)
    text=str(value).strip()
    if not re.fullmatch(r"\d+(?::\d{1,2}){0,2}(?:\.\d+)?",text): return None
    parts=[float(x) for x in text.split(":")]
    if len(parts)==1:return parts[0]
    if len(parts)==2:return parts[0]*60+parts[1]
    return parts[0]*3600+parts[1]*60+parts[2]

def _chatgpt_walk_timestamps(value,path="$",out=None):
    out=[] if out is None else out
    if isinstance(value,dict):
        for k,v in value.items():
            p=f"{path}.{k}"
            if "timestamp" in str(k).lower() or str(k).lower() in {"start","end","start_seconds","end_seconds"}:out.append((p,v))
            _chatgpt_walk_timestamps(v,p,out)
    elif isinstance(value,list):
        for i,v in enumerate(value):_chatgpt_walk_timestamps(v,f"{path}[{i}]",out)
    return out

def _validate_chatgpt_package_integrity(package_id,manifest,stored_package_hash):
    errors=[];verified=[];root=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/package_id
    manifest_path=root/"manifest.json"
    if not manifest_path.is_file():return ["Outgoing manifest.json is missing; package integrity cannot be verified."],verified
    if str(manifest.get("package_id") or "")!=str(package_id):errors.append("Manifest package_id does not match the imported package.")
    actual_manifest_hash=hashlib.sha256(manifest_path.read_bytes()).hexdigest()
    if stored_package_hash and actual_manifest_hash!=stored_package_hash:errors.append("Package manifest checksum mismatch.")
    for name,expected_hash in (manifest.get("hashes") or {}).items():
        p=(root/str(name)).resolve()
        try:p.relative_to(root.resolve())
        except ValueError:errors.append(f"Unsafe evidence path in manifest: {name}");continue
        if not p.is_file():errors.append(f"Evidence file missing: {name}");continue
        actual=hashlib.sha256(p.read_bytes()).hexdigest()
        if actual!=str(expected_hash):errors.append(f"Evidence checksum mismatch: {name}")
        else:verified.append(str(name))
    return errors,verified

def _chatgpt_package_evidence_index(package_id):
    """Return evidence actually present per VIDEO_ID plus transcript time coverage."""
    path=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/str(package_id)/"evidence.json"
    try:data=json.loads(path.read_text(encoding="utf-8"))
    except Exception:return {}
    result={}
    for video in data.get("videos") or []:
        if not isinstance(video,dict):continue
        vid=str(video.get("video_id") or "").strip();evidence=video.get("evidence") or {};metadata=video.get("metadata") or {};manifest=evidence.get("manifest") or {}
        transcript=str(evidence.get("transcript") or "");comments=str(evidence.get("comments") or "")
        sources={"metadata","manifest"}
        if metadata.get("description"):sources.add("description")
        if transcript:sources.add("transcript")
        if comments:sources.add("comments")
        if manifest.get("timestamped_transcript"):sources.add("timestamped_transcript")
        if manifest.get("subtitle"):sources.add("subtitle")
        transcript_times=[_chatgpt_timestamp_seconds(v) for _,v in _chatgpt_walk_timestamps({"transcript":transcript})]
        # Plain transcript text is not a JSON timestamp field, so also inspect
        # common [HH:MM:SS] / HH:MM timestamp tokens without trusting prose.
        transcript_times += [_chatgpt_timestamp_seconds(x) for x in re.findall(r"(?<!\d)(\d{1,3}:\d{2}(?::\d{2}(?:\.\d+)?)?)(?!\d)",transcript)]
        result[vid]={"sources":sources,"transcript_max_seconds":max([x for x in transcript_times if x is not None],default=0.0)}
    return result

def import_validate_manual_chatgpt_processing_result(payload):
    """Archive and validate a user-selected result.  This never writes video metadata or moves files."""
    payload=payload or {};raw=payload.get("result_json")
    if not isinstance(raw,str) or not raw.strip(): raise ValueError("Select a returned JSON file first.")
    try: result=json.loads(raw)
    except Exception as ex: raise ValueError(f"Returned file is not valid JSON: {ex}")
    if not isinstance(result,dict): raise ValueError("Returned JSON must be one object containing package_id and video_updates.")
    package_id=str(result.get("package_id") or "").strip();schema=str(result.get("schema_version") or "").strip()
    if not package_id: raise ValueError("Returned JSON is missing package_id.")
    con=db_connect();request=con.execute("SELECT request_id,schema_version,requested_features_json,manifest_json,package_hash FROM chatgpt_requests WHERE package_id=?",(package_id,)).fetchone()
    if not request: con.close();raise ValueError("Unknown package_id. Import the result for a package created by this VideoHoarder library.")
    request_id,expected_schema,features,manifest_json,stored_package_hash=request;features=json.loads(features or "[]");manifest=json.loads(manifest_json or "{}")
    expected={str(r[0]) for r in con.execute("SELECT video_id FROM chatgpt_request_videos WHERE request_id=?",(request_id,)).fetchall()}
    updates=result.get("video_updates") or result.get("videos") or []
    normalized_keyed_updates=False
    # Compatibility: earlier package files did not include an exact response
    # template, so ChatGPT reasonably returned {VIDEO_ID: feature_data}. Keep
    # accepting that safe, common representation and normalize only in memory.
    if isinstance(updates,dict):
        normalized_keyed_updates=True
        updates=[{"video_id":str(video_id),"features":feature_data} for video_id,feature_data in updates.items()]
    if not isinstance(updates,list): con.close();raise ValueError("video_updates must be a JSON array, or a VIDEO_ID-keyed JSON object.")
    returned=[];unexpected=[];warnings=[];errors=[];evidence_index=_chatgpt_package_evidence_index(package_id)
    integrity_errors,verified_files=_validate_chatgpt_package_integrity(package_id,manifest,stored_package_hash);errors+=integrity_errors
    for item in updates:
        if not isinstance(item,dict): warnings.append("Ignored a non-object update.");continue
        vid=str(item.get("video_id") or "").strip()
        if not vid: warnings.append("Ignored update with no video_id.");continue
        returned.append(vid)
        if vid not in expected: unexpected.append(vid)
        refs=item.get("evidence_references") or item.get("evidence") or []
        if not refs:warnings.append(f"{vid}: no evidence reference supplied")
        if not isinstance(refs,list):errors.append(f"{vid}: evidence_references must be an array");refs=[]
        allowed={"metadata","description","transcript","comments","manifest","timestamped_transcript","subtitle","existing_intelligence"}
        bad=[str(x) for x in refs if str(x) not in allowed]
        if bad:errors.append(f"{vid}: unknown provenance reference(s): {', '.join(bad[:10])}")
        available=set((evidence_index.get(vid) or {}).get("sources") or [])
        unavailable=[str(x) for x in refs if str(x) in allowed and str(x)!="existing_intelligence" and str(x) not in available]
        if unavailable:errors.append(f"{vid}: provenance references unavailable package evidence: {', '.join(unavailable[:10])}")
        duration_row=con.execute("SELECT COALESCE(duration_seconds,0) FROM videos WHERE video_id=?",(vid,)).fetchone();duration=float((duration_row or [0])[0] or 0)
        transcript_limit=float((evidence_index.get(vid) or {}).get("transcript_max_seconds") or 0)
        timestamp_limit=duration or transcript_limit
        for timestamp_path,timestamp_value in _chatgpt_walk_timestamps(item.get("features") or item):
            seconds=_chatgpt_timestamp_seconds(timestamp_value)
            if timestamp_value not in (None,"") and seconds is None:errors.append(f"{vid}: invalid timestamp at {timestamp_path}: {timestamp_value}")
            elif seconds is not None and seconds<0:errors.append(f"{vid}: negative timestamp at {timestamp_path}")
            elif seconds is not None and timestamp_limit and seconds>timestamp_limit+2:errors.append(f"{vid}: timestamp {timestamp_value} exceeds available video/transcript duration {timestamp_limit:.1f}s at {timestamp_path}")
    if schema!=expected_schema: warnings.append(f"Schema version mismatch: expected {expected_schema}, received {schema or 'missing'}.")
    if unexpected: warnings.append("Unauthorised video IDs: "+", ".join(sorted(set(unexpected))[:20]))
    missing=sorted(expected-set(returned))
    if missing: warnings.append(f"Partial result: {len(missing)} requested video(s) not returned.")
    valid=not unexpected and schema==expected_schema and not errors
    warnings.extend(errors)
    status="VALIDATED" if valid and not missing else ("PARTIAL" if valid else "INVALID")
    incoming=BASE/"data"/"chatgpt"/"exchange"/"incoming";incoming.mkdir(parents=True,exist_ok=True)
    safe_name=re.sub(r"[^A-Za-z0-9._-]+","_",str(payload.get("filename") or "chatgpt_result.json"))
    saved=incoming/f"{package_id}_{time.strftime('%Y%m%d_%H%M%S')}_{safe_name}"
    saved.write_text(raw,encoding="utf-8")
    result_hash=hashlib.sha256(raw.encode("utf-8")).hexdigest()
    if normalized_keyed_updates: warnings.insert(0,"Accepted legacy VIDEO_ID-keyed video_updates and normalized it locally. Future packages require the documented array structure.")
    preview={"package_id":package_id,"request_id":request_id,"status":status,"requested_features":features,"returned_video_ids":sorted(set(returned)),"missing_video_ids":missing,"warnings":warnings,"errors":errors,"verified_package_files":verified_files,"result_file":str(saved),"result_hash":result_hash,"manual_review_required":True,"automatic_apply":False,"input_format":"VIDEO_ID_KEYED_OBJECT" if normalized_keyed_updates else "VIDEO_UPDATE_ARRAY","proposed_updates":updates}
    review=BASE/"data"/"chatgpt"/"exchange"/"review";review.mkdir(parents=True,exist_ok=True)
    preview_path=review/f"{package_id}_{result_hash[:12]}_review.json";preview_path.write_text(json.dumps(preview,indent=2,ensure_ascii=False),encoding="utf-8")
    con.execute("UPDATE chatgpt_requests SET status=?,result_path=?,result_hash=?,validation_status=?,applied_status=? WHERE request_id=?",(status,str(saved),result_hash,status,"NOT_APPLIED",request_id))
    for vid in set(returned)&expected:
        for fid in features:
            name,ver=fid.split('.',1)
            con.execute("UPDATE video_feature_coverage SET status=?,result_hash=?,completed_at=?,last_error=? WHERE video_id=? AND feature_id=? AND feature_version=?",("RESULT_AVAILABLE" if valid else "NEEDS_VALIDATION",result_hash,time.strftime("%Y-%m-%d %H:%M:%S"),"; ".join(warnings[:3]),vid,name,"v"+ver))
            con.execute("INSERT INTO chatgpt_import_field_history VALUES(?,?,?,?,?,?,?,?,?)",(str(uuid.uuid4()),vid,name,"$", "",result_hash,"PROPOSED","MANUAL_REVIEW",time.strftime("%Y-%m-%d %H:%M:%S")))
    con.commit();con.close()
    return {"ok":valid,"package_id":package_id,"status":status,"warnings":warnings,"returned":len(set(returned)),"missing":len(missing),"preview":str(preview_path),"result_file":str(saved),"input_format":"VIDEO_ID_KEYED_OBJECT" if normalized_keyed_updates else "VIDEO_UPDATE_ARRAY","manual_review_required":True,"applied":False}

def chatgpt_processing_review(package_id=""):
    con=db_connect();args=[];where=""
    if package_id: where=" WHERE package_id=?";args=[package_id]
    rows=con.execute("SELECT package_id,status,result_path,result_hash,validation_status,applied_status FROM chatgpt_requests"+where+" ORDER BY created_at DESC LIMIT 50",args).fetchall();con.close()
    out=[]
    for package_id,status,result_path,result_hash,validation,applied in rows:
        preview=BASE/"data"/"chatgpt"/"exchange"/"review"/f"{package_id}_{str(result_hash or '')[:12]}_review.json"
        preview_data={}
        if preview.is_file():
            try:preview_data=json.loads(preview.read_text(encoding="utf-8"))
            except Exception:preview_data={}
        out.append({"package_id":package_id,"status":status,"validation_status":validation,"applied_status":applied,"result_path":result_path,"review_preview":str(preview) if preview.is_file() else "","proposed_updates":preview_data.get("proposed_updates") or [],"warnings":preview_data.get("warnings") or [],"errors":preview_data.get("errors") or [],"manual_actions_only":["Review rename suggestion in existing Rename tool","Review category move in existing move preview","Review duplicate canonical choice","Review Clip Studio plan"]})
    return out

def record_chatgpt_review_decisions(payload):
    """Persist explicit field/action decisions; physical actions remain separate reviewed tools."""
    payload=payload or {};package_id=str(payload.get("package_id") or "").strip();decisions=payload.get("decisions") or []
    if not package_id:raise ValueError("package_id is required")
    if not isinstance(decisions,list) or not decisions:raise ValueError("Select at least one proposed field/action.")
    allowed={"rename","move","metadata","taxonomy","duplicate_keep","duplicate_archive","duplicate_mark_delete","clip_plan","report_refresh"}
    clean=[]
    for row in decisions:
        if not isinstance(row,dict):continue
        action=str(row.get("action") or "").strip()
        if action not in allowed:raise ValueError(f"Unsupported review action: {action}")
        clean.append({"video_id":str(row.get("video_id") or ""),"feature_id":str(row.get("feature_id") or ""),"field_path":str(row.get("field_path") or "$"),"action":action,"approved":bool(row.get("approved")),"value":row.get("value")})
    if not clean:raise ValueError("No valid review decisions supplied.")
    root=BASE/"data"/"chatgpt"/"exchange"/"review"/"decisions";root.mkdir(parents=True,exist_ok=True)
    record={"package_id":package_id,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"decisions":clean,"physical_changes_applied":False,"next_routes":{"rename":"/app?tab=chatgpt","move":"/app?tab=chatgpt","duplicates":"/app?tab=tools&command=duplicate_audit","clips":"/app?tab=clips"}}
    path=root/f"{package_id}_{time.strftime('%Y%m%d_%H%M%S')}.json";path.write_text(json.dumps(record,indent=2,ensure_ascii=False),encoding="utf-8")
    con=db_connect();con.execute("UPDATE chatgpt_requests SET applied_status='REVIEWED_NOT_APPLIED',notes=? WHERE package_id=?",(f"Review decisions: {path}",package_id));con.commit();con.close()
    return {"ok":True,"record":str(path),"decisions":len(clean),"physical_changes_applied":False,"next_routes":record["next_routes"]}

def record_chatgpt_duplicate_review(payload):
    """Record a reviewed duplicate group without moving or deleting media."""
    payload=payload or {};group=payload.get("group") or {};canonical=str(payload.get("canonical_video_id") or "").strip();choices=payload.get("choices") or []
    ids=[str(x).strip() for x in (group.get("video_ids") or []) if str(x).strip()]
    if len(ids)<2:raise ValueError("Duplicate review requires at least two VIDEO_IDs.")
    if canonical not in ids:raise ValueError("Canonical VIDEO_ID must belong to the duplicate group.")
    allowed={"keep","archive","mark_delete"};normalized=[]
    for row in choices:
        vid=str((row or {}).get("video_id") or "").strip();decision=str((row or {}).get("decision") or "keep").strip().lower()
        if vid not in ids:raise ValueError(f"Unknown VIDEO_ID in duplicate choice: {vid}")
        if decision not in allowed:raise ValueError(f"Unsupported duplicate decision: {decision}")
        if vid==canonical and decision!="keep":raise ValueError("The canonical video must be kept.")
        normalized.append({"video_id":vid,"decision":decision})
    decided={x["video_id"] for x in normalized}
    normalized.extend({"video_id":vid,"decision":"keep"} for vid in ids if vid not in decided)
    record={"review_id":str(uuid.uuid4()),"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"canonical_video_id":canonical,"group_name":str(group.get("group_name") or "Duplicate group"),"choices":normalized,"physical_changes_applied":False,"manual_delete_only":True}
    root=BASE/"data"/"chatgpt"/"exchange"/"review"/"duplicates";root.mkdir(parents=True,exist_ok=True);path=root/f"duplicate_{record['review_id']}.json";path.write_text(json.dumps(record,indent=2,ensure_ascii=False),encoding="utf-8")
    return {"ok":True,"record":str(path),"review":record,"duplicate_audit_route":"/app?tab=tools&command=duplicate_audit"}

def validate_chatgpt_clip_plan(payload,save=False):
    payload=payload or {};plan=payload.get("plan") if isinstance(payload.get("plan"),dict) else payload
    clips=plan.get("clips") or plan.get("merge_clip_plan") or []
    if not isinstance(clips,list) or not clips:raise ValueError("Clip plan must contain a non-empty clips array.")
    con=db_connect();normalized=[];errors=[]
    for index,clip in enumerate(clips,1):
        if not isinstance(clip,dict):errors.append(f"Clip {index}: not an object");continue
        vid=str(clip.get("video_id") or "").strip();row=con.execute("SELECT local_video,COALESCE(duration_seconds,0) FROM videos WHERE video_id=?",(vid,)).fetchone()
        if not row:errors.append(f"Clip {index}: unknown VIDEO_ID {vid}");continue
        start=_chatgpt_timestamp_seconds(clip.get("start_seconds",clip.get("start_timestamp")));end=_chatgpt_timestamp_seconds(clip.get("end_seconds",clip.get("end_timestamp")))
        if start is None or end is None:errors.append(f"Clip {index}: invalid start/end timestamp");continue
        if start<0 or end<=start:errors.append(f"Clip {index}: end must be greater than start");continue
        duration=float(row[1] or 0)
        if duration and end>duration+2:errors.append(f"Clip {index}: end {end:.1f}s exceeds video duration {duration:.1f}s");continue
        source=str(row[0] or "")
        if not source:errors.append(f"Clip {index}: video has no local media path");continue
        normalized.append({"order":index,"included":bool(clip.get("included",True)),"video_id":vid,"source":source,"start":start,"end":end,"duration":round(end-start,3),"title":str(clip.get("title") or f"Clip {index}")})
    con.close();valid=not errors and len(normalized)==len(clips);out={"ok":valid,"valid":valid,"errors":errors,"clips":normalized,"manual_handoff_only":True}
    if save and valid:
        root=BASE/"data"/"chatgpt"/"exchange"/"review"/"clip_plans";root.mkdir(parents=True,exist_ok=True);path=root/f"clip_plan_{time.strftime('%Y%m%d_%H%M%S')}.json";path.write_text(json.dumps(out,indent=2,ensure_ascii=False),encoding="utf-8");out.update({"saved":str(path),"clip_studio_route":"/app?tab=clips","executed":False})
    return out

def import_validate_many_manual_chatgpt_processing_results(payload):
    """Validate a user-selected set of result files; each remains review-only."""
    items=(payload or {}).get("results") or []
    if not isinstance(items,list) or not items: raise ValueError("Select one or more returned JSON files first.")
    if len(items)>200: raise ValueError("Select no more than 200 JSON files at once.")
    outcomes=[]
    for item in items:
        try: outcomes.append(import_validate_manual_chatgpt_processing_result(item))
        except Exception as ex: outcomes.append({"ok":False,"filename":str((item or {}).get("filename") or "unknown"),"message":f"{type(ex).__name__}: {ex}"})
    return {"ok":all(x.get("ok") for x in outcomes),"files":len(outcomes),"validated":sum(1 for x in outcomes if x.get("status")=="VALIDATED"),"partial":sum(1 for x in outcomes if x.get("status")=="PARTIAL"),"failed":sum(1 for x in outcomes if not x.get("ok")),"outcomes":outcomes,"manual_review_required":True,"applied":False}

def export_chatgpt_processing_review_csv():
    """Create one local, review-only CSV from validated/partial imported result previews."""
    import csv
    review_dir=BASE/"data"/"chatgpt"/"exchange"/"review";review_dir.mkdir(parents=True,exist_ok=True)
    out_dir=BASE/"data"/"chatgpt"/"exchange"/"exports";out_dir.mkdir(parents=True,exist_ok=True)
    rows=[]
    for preview_path in sorted(review_dir.glob("*_review.json")):
        try: preview=json.loads(preview_path.read_text(encoding="utf-8"))
        except Exception: continue
        if preview.get("status") not in {"VALIDATED","PARTIAL"}: continue
        for item in preview.get("proposed_updates") or []:
            if not isinstance(item,dict): continue
            video_id=str(item.get("video_id") or "")
            features=item.get("features") if isinstance(item.get("features"),dict) else {k:v for k,v in item.items() if k in CHATGPT_FEATURES}
            for feature_id,value in (features or {}).items():
                rows.append({"package_id":preview.get("package_id",""),"request_id":preview.get("request_id",""),"validation_status":preview.get("status",""),"video_id":video_id,"feature_id":feature_id,"evidence_references":json.dumps(item.get("evidence_references") or item.get("evidence") or [],ensure_ascii=False),"proposed_value_json":json.dumps(value,ensure_ascii=False),"review_preview":str(preview_path),"applied":"NO"})
    out=out_dir/f"chatgpt_review_combined_{time.strftime('%Y%m%d_%H%M%S')}.csv"
    fields=["package_id","request_id","validation_status","video_id","feature_id","evidence_references","proposed_value_json","review_preview","applied"]
    with out.open("w",encoding="utf-8-sig",newline="") as f:
        writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows)
    return {"ok":True,"csv":str(out),"rows":len(rows),"manual_review_only":True,"applied":False}

def chatgpt_processing_unprocessed_packages():
    """Only packages with no returned/imported result may be removed from local exchange storage."""
    con=db_connect();rows=con.execute("SELECT package_id,created_at,mode,requested_features_json FROM chatgpt_requests WHERE status='AWAITING_RESULT' AND COALESCE(result_path,'')='' ORDER BY created_at DESC").fetchall();con.close()
    out=[]
    for package_id,created_at,mode,features_json in rows:
        folder=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/str(package_id)
        out.append({"package_id":package_id,"created_at":created_at,"mode":mode,"features":json.loads(features_json or '[]'),"folder":str(folder),"folder_exists":folder.is_dir()})
    return out

def delete_unprocessed_chatgpt_packages(package_ids):
    """Remove only locally-created, unprocessed package folders; retain a deletion audit row."""
    package_ids=[str(x).strip() for x in (package_ids or []) if str(x).strip()]
    if not package_ids: raise ValueError("Select at least one unprocessed package.")
    if len(package_ids)>200: raise ValueError("Select no more than 200 packages at once.")
    con=db_connect();deleted=[];skipped=[]
    for package_id in package_ids:
        row=con.execute("SELECT status,result_path FROM chatgpt_requests WHERE package_id=?",(package_id,)).fetchone()
        if not row or row[0]!="AWAITING_RESULT" or str(row[1] or ""):
            skipped.append({"package_id":package_id,"reason":"Only packages awaiting a result and never imported can be deleted."});continue
        folder=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/package_id
        if folder.is_dir(): shutil.rmtree(folder)
        con.execute("UPDATE chatgpt_requests SET status='DELETED',notes=? WHERE package_id=?",(f"Outgoing package removed locally at {time.strftime('%Y-%m-%d %H:%M:%S')}",package_id))
        con.execute("DELETE FROM video_feature_coverage WHERE package_id=? AND status='REQUESTED'",(package_id,))
        deleted.append(package_id)
    con.commit();con.close()
    return {"ok":not skipped,"deleted":deleted,"skipped":skipped,"message":"Only local unprocessed package folders were removed; processed/imported packages were retained."}


