    import_panel=import_panel.replace('<h2>Old Library Import &amp; Repair</h2>', '<h2>Old Library Import &amp; Repair</h2><div class="actions"><button class="btn danger" onclick="closePreviousSessions()">Close Previous App Sessions</button></div><div id="oldSessionHint" class="muted" style="margin-top:7px">Use this if an older window is still running or the interface looks outdated. The current window stays open.</div>', 1)
    page=page.replace('</section><section id="status" class="section">', import_panel+'</section><section id="status" class="section">', 1)
