def web_json_default(obj):
    """Convert browser/API diagnostic objects into JSON-safe values."""
    if isinstance(obj,Path):
        return str(obj)
    if isinstance(obj,datetime):
        return obj.isoformat()
    if isinstance(obj,set):
        return sorted(str(x) for x in obj)
    if isinstance(obj,tuple):
        return list(obj)
    if isinstance(obj,bytes):
        return obj.decode("utf-8",errors="replace")
    try:
        if hasattr(obj,"keys"):
            return {str(k):obj[k] for k in obj.keys()}
    except Exception:
        pass
    return str(obj)

def web_json_safe(obj):
    return json.loads(json.dumps(obj,default=web_json_default,ensure_ascii=False))


