def chatgpt_processing_page_html_v2():
    features=''.join(f'<label><input type="checkbox" value="{html.escape(k)}" checked> {html.escape(k)} — {html.escape(v)}</label>' for k,v in CHATGPT_FEATURES.items())
    navigation=[('overview','Overview'),('create','Create Package'),('history','Request History'),('coverage','Feature Coverage'),('import','Import & Validate'),('review','Review & Apply'),('duplicates','Duplicates'),('clips','Clip Plans'),('maintenance','Maintenance')]
    nav=''.join(f'<button onclick="show(\'{key}\')">{label}</button>' for key,label in navigation)
    return f'''<!doctype html><html><head><meta charset="utf-8"><style>body{{margin:0;background:#081426;color:#eef5ff;font:15px Segoe UI,Arial}}.top{{padding:18px 24px;background:#0e2038;border-bottom:1px solid #294667;font-size:22px;font-weight:700}}.layout{{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 61px)}}nav{{background:#0b1a2d;border-right:1px solid #294667;padding:14px}}nav button{{display:block;width:100%;text-align:left;margin:5px 0;background:transparent;border:0;color:#b9cae2;padding:11px;border-radius:8px;font-size:14px}}main{{padding:22px;max-width:1250px}}.notice{{background:#13325a;border:1px solid #2f649b;padding:14px;border-radius:10px;color:#d9ecff}}.grid{{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin:15px 0}}.card{{background:#0f2036;border:1px solid #294667;border-radius:12px;padding:16px;margin:12px 0}}.count{{font-size:30px;font-weight:700;color:#fff}}.panel{{display:none}}.panel.active{{display:block}}textarea,select,input{{box-sizing:border-box;background:#071120;color:#fff;border:1px solid #315273;border-radius:7px;padding:9px}}textarea,select{{width:100%}}textarea{{height:90px}}button.primary{{background:#1670ea;color:#fff;border:0;border-radius:8px;padding:11px 14px;font-weight:700}}.features label{{display:block;color:#c8d8ed;margin:7px 0}}pre{{white-space:pre-wrap;max-height:420px;overflow:auto;background:#071120;padding:12px;border-radius:8px}}</style></head><body><div class="top">ChatGPT Processing <span style="font-size:13px;color:#9eb5d1">Manual Exchange Command Center</span></div><div class="layout"><nav>{nav}</nav><main><section id="overview" class="panel active"><div class="notice"><b>Manual exchange safety:</b> VideoHoarder creates local packages only. You upload manually to ChatGPT, then manually select returned JSON. Nothing is uploaded or applied automatically.</div><div id="counters" class="grid"></div><div class="card"><h3>Six-step manual flow</h3>Select → Review evidence → Create package → Upload manually → Import & validate → Review & apply.</div><div class="card"><h3>Quick actions</h3><button class="primary" onclick="show('create')">Create package</button> <button class="primary" onclick="show('history')">View history</button> <button class="primary" onclick="show('coverage')">Feature coverage</button></div></section><section id="create" class="panel"><h2>Create Package</h2><div class="card"><label>Mode</label><select id="mode"><option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option></select><label>VIDEO_IDs (optional; blank selects eligible active videos)</label><textarea id="ids"></textarea><div class="features">{features}</div><button class="primary" onclick="createPackage()">Create local manual package</button><pre id="createOut"></pre></div></section><section id="history" class="panel"><h2>Request History</h2><pre id="historyOut"></pre></section><section id="coverage" class="panel"><h2>Feature Coverage</h2><button class="primary" onclick="loadCoverage()">Refresh matrix</button><pre id="coverageOut"></pre></section><section id="import" class="panel"><h2>Import & Validate</h2><div class="notice"><b>Nothing is applied here.</b> Select JSON manually saved from ChatGPT. VideoHoarder archives it locally, validates it and creates a review preview.</div><div class="card"><input id="resultFile" type="file" accept="application/json,.json"> <button class="primary" onclick="importResult()">Import & validate selected result</button><pre id="importOut"></pre></div></section><section id="review" class="panel"><h2>Review & Apply</h2><div class="notice">Review previews before using existing reviewed rename, category-move preview, metadata, taxonomy and undo tools. No physical rename, move, deletion, cut, or merge happens automatically.</div><button class="primary" onclick="loadReview()">Refresh reviewed results</button><pre id="reviewOut"></pre></section><section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Suggestions only. Choose a canonical video and manually keep, archive, mark delete or delete. No automatic deletion.</div></section><section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">Suggestions only. Review and manually send a valid plan to existing Clip Studio; no automatic cut or merge.</div></section><section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Existing integrity, comment-intelligence, legacy sync and audit tools remain local and traceable.</div></section></main></div><script>const $=x=>document.getElementById(x);async function api(u,o){{return await fetch(u,o).then(r=>r.json())}}function show(id){{document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');if(id==='overview')loadOverview();if(id==='history')loadHistory();if(id==='coverage')loadCoverage();if(id==='review')loadReview()}}async function loadOverview(){{let x=await api('/api/chatgpt-processing/overview');let n=Object.values(x.requests||{{}}).reduce((a,b)=>a+b,0),u=Object.values(x.coverage||{{}}).reduce((a,b)=>a+b,0);$('counters').innerHTML=[['Packages',n],['Videos with intelligence',u],['Feature updates',u]].map(v=>`<div class="card"><div>${{v[0]}}</div><div class="count">${{v[1]}}</div></div>`).join('')}}async function createPackage(){{let f=[...document.querySelectorAll('.features input:checked')].map(x=>x.value);let x=await api('/api/chatgpt-processing/create',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{mode:$('mode').value,video_ids:$('ids').value,features:f}})}});$('createOut').textContent=JSON.stringify(x,null,2);loadOverview()}}async function loadHistory(){{$('historyOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/history'),null,2)}}async function loadCoverage(){{$('coverageOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/coverage'),null,2)}}async function importResult(){{let f=$('resultFile').files[0];if(!f){{$('importOut').textContent='Select the returned JSON file first.';return}}let x=await api('/api/chatgpt-processing/import',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{filename:f.name,result_json:await f.text()}})}});$('importOut').textContent=JSON.stringify(x,null,2);loadOverview()}}async function loadReview(){{$('reviewOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/review'),null,2)}}loadOverview()</script></body></html>'''

def chatgpt_processing_page_html_v3():
    page=chatgpt_processing_page_html_v2()
    return page.replace('<option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option>', '<option value="SMART_QUALITY">SMART QUALITY - 25 transcript / 50 no-transcript</option><option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option>')

def chatgpt_processing_page_html_v4():
    page=chatgpt_processing_page_html_v3()
    page=page.replace('id="resultFile" type="file" accept="application/json,.json"', 'id="resultFiles" type="file" accept="application/json,.json" multiple> <label style="display:block;margin-top:8px">Or choose a folder of returned JSON files:</label><input id="resultFolder" type="file" accept="application/json,.json" multiple webkitdirectory directory')
    page=page.replace('Import & validate selected result', 'Import & validate selected JSON file(s) / folder')
    page=page.replace('<button class="primary" onclick="loadReview()">Refresh reviewed results</button>', '<button class="primary" onclick="loadReview()">Refresh reviewed results</button> <button class="primary" onclick="exportReviewCsv()">Create combined review CSV</button>')
    script='''<script>async function importMany(){let fs=[...document.getElementById('resultFiles').files,...document.getElementById('resultFolder').files].filter(f=>f.name.toLowerCase().endsWith('.json'));let seen=new Set;fs=fs.filter(f=>!seen.has(f.name)&&seen.add(f.name));if(!fs.length){document.getElementById('importOut').textContent='Select one or more returned JSON files, or choose a folder containing them.';return}document.getElementById('importOut').textContent='Reading and validating '+fs.length+' JSON file(s)...';let results=[];for(const f of fs){results.push({filename:f.name,result_json:await f.text()})}let x=await api('/api/chatgpt-processing/import-many',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({results})});document.getElementById('importOut').textContent=JSON.stringify(x,null,2);loadOverview()}async function exportReviewCsv(){let x=await api('/api/chatgpt-processing/export-review-csv',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});document.getElementById('reviewOut').textContent=JSON.stringify(x,null,2)}document.querySelector('#import button.primary').setAttribute('onclick','importMany()');</script>'''
    selectors_script='''<script>(async function(){try{const x=await api('/api/chatgpt-processing/selectors');const map={folderScope:x.folders||[],topicScope:x.topics||[],categoryScope:x.categories||[]};Object.entries(map).forEach(([id,vals])=>{const e=$(id);if(!e)return;vals.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;e.appendChild(o)});e.addEventListener('change',()=>{const ids=$('ids');if(ids&&!ids.value)ids.placeholder='Selected '+id.replace('Scope','')+': '+e.value+' (backend scope wiring follows current package selection)'});});}catch(e){}})();</script>'''
    return page.replace('</body>',script+selectors_script+'</body>')

def chatgpt_processing_page_html_v5():
    page=chatgpt_processing_page_html_v4()
    old='<section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Existing integrity, comment-intelligence, legacy sync and audit tools remain local and traceable.</div></section>'
    new='<section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Existing integrity, comment-intelligence, legacy sync and audit tools remain local and traceable.</div><div class="card"><h3>Remove unprocessed packages</h3><p>Only local outgoing packages with no returned/imported result are listed. Processed or imported packages cannot be removed here. The request history is retained as DELETED.</p><label>Filter by batch number or package ID</label><input id="packageBatchFilter" placeholder="Example: 2 or 20260813"><button class="primary" onclick="loadUnprocessedPackages()">Refresh filtered list</button> <button class="primary" onclick="deleteSelectedUnprocessed()">Delete selected local packages</button><div id="unprocessedList"></div><pre id="maintenanceOut"></pre></div></section>'
    page=page.replace(old,new)
    script='''<script>async function loadUnprocessedPackages(){let x=await api('/api/chatgpt-processing/unprocessed-packages');let q=(document.getElementById('packageBatchFilter')?.value||'').toLowerCase();let a=(x.items||[]).filter(p=>!q||String(p.package_id||'').toLowerCase().includes(q)||String(p.batch_number||'').toLowerCase()===q);document.getElementById('unprocessedList').innerHTML=a.length?a.map(p=>`<label style="display:block;margin:8px 0"><input type="checkbox" class="unprocessedPackage" value="${p.package_id}"> <b>${p.package_id}</b> - batch ${p.batch_number||'—'} - ${p.mode} - ${p.created_at}<br><small>${p.folder}</small></label>`).join(''):'<p>No matching unprocessed packages are available for deletion.</p>'}async function deleteSelectedUnprocessed(){let ids=[...document.querySelectorAll('.unprocessedPackage:checked')].map(x=>x.value);if(!ids.length){document.getElementById('maintenanceOut').textContent='Select one or more packages first.';return}if(!confirm('Delete '+ids.length+' local unprocessed package folder(s)? Imported/processed packages are not affected.'))return;let x=await api('/api/chatgpt-processing/delete-unprocessed-packages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({package_ids:ids})});document.getElementById('maintenanceOut').textContent=JSON.stringify(x,null,2);loadUnprocessedPackages();loadOverview();if(window.loadHistory)loadHistory()}</script>'''
    review_script='''<script>(function(){function esc(v){return String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function fields(value,path,out){out=out||[];if(value&&typeof value==='object'&&!Array.isArray(value)){Object.entries(value).forEach(([k,v])=>fields(v,path?path+'.'+k:k,out))}else out.push([path,value]);return out}window.loadReview=async function(){const x=await api('/api/chatgpt-processing/review'),items=x.items||[],root=$('reviewOut');if(!root)return;root.outerHTML='<div id="reviewOut">'+(items.map(p=>'<div class="card"><div class="section-head"><h3>'+esc(p.package_id)+'</h3><span class="status-chip">'+esc(p.validation_status)+'</span></div>'+(p.errors||[]).map(e=>'<div class="notice">'+esc(e)+'</div>').join('')+(p.proposed_updates||[]).map(u=>'<div class="work-stat"><b>'+esc(u.video_id)+'</b>'+Object.entries(u.features||{}).flatMap(([fid,val])=>fields(val,fid)).map(([field,val])=>'<div class="review-field"><label><input class="reviewDecision" type="checkbox" data-package="'+esc(p.package_id)+'" data-video="'+esc(u.video_id)+'" data-feature="'+esc(field.split('.')[0])+'" data-field="'+esc(field)+'" data-value="'+encodeURIComponent(JSON.stringify(val))+'"> <b>'+esc(field)+'</b>: '+esc(typeof val==='object'?JSON.stringify(val):val)+'</label><select class="reviewAction"><option value="metadata">Approve metadata</option><option value="taxonomy">Approve taxonomy</option><option value="rename">Stage rename preview</option><option value="move">Stage folder-move preview</option><option value="duplicate_keep">Duplicate: keep</option><option value="duplicate_archive">Duplicate: archive</option><option value="duplicate_mark_delete">Duplicate: mark delete</option><option value="clip_plan">Stage clip plan</option><option value="report_refresh">Refresh report</option></select></div>').join('')+'</div>').join('')+'<button class="primary" onclick="saveReviewDecisions(\''+esc(p.package_id)+'\')">Save approved field decisions</button></div>').join('')||'<div class="card">No imported results are ready for review.</div>')+'</div>'};window.saveReviewDecisions=async function(packageId){const decisions=[...document.querySelectorAll('.reviewDecision:checked[data-package="'+packageId+'"]')].map(c=>({video_id:c.dataset.video,feature_id:c.dataset.feature,field_path:c.dataset.field,action:c.closest('.review-field').querySelector('.reviewAction').value,approved:true,value:JSON.parse(decodeURIComponent(c.dataset.value))}));const x=await api('/api/chatgpt-processing/review-decisions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({package_id:packageId,decisions})});alert(x.message||('Saved '+(x.decisions||0)+' reviewed field decision(s). Physical file changes were not applied.'))}})();</script>'''
    return page.replace('</body>',script+review_script+'</body>')

