def chatgpt_processing_page_html_v8():
    """Use the shared job queue so package creation reports live progress."""
    page=chatgpt_processing_page_html_v7()
    page=page.replace("payload={mode:$('mode').value,video_ids:$('ids').value,verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f}", "payload={mode:$('mode').value,video_ids:$('ids').value,folderScope:$('folderScope')?.value||'',topicScope:$('topicScope')?.value||'',categoryScope:$('categoryScope')?.value||'',verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f}")
    script='''<script>(function(){let createTimer=null;function out(t){const e=document.getElementById('createOut');if(e)e.textContent=t}function line(j){return (j.label||'Create ChatGPT package')+' — '+(j.status||'')+'\\nPhase: '+(j.phase||'Preparing')+'\\nCurrent video: '+(j.current_file||'Preparing')+'\\nStatus: '+(j.current_status||j.message||'')+(j.total?'\\nOverall: '+(j.processed||0)+' / '+j.total:'')+(j.current_percent?'\\nProgress: '+j.current_percent:'')+(j.current_speed?' · '+j.current_speed:'')+(j.current_eta?' · ETA '+j.current_eta:'')}async function watchCreate(jobId){if(createTimer)clearInterval(createTimer);async function tick(){try{const x=await api('/api/job-detail?id='+encodeURIComponent(jobId)),j=x.job||{};out(line(j));if(['SUCCESS','WARN','FAILED','CANCELLED'].includes(j.status)){clearInterval(createTimer);if(j.result)out(line(j)+'\\n\\n'+JSON.stringify(j.result,null,2));loadOverview()}}catch(e){out('Progress check failed: '+e)}}await tick();createTimer=setInterval(tick,1000)}window.watchCreate=watchCreate;window.createPackage=async function(){let f=[...document.querySelectorAll('.features input:checked')].map(x=>x.value),payload={mode:$('mode').value,video_ids:$('ids').value,verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f};out('Queuing package creation…');let x=await api('/api/job-start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'chatgpt_processing_create',payload:payload})});if(!x.ok){out(x.message||JSON.stringify(x));return}out(x.message+'\\nWaiting for live progress…');watchCreate(x.job_id)}})();</script>'''
    return page.replace('</body>',script+'</body>')

