    page=page.replace('<section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Suggestions only. Choose a canonical video and manually keep, archive, mark delete or delete. No automatic deletion.</div></section>', '<section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Suggestions only. Paste one duplicate group, choose its canonical VIDEO_ID, then record Keep, Archive or Mark Delete per video. Nothing is deleted automatically.</div><div class="card"><label>Duplicate group JSON</label><textarea id="duplicatePlan" placeholder=\'{"group_name":"Same recording","video_ids":["ID1","ID2"]}\'></textarea><button class="primary" onclick="loadDuplicateGroup()">Preview duplicate group</button><div id="duplicateReview"></div><button class="primary" onclick="saveDuplicateReview()">Save reviewed choices</button><button onclick="location.href=\'/app?tab=tools&command=duplicate_audit\'">Open existing Duplicate Audit</button><pre id="duplicateOut"></pre></div></section>',1)
    page=page.replace('<section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">Suggestions only. Review and manually send a valid plan to existing Clip Studio; no automatic cut or merge.</div></section>', '<section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">Paste a ChatGPT clip-plan JSON. VideoHoarder validates VIDEO_IDs, timestamps, order and duration. Handoff only saves a reviewed plan; it does not cut or merge.</div><div class="card"><textarea id="clipPlanJson" placeholder=\'{"clips":[{"video_id":"...","start_timestamp":"00:10","end_timestamp":"00:30"}]}\'></textarea><button class="primary" onclick="validateClipPlan(false)">Validate clip plan</button><button class="primary" onclick="validateClipPlan(true)">Send to Clip Studio (manual)</button><pre id="clipPlanOut"></pre></div></section>',1)
    page=page.replace('<select id="coverageFeature"><option value="">All features</option>', '<select id="coverageStatus"><option value="">All statuses</option><option>MISSING</option><option>REQUESTED</option><option>RESULT_AVAILABLE</option><option>NEEDS_VALIDATION</option><option>PARTIAL</option><option>FAILED</option><option>STALE</option></select> <select id="coverageFeature"><option value="">All features</option>',1)
