    page=page.replace('<label><input id="meta" type="checkbox" checked> Refresh YouTube metadata</label>', '<label><input id="artifactManifest" type="checkbox"> Create / refresh cached list of files present and missing in every selected video folder</label><label><input id="meta" type="checkbox" checked> Refresh YouTube metadata</label>')
