def sync_library_markers_to_db():
    con=db_connect()
    rows=con.execute("SELECT video_id,local_folder FROM videos").fetchall()
    for vid,folder in rows:
        if not folder:
            continue
        p=Path(folder)
        if not p.exists():
            continue
        con.execute(
            "UPDATE videos SET favorite=?,archived=? WHERE video_id=?",
            (1 if (p/".favorite").exists() else 0,1 if (p/".archive").exists() else 0,vid)
        )
    con.commit()
    con.close()


def _phase5_time_to_seconds(value):
    s=str(value or "")
    m=re.search(r"(?<!\d)(\d{1,2}):(\d{2}):(\d{2})(?!\d)",s)
    if m:
        return int(m.group(1))*3600+int(m.group(2))*60+int(m.group(3))
    m=re.search(r"(?<!\d)(\d{1,3}):(\d{2})(?!\d)",s)
    if m:
        return int(m.group(1))*60+int(m.group(2))
    return None


def phase5_find_timestamp(video_id,query):
    vid=str(video_id or "")
    qtokens=phase5_tokens(query)
    if not qtokens:
        return None
    con=db_connect()
    row=con.execute(
        "SELECT transcript_original,transcript_clean,report_html FROM videos WHERE video_id=?",
        (vid,)
    ).fetchone()
    con.close()
    if not row:
        return None
    p=Path(row[0] or row[1] or "")
    if not p.exists():
        return None
    lines=p.read_text(encoding="utf-8",errors="replace").splitlines()
    for i,line in enumerate(lines):
        low=line.lower()
        if not any(q in low for q in qtokens):
            continue
        for j in range(i,max(-1,i-5),-1):
            sec=_phase5_time_to_seconds(lines[j])
            if sec is not None:
                return {"seconds":sec,"text":re.sub(r"\s+"," ",line).strip(),"report_html":row[2] or ""}
    return None


def backfill_downloaded_at_from_media():
    """
    For existing downloaded videos, infer downloaded_at from media file mtime
    only when downloaded_at is blank.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,local_video,downloaded_at FROM videos WHERE downloaded=1"
    ).fetchall()
    updated=0
    for vid,local_video,downloaded_at in rows:
        if downloaded_at:
            continue
        try:
            p=Path(local_video or "")
            if p.exists():
                stamp=time.strftime("%Y-%m-%d %H:%M:%S",time.localtime(p.stat().st_mtime))
                con.execute("UPDATE videos SET downloaded_at=? WHERE video_id=?",(stamp,vid))
                updated+=1
        except Exception:
            pass
    con.commit()
    con.close()
    return updated


def set_video_library_state(video_id,action,value=None):
    vid=str(video_id or "").strip()
    if not vid:
        return False,"Missing Video ID"

    con=db_connect()
    row=con.execute("SELECT local_folder,favorite,watched,user_rating,archived FROM videos WHERE video_id=?",(vid,)).fetchone()
    if not row:
        con.close()
        return False,"Video not found"

    folder=Path(row[0]) if row[0] else None
    try:
        if action=="favorite":
            val=1 if bool(value) else 0
            con.execute("UPDATE videos SET favorite=? WHERE video_id=?",(val,vid))
            if folder and folder.exists():
                marker=folder/".favorite"
                if val: marker.write_text("",encoding="utf-8")
                elif marker.exists(): marker.unlink()

        elif action=="watched":
            val=1 if bool(value) else 0
            con.execute("UPDATE videos SET watched=? WHERE video_id=?",(val,vid))

        elif action=="rating":
            try: val=max(0,min(5,int(value)))
            except Exception: val=0
            con.execute("UPDATE videos SET user_rating=? WHERE video_id=?",(val,vid))

        elif action=="archive":
            val=1 if bool(value) else 0
            con.execute("UPDATE videos SET archived=? WHERE video_id=?",(val,vid))
            if folder and folder.exists():
                marker=folder/".archive"
                if val: marker.write_text("",encoding="utf-8")
                elif marker.exists(): marker.unlink()
        else:
            con.close()
            return False,f"Unknown action: {action}"

        con.commit()
        con.close()
        return True,"Updated"
    except Exception as ex:
        con.close()
        return False,f"{type(ex).__name__}: {ex}"


