def video_support_path_audit(video_id):
    con=db_connect()
    row=con.execute(
        "SELECT local_folder,clean_title,original_title,upload_date,channel FROM videos WHERE video_id=?",
        (str(video_id),)
    ).fetchone()
    con.close()

    if not row:
        print(f"Video ID not found: {video_id}")
        return False

    folder=row[0] or str(video_folder_path(
        row[1] or row[2] or video_id,
        row[3] or "",
        row[4] or "",
        video_id
    ))

    print("")
    print("===== VIDEO SUPPORT PATH AUDIT =====")
    print(f"Video ID: {video_id}")
    print(f"Folder length {len(folder)}: {folder}")
    names=[
        f"{video_id}.transcript_timestamped.txt",
        f"{video_id}.transcript_clean.txt",
        f"{video_id}.en.srt",
        "ERROR.txt",
        f"{video_id}.info.json"
    ]
    for name in names:
        p=Path(folder)/"_data"/name
        print(f"{len(str(p)):3} | {p}")
    return True


def folder_title_length_audit():
    """
    Audit existing managed video folders against:
      - title portion <= 50 characters
      - full path <= Windows safe path budget
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    problems=[]
    checked=0

    for vid,folder in rows:
        if not folder:
            continue
        p=Path(folder)
        if not p.exists():
            continue

        checked+=1
        title_part=re.sub(
            r"^\d{4}-\d{2}-\d{2}\s+-\s+",
            "",
            p.name
        )

        if (
            len(title_part)>MAX_VIDEO_TITLE_CHARS
            or len(str(p))>WINDOWS_SAFE_PATH_BUDGET
        ):
            problems.append(
                (vid,len(title_part),len(str(p)),str(p))
            )

    print("")
    print("===== FOLDER TITLE / WINDOWS PATH AUDIT =====")
    print(f"Checked: {checked}")

    if not problems:
        print(
            "PASS: all existing folder title portions are within "
            f"{MAX_VIDEO_TITLE_CHARS} characters and paths are within "
            f"{WINDOWS_SAFE_PATH_BUDGET} characters."
        )
        return True

    for vid,title_len,path_len,path in problems:
        print(
            f"{vid} | title={title_len} | path={path_len} | {path}"
        )

    print(f"Problems: {len(problems)}")
    return False

def windows_long_path_audit():
    """
    Find managed files/directories whose paths are likely to exceed classic
    Windows API limits.
    """
    threshold=235
    hits=[]

    for base in [DOWNLOADS,BASE/"tmp",BASE/"data",BASE/"maintenance"]:
        if not Path(base).exists():
            continue
        try:
            for p in Path(base).rglob("*"):
                plen=len(str(p))
                if plen>threshold:
                    hits.append((plen,str(p)))
        except Exception:
            pass

    hits.sort(reverse=True)

    print("")
    print("===== WINDOWS LONG PATH AUDIT =====")
    if not hits:
        print(f"PASS: no managed paths longer than {threshold} characters.")
        return True

    print(f"Found {len(hits)} path(s) longer than {threshold} characters.")
    for plen,p in hits[:50]:
        print(f"{plen:3} | {p}")
    if len(hits)>50:
        print(f"... plus {len(hits)-50} more")
    return False

