def original_title_reference_audit():
    """
    Runtime-facing audit for marker compatibility.
    Reports video folders where no marker exists; does not fail downloads.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,original_title,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    missing=[]
    for vid,orig,db_folder in rows:
        folder=locate_existing_folder(vid)
        if folder is None and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)
        if not folder:
            continue
        marker=find_original_title_marker(folder)
        if marker is None:
            missing.append((vid,str(folder),orig or ""))

    print("")
    print("===== ORIGINAL-TITLE REFERENCE AUDIT =====")
    if not missing:
        print("PASS: every existing video folder has an original-title marker or fallback.")
        return True

    for vid,folder,orig in missing:
        print(f"MISSING {vid} | {folder}")
    print(f"Missing markers: {len(missing)}")
    print("These are non-fatal in FIX17.")
    return False

def original_title_marker_audit():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,original_title,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    missing=0
    empty=0
    ok=0

    for vid,orig,db_folder in rows:
        folder=locate_existing_folder(vid)
        if folder is None and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)
        if folder is None:
            continue

        marker=find_original_title_marker(folder)
        if not marker:
            missing+=1
            print(f"MISSING {vid}: no .original-title marker")
            continue

        value=read_original_title_marker(folder,"")
        if not value:
            empty+=1
            print(f"EMPTY {vid}: {marker}")
        else:
            ok+=1

    print("")
    print("Original-title marker audit")
    print(f"OK      : {ok}")
    print(f"Missing : {missing}")
    print(f"Empty   : {empty}")

def v25_static_integrity_check():
    checks=[]

    def add(name,ok,detail=""):
        checks.append((name,"PASS" if ok else "FAIL",detail))

    add("Project app.py", (BASE/"app"/"app.py").exists(), str(BASE/"app"/"app.py"))
    add("Config", (BASE/"app"/"config.json").exists(), str(BASE/"app"/"config.json"))
    add("urls.txt at root", URLS.exists(), str(URLS))
    add("api_key.txt at root", (BASE/"api_key.txt").exists(), str(BASE/"api_key.txt"))
    add("Database directory", DB.parent.exists(), str(DB.parent))
    add("Phase2 package folder", phase2_chatgpt_dirs()[0].exists(), str(phase2_chatgpt_dirs()[0]))
    add("Phase2 results folder", phase2_chatgpt_dirs()[1].exists(), str(phase2_chatgpt_dirs()[1]))
    add("Auto post-ChatGPT pipeline", CFG.get("auto_post_chatgpt_pipeline",False), "")
    add("Dashboard auto launch disabled", not CFG.get("dashboard_auto_launch",False), "")
    add("No stale legacy root files", v25_path_compatibility_audit(), "")

    print("")
    print("===== V25 STATIC INTEGRITY CHECK =====")
    for name,status,detail in checks:
        print(f"{status:<4} | {name} | {detail}")
    return all(status=="PASS" for _,status,_ in checks)

